class Main {
  import java.io._
  import java.util.StringTokenizer

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N = ni()
    val A = na(N)
    val B = na(N)

    val sumA = sumL(A)
    val sumB = sumL(B)
    if (sumA < sumB) out.println(-1)
    else {
      val minus = ArrayBuffer[Int]() // index
      val plus = mutable.PriorityQueue[Int]() // 数値。降順なのでscalaのでいい
      REP(N) { i =>
        if (A(i) < B(i)) minus += i
        if (A(i) > B(i)) plus += A(i) - B(i)
      }

      var pCnt = 0
      var remain = 0L
      REP(minus.length) { i =>
        val id = minus(i)
        val v = B(id) - A(id)
        while (remain < v) {
          remain += plus.dequeue()
          pCnt += 1
        }
        remain -= v
      }

      out.println(pCnt + minus.length)
    }
  }


  def debug(as: Array[Boolean]): Unit = {
    System.err.println(as.map(x => if(x) "1" else "0").mkString)
  }

  def debug(as: Array[Int]): Unit = {
