		scanf("%lld", &A[i]);
	}
	for (int i = 0; i < N; i++) {
		scanf("%lld", &B[i]);
	}

	ans = 0;

	/*A_i < B_iとなってる分差の和を計算*/
	to_fix = 0;
	for (int i = 0; i < N; i++) {
		if (A[i] < B[i]) {
			to_fix += B[i] - A[i];
			ans++;
		}
	}

	/*A_i > B_iとなってる分を取得*/
	for (int i = 0; i < N; i++) {
		diff[i] = A[i] - B[i];
	}
