		printf("0\n");
		return 0;
	}
	for (int i = 0; i < N; i++) {
		if (diff[i] <= 0) {
			printf("-1\n");
			return 0;
		}
		to_fix -= diff[i];
		if (to_fix <= 0) {
			ans += i + 1;
			break;
		}
	}
	if (to_fix > 0) {
		printf("-1\n");
		return 0;
	}
	printf("%lld\n", ans);
	return 0;
}

