            //backpointerが十分大きい
            if((diff[backpointer] + diff[i]) > 0){
                //backpointerを分け与えて次へ。
                diff[backpointer] += diff[i];
                diff[i] = 0;
                continue;
            }else{
                //backpointerの限界まで分けて次のbackpointerへ
                diff[i] += diff[backpointer];
                diff[backpointer] = 0;
                backpointer--;
                i--;
                continue;
            }
        } 
    }

    //変化があった数をカウントして表示する
    int counter=0;
    for(int i=0; i<N; i++){
        if(diff[i] != diffbefore[i]){ counter++; }
    }
    cout << counter << endl;

    return 0;
}

