void solve(long long N, vector<long long> A, vector<long long> B){
  long long suma = accumulate(A.begin(), A.end(), 0);
  long long sumb = accumulate(B.begin(), B.end(), 0);
  if (suma < sumb) {
    std::cout << -1 << std::endl;
    return;
  }
  bool flag = true;
  for (int i = 0; i < N; i++) {
    if (A[i] < B[i]) {
      flag = false;
    }
  }
  if (flag) {
    std::cout << 0 << std::endl;
    return;
  }
  vector<long long> diff(N, 0);
  for (int i = 0; i < N; i++) {
    diff[i] = A[i] - B[i];
  }
  sort(diff.begin(), diff.end());
  long long minus_amount = 0;
  long long ret = 0;
  for (int i = 0; i < N; i++) {
    if (diff[i] < 0) {
      minus_amount += diff[i];
      ret++;
    } else {
      break;
    }
  }
  for (int i = N-1; i >= 0; i--) {
    minus_amount += diff[i];
    ret++;
    if (minus_amount >= 0) {
      std::cout << ret << std::endl;
      return;
    }
  }
}

