		tmp_k = 0;
		etdfs(root, -1);
	}

	vector<vector<int>> children() {
		assert(root >= 0);
		auto ret = make_v<vector<int>>(size);
		REP(i, size) {
			int prt = p[i];
			if (prt == -1) continue;
			ret[prt].push_back(i);
		}
		return ret;
	}

	int stronglyConnectedConponent() {
		auto rto = make_v<vector<int>>(size);
		REP(from, size) {
			for (auto&& t : to[from])
				rto[t].push_back(from);
		}
		auto cmp = make_v<int>(size);
		fill_v(cmp, 0);
		auto used = make_v<char>(size);
		fill_v(used, 0);
		vector<int> rets; // return index in order
		REP(i, size) {
			makeFixPoint([&](auto dfs, int v) -> void {
				if (used[v]) return;
				used[v] = 1;
				for (auto&& t : to[v])
					dfs(t);
				rets.push_back(v);
			})(i);
		}
		fill_v(used, 0);
		int ret = 0;
		REPR(i, rets.size()-1) {
			makeFixPoint([&](auto rdfs, int v, int k) -> void {
				if (used[v]) return;
				used[v] = 1;
				cmp[v] = k;
				for (auto&& rt : rto[v])
						rdfs(rt, k);

				rets.push_back(v);
			})(rets[i], ret++);
		}
		return ret;
	}

	vector<int> topologicalSorted() {
		vector<int> ret;
		auto used = make_v<char>(size);
		fill_v(used, 0);
		REP(i, size) {
			makeFixPoint([&](auto dfs, int v) -> void {
				if (used[v]) return;
				used[v] = 1;
				for (auto&& t : to[v]) 
					dfs(t);
				ret.push_back(v);
			})(i);
		}
		reverse(all(ret));
		return ret;
	}

	int size, root;
	vector<int> p; // parent for each node. parent of root = -1
	vector<int> depth; // for each node. depth of root node = 0
	vector<int> euler_tour;
	vector<int> et_begin, et_end;
	set<int> leaf_idx;

	int tmp_k;
private:	

	void etdfs(int vidx, int pidx) {
		et_begin[vidx] = tmp_k;
		euler_tour.push_back(vidx);
		tmp_k++;
		REP(i, to[vidx].size()) {
			if (to[vidx][i] != pidx) {
				etdfs(to[vidx][i], vidx);
				euler_tour.push_back(vidx);
				tmp_k++;
			}
		}
		et_end[vidx] = tmp_k;
	}
};

