int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}


ll solve(int N, vi& a, vi& b) {
    ll mq = 0;
    int X = 0;
    vi over;
    rep(i,N){
        if (a[i] < b[i]) {
            mq += b[i] - a[i];
            ++X;
        } else if (a[i] > b[i]) {
            over.pb(a[i] - b[i]);
        }
    }
    sort(ALL(over)); reverse(ALL(over));
    if (mq > accumulate(ALL(over), 0LL)) return -1;

    int i = 0;
    while (mq > 0) {
        mq -= over[i++];
        ++X;
    }
    return X;
}

