#include <bits/stdc++.h>
using namespace std;
int main() {
	int N;
	int i,j,k,acount=0,atotal=0,ccount=0,flg;
	cin >> N;
	vector <int> A(N);
	vector <int> B(N);
	vector <int> C(N);
	for (i = 0; i < N; i++) {
		cin >> A.at(i);
	}
	for (i = 0; i < N; i++) {
		cin >> B.at(i);
		k = A.at(i) - B.at(i);
		if(k < 0) {
			acount++;
			atotal-=k;
		}
		else if(k > 0) {
			C.at(ccount) = k;
			ccount++;
		}
	}
	if(acount == 0) {
		cout << acount << endl;
		return 0;
	}
	flg = 1;
	while(flg == 1) {					// C：準備度余分数を降順ソート
		flg = 0;
		for(i = 1;i<ccount;i++) {
			if(C.at(i) > C.at(i-1)) {		// Cの後の方が大きい場合は入れ替えて、入替フラグを1
				j = C.at(i);
				C.at(i) = C.at(i-1);
				C.at(i-1) = j;
				flg = 1;
			}
		}
	}
	i = 0;
	while ((i < ccount) && (atotal > 0)) {		// 準備不測数合計が0以下になるまで
		atotal-=C.at(i);			// 不足準備数合計から準備度余分数を大きい方から減じる
		i++;					// 不足準備度を補う為に使用された準備度余分試験数
	}
	if(atotal > 0) {
		cout << "-1" << endl;
	}
	else {
		cout << (acount + i) << endl;
	}
	return 0;
}

