  for (auto& a : A) { cin >> a; }
  vector<ll> B(N);
  for (auto& b : B) { cin >> b; }
  vector<ll> C(N);
  vector<ll> minus{}, plus{};
  for (int i = 0; i < N; ++i) {
    C[i] = A[i] - B[i];
    if (C[i] < 0) {
      minus.push_back(C[i]);
    } else if (C[i] > 0) {
      plus.push_back(C[i]);
    }
  }
  auto hunowa = std::accumulate(minus.begin(), minus.end(), 0LL);
  if (hunowa == 0) {
    cout << 0 << CRLF;
