  vector<ll> P_SUM(plus.size());
  boost::partial_sum(plus, P_SUM.begin());
  for (int i = 0; i < plus.size(); ++i) {
    if (P_SUM[i] >= hunowa) {
      cout << (i+1 + minus.size()) << CRLF;
      return;
    }
  }
  cout << -1 << CRLF;
  return;
}

