[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);
    auto B = RD_VEC(N);

    vector<i64> v(N);
    REP(i, N) {
        v[i] = A[i] - B[i];
    }
    ALL(sort, v);
    DBG(v);

    vector<bool> changed(N, false);
    i64 l = 0;
    i64 r = N-1;
    for(;;) {
        if(v[r] <  0) impossible();
        if(v[l] >= 0) break;
        // この時点で v[l] < 0, v[r] >= 0

        if(v[l] + v[r] >= 0) {
            v[r] += v[l];
            v[l]  = 0;
            changed[l] = true;
            changed[r] = true;
            ++l;
        }
        else {
            v[l] += v[r];
            v[r]  = 0;
            changed[l] = true;
            changed[r] = true;
            --r;
        }
    }
    DBG(v);

    i64 ans = ALL(count, changed, true);

    PRINTLN(ans);
}

