void built(int start,int end,int index)
{
	if(start==end)
	{
		tree[index]=pa[start].ss;
		return;
	}
	int mid=(start+end)/2;
	built(start,mid,2*index);
	built(mid+1,end,2*index+1);
	tree[index]=max(tree[2*index],tree[2*index+1]);
}
void update(int start,int end,int index,int ind,int val)
{
	if(start==end)
	{
		tree[index]=val;
		return;
	}
	int mid=(start+end)/2;
	if(ind<=mid)update(start,mid,2*index,ind,val);
	else update(mid+1,end,2*index+1,ind,val);
	tree[index]=max(tree[2*index],tree[2*index+1]);
}
int search(int start,int end,int index,int val)
{
	if(start==end)
	{
		return start;
	}
	int mid=(start+end)/2;
	if(tree[2*index]>=val)return search(start,mid,2*index,val);
	return search(mid+1,end,2*index+1,val);
}
