  for (int i = 0; i < N; i++) { cin >> A[i]; sum_A += A[i]; }
  for (int i = 0; i < N; i++) { cin >> B[i]; sum_B += B[i]; }

  if (sum_A < sum_B) { cout << -1 << endl; return 0;}

  vector<int> sub_neg, sub_pos;
  ll sum_neg = 0;
  for (int i = 0; i < N; i++) {
    ll sub = A[i] - B[i];
    if (sub < 0) { sub_neg.push_back(sub); sum_neg += sub; }
    else sub_pos.push_back(sub);
  }

  ll ans = sub_neg.size();
  sort(sub_pos.begin(), sub_pos.end(), greater<ll>());

  ll sum_pos = 0;
  int i = 0;
  while (sum_pos < -sum_neg) {
    ans ++;
    sum_pos += sub_pos[i];
    i ++;
  }

  cout << ans << endl;

  return 0;
}

#include <stdio.h>
