int N;
long long A[10001];
long long B[10001];

long long diff[10001];

int main(int argc, char const *argv[]) {
	int i, j;
	scanf("%d", &N);

	for (i = 0; i < N; i++) {
		scanf("%lld", &A[i]);
	}

	for (i = 0; i < N; i++) {
		scanf("%lld", &B[i]);

		diff[i] = A[i] - B[i];
	}

	std::sort(diff, diff+N);

	if (0 <= diff[0]) {
		printf("0\n");
		return 0;
	}

	for (i = 0, j = N-1; i < j && diff[i] < 0; i++) {
		if (-diff[i] < diff[j]) {
			diff[j] += diff[i];
		} else {
			diff[i] += diff[j];
			diff[j] = 0;
			j--;

			if (diff[j] <= 0) {
				printf("-1\n");
				return 0;
			}
		}
	}

	printf("%d\n", i+(N-j));

	return 0;
}

