  for (int i = 0; i < n; ++ i) {
    scanf("%d", a + i);
  }
  int result = 0;
  LL left = 0;
  std::vector<int> surplus;
  for (int i = 0; i < n; ++ i) {
    scanf("%d", b + i);
    if (a[i] < b[i])
      left += b[i] - a[i], ++ result;
    else if (a[i] > b[i])
      surplus.emplace_back(a[i] - b[i]);
  }
  std::sort(surplus.begin(), surplus.end());
  while (left > 0 && !surplus.empty()) {
    int w = surplus.back();
    surplus.pop_back();
    left -= w;
    ++ result;
  }
  if (left > 0) {
    puts("-1");
  } else {
    printf("%d\n", result);
  }
}

