  }

  priority_queue<ll> pq;
  ll del_sum = 0ll;
  int ans = 0;
  rep(i, n) {
    if(a[i] >= b[i]) pq.push(a[i]-b[i]);
    else {
      ++ans;
      del_sum += b[i]-a[i];
    }
  }

