                ans++;
                scnt += B[i] - A[i];
            }
        }

        vector<int> C(N);
        rep(i, N) {C[i] = max(A[i] - B[i], 0);}
        sort(all(C), greater<int>());

        rep(i, N) {
            if(scnt <= 0) break;
            scnt -= C[i];
            ans++;
        }
        coi(ans);

    }

}

