    }else if(A[i] > B[i]){
      AB.push(A[i] - B[i]);
    }
  }
  if(m_sum == 0){
    cout << 0 << endl;
    return 0;
  }
  int p_cnt = 0;
  while (!AB.empty()){
    m_sum -= AB.top(); AB.pop();
    p_cnt++;
    if(m_sum <= 0) break;
  }
  if(m_sum > 0){
    cout << -1 << endl;
  }else{
    cout << m_cnt + p_cnt << endl;
  }
}

