			break;
		}
	}
	if (flag) {
		cout << 0 << en;
		return 0;
	}

	vector<ll> diff(n), plus;
	ll ans = 0;
	ll sum_diff = 0;

	rep(i, n) {
		diff[i] = a[i] - b[i];
		if (diff[i] < 0) {
			ans++;
			sum_diff += -diff[i];
		}
		else {
			plus.push_back(diff[i]);
		}
	}

	sort(plus.begin(), plus.end());
	reverse(plus.begin(), plus.end());

	ll sum_plus = 0;

	for (int i = 0; i < plus.size(); i++) {
		sum_plus += plus[i];
		ans++;
		if (sum_plus >= sum_diff) {
			break;
		}
	}

	cout << ans << en;
	return 0;
