    if (sum_margin < sum_lack) ans = -1;
    else {
        ans += lower_bound(cumulative_sum.begin(), cumulative_sum.end(), sum_lack) - cumulative_sum.begin();
    }
    if (all_ok) ans = 0;
    cout << ans << endl;
}

