void solve(ll N, vector<ll> A, vector<ll> B) {
  ll asum = accumulate(ALL(A), 0LL);
  ll bsum = accumulate(ALL(B), 0LL);
  if (asum < bsum) {
    cout << -1 << endl;
    return;
  }
  vector<ll> vec;
  int res = 0;
  ll sum = 0;
  REP(i,N) {
    if (A[i] < B[i]) {
      sum += B[i] - A[i];
      ++res;
    }
    else vec.emplace_back(A[i] - B[i]);
  }
  sort(ALL(vec));
  while (sum > 0) {
    sum -= vec.back();
    vec.pop_back();
    ++res;
  }
  cout << res << endl;
}

