int main() {
	// 入力
	ll N;
	cin >> N;
	ll A[N],B[N];
	for (ll i = 0; i < N; ++i) cin >> A[i];
	for (ll i = 0; i < N; ++i) cin >> B[i];

	// 解法
	ll diff[N];
	REP(i,N) diff[i] = A[i] - B[i];
	sort(diff, diff + N);
	ll n_minus = 0;
	ll total_minus = 0;
	REP(i,N){
		if (diff[i]<0){
			n_minus++;
			total_minus -= diff[i];
		} 
		else break;
	}
	ll acc[N-n_minus];
	REP(i,N-n_minus){
		if (i==0) acc[i] = diff[N-i-1];
		else acc[i] = acc[i-1] + diff[N-i-1];
	}
	// printf("n minus %lld\n", n_minus);
	// printf("total minus %lld\n", total_minus);
	// REP(i,N-n_minus){
	// 	printf("%lld ", acc[i]);
	// }
	printf("\n");
	ll ans = -1;
	REP(i,N-n_minus){
		if (total_minus <=acc[i]){
			ans = i+1 + n_minus;
			break;
		}
	}
	if (total_minus==0) ans = 0;

	//出力
	cout << ans << endl;
}

