    }
    vector<int64_t> plus;
    int64_t sumOfMinus = 0;
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int64_t diff = a[i] - b[i];
        if (diff < (int64_t)0) {
            sumOfMinus -= diff;
            ans++;
        } else if (diff > (int64_t)0) {
            plus.push_back(diff);
        }
    }
    sort(plus.rbegin(), plus.rend());
    for (int i = 0; i < plus.size() && sumOfMinus > (int64_t)0; i++) {
        sumOfMinus -= plus[i];
        ans++;
    }
    if (sumOfMinus > (int64_t)0) ans = -1;
    cout << ans << endl;
}

