    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];

    vector<int> over;
    int64_t sum = 0, lack = 0;
    int ans = 0;
    for(int i=0; i<N; i++){
        sum += A[i] - B[i];
        if(A[i] > B[i]){
            over.push_back(A[i] - B[i]);
        }else if(A[i] < B[i]){
            ans++;
            lack += B[i] - A[i];
        }
    }

    if(sum < 0){
        cout << -1 << endl;
        return 0;
    }

    sort(over.rbegin(), over.rend());
    for(auto a : over){
        if(lack <= 0) break;
        lack -= a;
        ans++;
    }
    cout << ans << endl;
    return 0;
}

