int N;
int minuscnt;
int totalminus;
bool isOK(int index) {
    ll sum = 0;
    if(index <= minuscnt) {
        return false;
    }
    index -= minuscnt;
    REP(i, index) {
        sum += C[N - 1 - i];
        if(sum >= -totalminus) {
            return true;
        }
    }
    return false;
}

// 汎用的な二分探索のテンプレ
ll binary_search(void) {
    ll ng = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
    ll ok = N; // 「index =
               // a.size()-1」が条件を満たさないこともあるので、初期値は
               // a.size()

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while(abs(ok - ng) > 1LL) {
        ll mid = (ok + ng) / 2LL;

        if(isOK(mid))
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

