        cout << 0 << endl;
    }else{
        ll sum = 0;
        int ans = 0;
        for(; ans < surplus.size();){
            sum += surplus[ans++];
            if(sum >= lack) break;
        }

        if(sum >= lack) cout << ans+lacknum << endl;
        else cout << -1 << endl;
    }
    return 0;
}

