using namespace std;
typedef long long ll;
#define rep(i, n) for(ll i = 0, i##_len = (n); i < i##_len; i++)
#define reps(i, s, n) for(ll i = (s), i##_len = (n); i < i##_len; i++)
#define rrep(i, n) for(ll i = (n) - 1; i >= 0; i--)
#define rreps(i, e, n) for(ll i = (n) - 1; i >= (e); i--)
#define all(x) (x).begin(), (x).end()
#define sz(x) ((ll)(x).size())
#define len(x) ((ll)(x).length())

struct S {
    ll a, b, diff;

    bool operator<(const S &b) const {
        return diff > b.diff;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    // std::ifstream in("input.txt");
    // std::cin.rdbuf(in.rdbuf());
    ll n;
    cin >> n;
    vector<S> exam(n);
    rep(i, n) cin >> exam[i].a;
    rep(i, n) cin >> exam[i].b;
    rep(i, n) exam[i].diff = exam[i].a - exam[i].b;
    sort(all(exam));
    deque<pair<ll, bool>> dq;
    ll cnt = 0;
    rep(i, n) {
        if (exam[i].diff == 0) {
            continue;
        }
        else if (exam[i].diff > 0) {
            dq.push_back(make_pair(exam[i].diff, false));
            cnt++;
        }
        else {
            while(exam[i].diff < 0) {
                // printf("i=%lld, v=%lld\n", i, exam[i].diff);
                if (sz(dq) == 0) {
                    cout << -1 << endl;
                    return 0;
                }
                pair<ll, bool> p = dq.front(); dq.pop_front();
                ll a = min(abs(exam[i].diff), p.first);
                exam[i].diff += a;
                p.first -= a;
                p.second = true;
                if (p.first > 0) dq.push_front(p);
            }
            cnt++;
        }
    }
    ll ans = cnt - sz(dq);
    rep(i, sz(dq)) {
        if (dq[i].second) ans++;
    }
    cout << ans << endl;
    return 0;
}

