    for(int i = 0;i < N;i++) {
        cnt.at(i) = A.at(i) - B.at(i);
    }
    int ret = 0;
    sort(cnt.begin(),cnt.end());
    ll cnt2 = 0;
    for(int i = 0;i < N;i++) {
