        }
        else if(a > b){
            M.push_back(a - b);
            //cout << "m" << endl;
            //D[i] = 0;
            //pass++;
        }
        //else cout << 0 << endl;
    }
    sort(D.begin(), D.end());
    sort(M.rbegin(), M.rend());
    queue<int> QD, QM;
    for(int i = 0; i < D.size(); i++) QD.push(D[i]);
    for(int i = 0; i < M.size(); i++) QM.push(M[i]);
