        return 0;
    }

    if(QM.empty()){
        cout << -1 << endl;
        return 0;
    }
    //cout << 1 << endl;
    while(!QM.empty()){
        if(QD.empty()) break;
        int m_past = 0;
        int m = QM.front(); QM.pop(); pass++;
        m = m + m_past;
        //cout << "m " << m << endl;
        while(!QD.empty()){
            int d = QD.front();
            //cout << "d " << d << endl;
            if(m - d >= 0){
                m = m - d;
                pass++;
                QD.pop();
            }
            else{
                m_past = m;
                break;
            }

        }
    }
