const int nmax = 1e9 + 7;
typedef long long ll;

int main(){

  int N; cin >> N;

  vector <ll> A(N), B(N);
  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < N; i++) cin >> B[i];

  int ans = 0;
  vector <ll> plus, minus;
  ll sump = 0, summ = 0;
  for (int i = 0; i < N; i++){
    if (A[i] == B[i]){
      ans++;
    }else if(A[i] > B[i]){
      plus.push_back(A[i] - B[i]);
      sump += A[i] - B[i];
      ans++;
    }else{
      minus.push_back(B[i] - A[i]);
      summ += B[i] - A[i];
    }
  }

  if (sump < summ){
    cout << -1 << endl;
  }else if (minus.size() == 0){
    cout << 0 << endl;
  }else{
    sort(plus.begin(), plus.end(), greater<ll>());
    sort(minus.begin(), minus.end(), greater<ll>());

    int cnt = 0;
    for (int i = 0; i < plus.size(); i++){
      while (plus[i] >= minus[cnt] && cnt < minus.size()){
        plus[i] -= minus[cnt];
        minus[cnt] = 0;
        cnt++;
      }
      ans--;
      if (cnt == minus.size()){
        break;
      }

      if (plus[i] > 0){
        minus[cnt] -= plus[i];
        plus[i] = 0;
      }
    }

    cout << N - ans << endl;
  }

  return 0;
}

