void solve(ll N, vector<ll> A, vector<ll> B) {
  ll all_score = sum(A);
  ll required = sum(B);

  if (all_score < required) {
    co("-1");
    return;
  }

  ll ans = 0;

  vll diff(N);
  ll not_enough = 0;
  rep(i, N) {
    diff[i] = A[i] - B[i];
    if (diff[i] < 0) {
      not_enough -= diff[i];
      ans++;
    }
  }

  rSort(diff);

  rep(i, N) {
    if (not_enough <= 0) {
      co(ans);
      return;
    }
    not_enough -= diff[i];
    ans++;
  }
}

int main() {
  ll N;
  ignore_ret(scanf("%lld",&N));
  vector<ll> A(N);
  for(int i = 0 ; i < N ; i++){
    ignore_ret(scanf("%lld",&A[i]));
  }
  vector<ll> B(N);
  for(int i = 0 ; i < N ; i++){
    ignore_ret(scanf("%lld",&B[i]));
  }
  solve(N, move(A), move(B));
  return 0;
}

