        return 0;
    }

    ll C[N];
    bool isChanged[N];
    ll lenm, lenp;
    for(ll i = 0; i < N; i++){
        C[i] = A[i] - B[i];
        isChanged[i] = false;
    }
    sort(C, C + N);

    ll give_ind = N - 1;
    ll ans = 0;
    for(ll i = 0; i < N; i++){
        if(C[i] >= 0){
            break;
        }
        while(give_ind > 0){
            if(C[give_ind] + C[i] > 0){
