  for (int i = 0; i < n; ++i) {
    cin >> a[i];
    asum += a[i];
  }

  vector<int> b(n);
  long long bsum = 0;
  for (int i = 0; i < n; ++i) {
    cin >> b[i];
    bsum += b[i];
  }

  if (bsum > asum) {
    puts("-1");
    return 0;
  }

  vector<int> g;
  vector<int> l;
  for (int i = 0; i < n; ++i) {
    int diff = a[i] - b[i];
    if (diff < 0) l.push_back(diff);
    else g.push_back(diff);
  }

  if (g.size() == n) {
    puts("0");
    return 0;
  }

  int cur = 0;
  for (int i = 0; i < (int)l.size(); ++i) {
    while (l[i] < 0) {
      if (abs(l[i]) > g[cur]) {
	l[i] += g[cur];
	cur++;
      } else {
	g[cur] += l[i];
	l[i] = 0;
      }
    }
  }
  int ans = (int)l.size() + cur + 1;
  cout << ans << endl;
  return 0;
}

