int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL); cout.tie(NULL);

	ini(n);
	forn(i, 0, n) in(a[i]);
	forn(i, 0, n) in(b[i]);
	forn(i, 0, n) {
		sa[i] = a[i];
		sb[i] = b[i];
	}	
	sort(alln(sa, n));
	sort(alln(sb, n));
	forn(i, 0, n) {
		if (sa[i] < sb[i]) {
			outn(-1);
			return 0;
		}
	}
	set<pi> fix;
	forn(i, 0, n) if (a[i] >= b[i]) fix.insert(mp(a[i], i));
	forn(i, 0, n) p[i] = i;
	forn(i, 0, n) {
		if (a[p[i]] >= b[i]) continue;
		auto it = lower_bound(all(fix), mp(b[i], 0));
		int pos = (*it).se;
		swap(p[i], p[pos]);
		fix.erase(it);
		fix.insert(mp(a[p[i]], i));
		if (a[i] >= b[p[i]]) fix.insert(mp(a[i], pos));
		forn(i, 0, n) outn(p[i]);
		outn("");
	}
	int ret = 0;
	forn(i, 0, n) if (i != p[i]) ret++;		
	outn(ret);	

	return 0;
}

