template<typename N>
int query(const vector<N>& A, const vector<N>& B)
{
  vector<N> D(A.size());
  long sum = 0;
  for (size_t i = 0; i < A.size(); ++i) {
    D[i] = A[i] - B[i];
    sum += D[i];
  }
  if (sum < 0) return -1;
  sort(D.begin(), D.end());
  int index = 0;
  long value = 0;
  for (size_t i = 0, p = D.size(); i < D.size(); ++i) {
    if (D[i] >= 0) break;
    long d = abs(D[i]);
    ++index;
    while (value < d) {
      --p;
      value += D[p];
      ++index;
    }
    value -= d;
  }
  return index;
}

