  	For(i,n)if(a[i]<b[i])is=true;
  	if(is)
  	{
  		cout<<"-1\n";
  		return 0;
  	}
  	built(1,n,1);
  	bool visit[n];
  	memset(visit,false,sizeof(visit));
  	priority_queue<int> pq,pq1;
  	int ans=0;
  	for(int i=n;i>0;i--)
  	{
  		while(!pq1.empty() && pq1.top()==pq.top())pq1.pop(),pq.pop();
  		if(pa[i].ff<=pa[i].ss)
  		{
  			if(visit[i])pq1.push(pa[i].ss);
  			else visit[i]=true;
  			update(1,n,1,i,0);
  		}
  		else if(!pq.empty() && pq.top()>=pa[i].ff)
  		{
  			pq.pop();
  			if(!visit[i])
  			{
  				update(1,n,1,i,0);
  				visit[i]=true;
  				pq.push(pa[i].ss);
  				ans++;
			}
			else
			{
				pq1.push(pa[i].ss);
			}
		}
  		else
  		{
  			int g=search(1,n,1,pa[i].ff);
  			ans++;
			visit[g]=true;
  			if(!visit[i])visit[i]=true,ans++;
  			update(1,n,1,i,0);
  			update(1,n,1,g,0);
  			pq.push(pa[i].ss);
