        d[i] += d[j];
        if (check1 == 1) {
          ++ans;
          check1 = 0;
        }
        d[j] = 0;
        if (check2 == 1) {
          ++ans;
          check2 = 0;
        }
      } else if (d[i] > 0 && d[j] < 0 && d[i] + d[j] < 0) {
        d[i] = 0;
        if (check1 == 1) {
          ++ans;
          check1 = 0;
        }
        d[j] += d[i];
        if (check2 == 1) {
          ++ans;
          check2 = 0;
        }
      }
      if (d[i] == 0) {
        ++i;
        check1 = 1;
        if (i >= j || d[i] <= 0) {
