LL A[100005];
LL B[100005];

void solve(int ks) {
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%lld", &A[i]);
	}
	for (int i = 0; i < n; i++) {
		scanf("%lld", &B[i]);
	}
	vector<LL> P, N;
	for (int i = 0; i < n; i++) {
		if (A[i] < B[i]) P.push_back(B[i] - A[i]);
		else if (A[i] > B[i]) N.push_back(A[i] - B[i]);
	}
	sort(ALL(P));
	sort(ALL(N));
	reverse(ALL(N));
	LL sumP = 0, sumN = 0;
	for (LL i : P) sumP += i;
	for (LL i : N) sumN += i;
	if (sumN < sumP) {
		printf("-1\n");
		return;
	}
	LL sum = 0;
	for (int i = 0; i < SZ(N); i++) {
		if (sum >= sumP) {
			printf("%d\n", i + SZ(P));
			return;
		}
		sum += N[i];
	}
	printf("%d\n", SZ(N) + SZ(P));
}

