signed main(){
	ll n;
	cin >> n;
	ll a[n],b[n],a_sum = 0,b_sum = 0,ans = 0,c_sum = 0;
	priority_queue<ll, vector<ll> > pq;
	bool flag = false;

	rep(i,0,n){
		cin >> a[i]; //zyunbi
		a_sum += a[i];
	}

	rep(i,0,n){
		cin >> b[i]; //siken
		b_sum += b[i];
		if(b[i] > a[i]){
			c_sum += b[i] - a[i];
			ans++;
			flag = true;
		}
		else{
			pq.push(a[i] - b[i]);
		}
	}

	while(pq.size() > 0 && flag){
		ans++;
		if(pq.top() >= c_sum){
			break;
		}

		c_sum -= pq.top();
		pq.pop();
	}


	if(b_sum > a_sum) cout << -1 << endl;
	else cout << ans << endl;
	return 0;

}

