		if(k < 0) {			// 準備不足
			acount++;		// acount：準備不足な試験数（調整で変更される対象）
			atotal-=k;		// atotal：準備不足数の合計
		}
		else if(k > 0) {		// 準備余裕（不足分を埋める候補）
			C.at(ccount) = k;	// C: 余裕数
			ctotal+=k;
			ccount++;		// ccount：余裕がある試験数
		}
	}
	if(acount == 0) {			// acount=0:全て準備が十分
		cout << acount << endl;		// 変更になる数が0、acountをそのまま出力
		return 0;
	}
	if(atotal > ctotal == 0) {		// 埋めきれない
		cout << "-1" << endl;
		return 0;
	}
	flg = 1;				// 不足を埋める候補を降順ソートする
	while(flg == 1) {
		flg = 0;
		for(i = 1;i<ccount;i++) {
			if(C.at(i) > C.at(i-1)) {
				j = C.at(i);
				C.at(i) = C.at(i-1);
				C.at(i-1) = j;
				flg = 1;
			}
		}
	}
	i = 0;
	while(i < ccount) {
		atotal-=C.at(i);
		if(atotal > 0) {
			i++;
		}
		else {
			break;
		}
	}
	if(atotal > 0) {
		cout << "-1" << endl;
	}
	else {
		cout << (acount + i + 1) << endl;
	}
	return 0;
}

