            ans++;
            sub_sum += (b - a);
        }
        if (a > b) {
            c_arr.push_back(a - b);
        }
    }

    //  合格するのに必要な差分を、いくつの
    //  準備度が高い値で満たせるか

    if (sub_sum == 0) {
        cout << 0 << endl;
    } else {
        sort(c_arr.begin(), c_arr.end(), greater<int>());

        for (int l = 0; l < c_arr.size(); l++) {
            sub_sum -= c_arr[l];
            ans++;
            if (sub_sum <= 0) {
                break;
            }
        }
        cout << ans << endl;
    }
    return 0;
}

