int main() {
  ll n, i, j, cnt = 0, ans = 0;
  cin >> n;
  vector<ll> a(n), b(n), d(n), d_copy(n);
  for (i = 0; i < n; ++i) {
    cin >> a[i];
  }
  for (i = 0; i < n; ++i) {
    cin >> b[i];
  }
  for (i = 0; i < n; ++i) {
    d[i] = a[i] - b[i];
    cnt += d[i];
  }

  if (cnt < 0) {
    ans = -1;
  } else {
    ans = 0;
    sort(d.rbegin(), d.rend());
    d_copy = d;
    i = 0;
    j = n - 1;
    while (i < j) {
      if (d[i] > 0 && d[j] < 0 && d[i] >= -d[j]) {
        d[i] += d[j];
        d[j] = 0;

      } else if (d[i] > 0 && d[j] < 0 && d[i] < -d[j]) {
        d[i] = 0;
        d[j] += d[i];
      }

      if (d[i] <= 0) {
        if (i == n - 1) {
          break;
        }
        ++i;
        if (d[i] <= 0) {
          break;
        }
      }
      if (d[j] >= 0) {
        if (j == 0) {
          break;
        }
        --j;
        if (d[j] >= 0) {
          break;
        }
      }
    }
    for (i = 0; i < n; ++i) {
      if (d[i] != d_copy[i]) {
        ++ans;
      }
    }
  }
  cout << ans << "\n";
