#include <bits/stdc++.h>
using namespace std;
int main() {
	int N;
	int i,j,ta=0,tb=0,acount=0,atotal=0,ctotal=0,ccount=0,flg;
	cin >> N;
	vector <int> A(N);
	vector <int> B(N);
	vector <int> C(N);
	for (i = 0; i < N; i++) {
		cin >> A.at(i);
		ta+=A.at(i);	// ta：準備合計
		C.at(i) = 0;
	}
	for (i = 0; i < N; i++) {
		cin >> B.at(i);
		tb+=B.at(i);	// tb：合格合計
		if(A.at(i) < B.at(i)) {
			acount++;	// acount:不足試験数
			atotal+=(B.at(i)-A.at(i));	// atotal：不足準備数合計
		}
		if(A.at(i) > B.at(i)) {
			C.at(ccount) = A.at(i) - B.at(i);	// C：超過準備数
			ctotal+=C.at(ccount);			// ctotal：超過準備数合計
			ccount++;				// ccount：超過試験数
		}
	}
	if(atotal > ctotal) {		// 不足数合計が超過数合計より大きいので不可能
		cout << "-1" << endl;
	}
	else {
		flg = 1;
		while(flg == 1) {	// C：超過準備数を降順ソート
			flg = 0;
			for(i = 1;i<ccount;i++) {
				if(C.at(i) > C.at(i-1)) {
					j = C.at(i);
					C.at(i) = C.at(i-1);
					C.at(i-1) = j;
					flg = 1;
				}
			}
		}
		i = 0;
		while (atotal > 0) {		// 不足準備数が0以下になるまでループ
			atotal-=C.at(i);	// 不足準備数合計から超過準備数を減じる
			i++;			// 超過準備数で変更になる個数
		}
		j = acount + i;			// acount：補充され変更になる個数、i：補充の為に変更になる個数
		cout << j << endl;
	}
	return 0;
}

