	vector<int> ds(N);
	for (int i = 0; i < N; i++)
		cin >> ps[i].second;
	for (int i = 0; i < N; i++)
		cin >> ps[i].first;
	for (int i = 0; i < N; i++)
	{
		ds[i] = (ps[i].second - ps[i].first);
	}
	sort(ds.begin(), ds.end());

	int l = 0, r = N - 1;
	bitset<100010> used;
	while (l < r)
	{
		if (ds[l] >= 0)
			break;
		if (ds[r] < 0)
		{
			cout << -1 << endl;
			return;
		}
		int x = min(ds[r], -ds[l]);
		ds[r] -= x;
		ds[l] += x;
		used[l] = used[r] = 1;
		if (ds[l] < 0)
		{
			r--;
		}
		else
		{
			l++;
		}
		//cout << l << ' ' << r << endl;
	}

	if (ds[r] < 0)
	{
		cout << -1 << endl;
		return;
	}

	cout << used.count() << endl;
}

