int solve() {
    ll sum_a = 0, sum_b = 0;
    for (int i = 0; i < n; i++) {
        sum_a += a[i];
        sum_b += b[i];
    }
    if (sum_a < sum_b) return -1;

    vector<int> vec(n);
    for (int i = 0; i < n; i++) vec[i] = i;
    sort(ALL(vec), [](int i, int j){ return a[i]-b[i] < a[j]-b[j]; });

    int idx = 0;
    ll lack = 0;
    while (a[vec[idx]] - b[vec[idx]] < 0) {
        lack += b[vec[idx]] - a[vec[idx]];
        idx++;
    }

    int res = idx;
    for (int i = n-1; i >= 0 && lack > 0; i--) {
        lack -= a[vec[i]] - b[vec[i]];
        res++;
    }
    return res;
}

