void Main() {
    i32 N;
    cin >> N;
    Vec<i64> A(N), B(N);
    i64 sumA = 0, sumB = 0;
    for (i32 i = 0; i < N; i++) {
        cin >> A[i];
        sumA += A[i];
    }
    for (i32 i = 0; i < N; i++) {
        cin >> B[i];
        sumB += B[i];
    }
    if (sumA < sumB) {
        cout << -1 << endl;
        return;
    }
    priority_queue<i64> pq;
    for (i32 i = 0; i < N; i++) {
        if (A[i] - B[i] > 0) pq.push(A[i] - B[i]);
    }
    i32 ans = 0;
    i64 current = 0;
    for (i32 i = 0; i < N; i++) {
        if (A[i] >= B[i]) continue;
        ans++;
        while (A[i] < B[i]) {
            if (B[i] - A[i] <= current) {
                current -= B[i] - A[i];
                A[i] = B[i];
            } else {
                ans++;
                current += pq.top();
                pq.pop();
            }
        }
    }
    cout << ans << endl;
}

