long long max_index(long long arr[]){
    long long max = -1000000000000000;
    long long max_i = -1;
    for(int i=0;i<N;i++){
        if(arr[i] >= max){
            max = arr[i];
            max_i = i;
        }
    }
    return max_i;
}

long long solve(){
    long long ret = 0;
    long long D[N]; //A-B
    long long dept = 0;
    long long property = 0;
    for(int i=0;i<N;i++){
        D[i] = A[i] - B[i];
        if(D[i] < 0){
            dept -= D[i];
            ret++;
        }else{
            property += D[i];
        }
    }
    if(dept > property){
        return -1;
    }
    while(dept > 0){
        long long index = max_index(D);
        dept -= D[index];
        D[index] = 0;
        ret++;
    }

    return ret;
}

