    rep(i,0,N) suma+=A[i];
    rep(i,0,N) sumb+=B[i];

    if(suma<sumb){
        cout << -1 << endl;
        return;
    }

    vector<i64> minus,plus;
    rep(i,0,N){
        if(A[i]<B[i]) minus.push_back(B[i]-A[i]);
        if(A[i]>B[i]) plus.push_back(A[i]-B[i]);
    }

    if(minus.size()==0){
        cout << 0 << endl;
        return;
    }

    sort(rbegin(plus),rend(plus));
    i64 i=0,rem=plus[0];
    rep(j,0,minus.size()){
        while(minus[j]){
            if(minus[j]<=rem){
                rem-=minus[j];
                minus[j]=0;
            }else{
                minus[j]-=rem;
                ++i;
                rem+=plus[i];
            }
        }
    }

    cout << minus.size()+i+1 << endl;
}

