bool cmp(int l,int r){
	return (orig[l]-a[l]) <= (orig[r]-a[r]);
}

int main()
{
	int n; cin>>n;
	 bool ok=true;

	for(int i=0;i<n;i++) {cin>>a[i]; orig[i]=a[i];}
	for(int i=0;i<n;i++) cin>>b[i];

	ll d=0;

	for(int i=0;i<n;i++){
		if(a[i]-b[i]>0){
			ll r = a[i]-b[i];
			d += r ; a[i] -= r; c[i]=1;
		}
	}

	for(int i=0;i<n;i++){
		if(c[i]==0){
			ll req = b[i]-a[i];
			a[i] += req;
