    cin >> a[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> b[i];
  }

  vector<int64_t> differences(n);
  for (int i = 0; i < n; i++) {
    differences[i] = a[i] - b[i];
  }
  sort(differences.begin(), differences.end());

  set<int> changed_indices;

  int target = n - 1;
  for (int i = 0; i < n; i++) {
    while (target > i and differences[i] < 0) {
      changed_indices.insert(i);
      int supply = max((int64_t)0, min(-differences[i], differences[target]));

      differences[i] += supply;
      differences[target] -= supply;

      if (supply > 0) {
        changed_indices.insert(target);
      }

      if (differences[target] <= 0) {
        target--;
      }
    }

    if (differences[i] < 0) {
      cout << -1 << endl;
      return 0;
    }
  }
  cout << changed_indices.size() << endl;

  return 0;
}

