int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    vector<ll> as(n); cin >> as;
    vector<ll> bs(n); cin >> bs;
    if(accumulate(as.begin(), as.end(), 0ll) < accumulate(bs.begin(), bs.end(), 0ll)){
        cout << -1 << '\n';
        return 0;
    }
    vector<ll> diffs;
    for(int i = 0; i < n; i++){
        ll diff = as[i] - bs[i];
        if(diff > 0){
            diffs.push_back(diff);
        }
    }
    sort(diffs.begin(), diffs.end());
    bool used = false;
    int cnt = 0;
    for(int i = 0; i < n; i++){
        ll rq = bs[i] - as[i];
        if(rq <= 0){ continue; }
        cnt++;
        while(rq){
            ll mi = min(diffs.back(), rq);
            rq -= mi;
            diffs.back() -= mi;
            used = true;
            if(diffs.back() == 0){
                diffs.pop_back();
                used = false;
                cnt++;
            }
        }
    }
    cout << cnt + used << '\n';
}

