int main() {
    ll n;
    int cont = 0;
    cin >> n;

    unsigned long long a[n], b[n];

    for (int x = 0; x < n; x++)
        cin >> a[x];
    for (int y = 0; y < n; y++)
        cin >> b[y];

    for (int s = 0; s < n; s++) {
        if (a[s] >= b[s]) {
            cont++;
        }
    }

    if (cont == n) {
        cout << 0 << endl;
        return 0;
    }

    cont = 0;

    sort(a, a + n); sort(b, b + n);

    int i = 0, j = 0;
    for (; i < n; i++) {
        if (a[i] >= b[j]) {
            j++;
            cont++;
            cout << i << " : " << j << " = " << cont << endl;
        }
    }

    if ((a[0] < b[0] || a[n - 1] < b[n - 1]) && i == j)
        cout << -1 << endl;

    cout << cont << endl;
}

