    int N;
    cin >> N;
    int answer = 0;
    int A[N];
    int B[N];
    for (int i = 0; i < N; i++)
    {
        cin >> A[i];
    }
    for (int i = 0; i < N; i++)
    {
        cin >> B[i];
    }
    if (accumulate(A, A + N, 0) < accumulate(B, B + N, 0))
    {
        int out = -1;
        cout << out << endl;
        return 0;
    }
    priority_queue<int> amari;
    ll tarinai = 0;
    for (int i = 0; i < N; i++)
    {
        if (A[i] < B[i])
        {
            answer++;
            tarinai += B[i] - A[i];
        }
        else if (A[i] > B[i])
        {
            amari.push(A[i] - B[i]);
        }
    }
    ll sum = 0;
    while (sum < tarinai)
    {
        answer++;
        sum += amari.top();
        amari.pop();
    }
    cout << answer << endl;
    return 0;
}

