inline void finish()
{
  cout << -1 << endl;
  exit(0);
}

int main()
{
  ll n;
  cin >> n;
  ll a[100010], b[100010];
  rep(i, n) cin >> a[i];
  rep(i, n) cin >> b[i];
  vector<ll> savings;  //余裕
  vector<ll> shortage; //不足分
  rep(i, n)
  {
    if (a[i] > b[i])
    {
      savings.push_back(a[i] - b[i]);
    }
    else if (a[i] < b[i])
    {
      shortage.push_back(b[i] - a[i]);
    }
  }
  sort(all(savings), greater<ll>());

  int ans = shortage.size();
  int i = 0;
  bool before_changed = false;
  for (auto &&t : shortage)
  {

    while (t > 0)
    {
      if (i == savings.size())
      {
        finish();
      }
      if (t - savings[i] < 0)
      {
        savings[i] -= t;
        t = 0;
        if (!before_changed)
          ans++;
        before_changed = true;
      }
      else if (t - savings[i] >= 0)
      {
        t -= savings[i];
        i++;
        if (!before_changed)
          ans++;
        before_changed = false;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

