ll sa[101010], sum[101010];

int main() {
    int n;
    cin >> n;
    vector<ll> A(n), B(n);
    rep(i, n) cin >> A[i];
    rep(i, n) cin >> B[i];
    vector<ll> p1, p2;
    rep(i, n) {
        sa[i] = A[i]-B[i];
        if (sa[i] < 0) p1.push_back(-sa[i]);
        else if (sa[i] > 0) p2.push_back(sa[i]);
    }
    sort(p2.rbegin(), p2.rend());
    ll ans = 0;
    for (int i=1; i<=n; ++i) {
        sum[i] = sum[i-1] + sa[i-1];
    }

    if (sum[n] < 0) {
        cout << "-1" << endl;
        return 0;
    }
    if (p1.size() == 0) {
        cout << 0 << endl;
        return 0;
    }

    int idx = 0;
    bitset<101010> used;
    rep(i, p1.size()) {
        if (p1[i] <= p2[idx]) {
            p2[idx] -= p1[i];
            used[idx] = 1;
            if (p2[idx] == 0) idx++;
        }
        else {
            int tmp = p1[i] - p2[idx];
            used[idx++] = 1;
            while (tmp > 0) {
                if (tmp <= p2[idx]) {
                    p2[idx] -= tmp;
                    tmp = 0;
                    used[idx] = 1;
                    if (p2[idx] == 0) {
                        idx++;
                    }
                    break;
                }
                else {
                    int tmp2 = tmp - p2[idx];
                    used[idx] = 1;
                    tmp = tmp2;
                    idx++;
                }
            }
        }
    }

    ans = p1.size() + used.count();
    cout << ans << endl;

}

