struct Node{
    ll d;
    ll i;
    bool operator< (const Node &r) const{
        return d < r.d;
    }
};

int main(){
    ll n;
    cin >> n;
    vector<ll> a(n);
    vector<ll> b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];


    ll asum = 0;
    ll bsum = 0;
    rep(i, n) asum += a[i];
    rep(i, n) bsum += b[i];

    if(asum < bsum){
        cout << -1 << endl;
        return 0;
    }

    vector<ll> c(n);
    rep(i, n) c[i] = a[i];

    priority_queue<Node> que;
    rep(i, n) que.push({c[i]-b[i], i});

    int i = 0;
    ll idx = que.top().i; que.pop();
    while(0 < c[idx]-b[idx]){
        while(i < n){
            ll diff = b[i]-c[i];
            if(c[idx]-b[idx] <= 0) break;
            else if(0 < diff){
                ll add = min(c[idx]-b[idx], diff);
                c[i] += add;
                c[idx] -= add;
            }
            else i++;
        }
        if(i == n) break;
        idx = que.top().i; que.pop();
    }


    ll cnt = 0;
    rep(i, n){
        if(c[i] != a[i]) cnt++;        
    }
    cout << cnt << endl;

    return 0;
}

