#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll solve() {
    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    for ( int i = 0; i < N; i++ ) cin >> A[i];
    for ( int i = 0; i < N; i++ ) cin >> B[i];
    priority_queue<ll> q;
    for ( int i = 0; i < N; i++ ) {
        if ( A[i] > B[i] ) q.push(A[i]-B[i]);
    }
    ll ans = 0, f = 0;
    for ( int i = 0; i < N; i++ ) {
        if ( A[i] < B[i] ) {
            ans++;
            while ( !q.empty() && f < B[i]-A[i] ) {
                f += q.top();
                q.pop();
                ans++;
            }
            if ( q.empty() && f < B[i]-A[i] ) return -1;
            f -= B[i]-A[i];
        }
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

