int Solve(int N, vector<ll> A, vector<ll> B) {
    vector<ll> record;
    ll residue = 0;
    int res = 0;
    for (int i =0; i < N; i++) {
        if (A[i] > B[i]) {
            record.push_back(A[i] - B[i]);
        }
        if (A[i] < B[i]){
            residue += B[i] - A[i];
            res++;
        }
    }
    sort(record.begin(), record.end(), greater<int>());
    int i = 0, n = record.size();
    while (residue > 0 && i < n) {
        residue -= record[i++];
        res++;
    }
    if (residue > 0) {
        return -1;
    }
    return res;
}


