    else
      break;
  }

  // 正のほうが計算しやすい
  sum = -sum;

  // 余剰の準備度から分配していく
  for(int i=N-1; i>=0; i--){
    // 分配し終わった
    if(sum <= 0)
      break;
    // 途中でsub[i]<0になったら100％ムリ
    if(sub[i] < 0){
      cout << -1 << endl;
      return 0;
    }

    // 余剰分を引いていく
    sum -= sub[i];
    ans++;
  }

  // 解答
  cout << ans << endl;

  return 0;
}

