typedef long long int ll;
vector<ll> A, B;
priority_queue<ll> diff;

int N;
ll sum = 0;
ll s = 0;
ll ans = 0;
bool need = false;
void input()
{
    cin >> N;
    for (int i = 0; i < N; i++)
    {
        ll ai;
        cin >> ai;
        A.push_back(ai);
    }
    for (int i = 0; i < N; i++)
    {
        ll bi;
        cin >> bi;
        B.push_back(bi);
    }
    for (int i = 0; i < N; i++)
    {
        if (A[i] - B[i] < 0)
        {
            need = true;
        }
        sum += A[i] - B[i];
        // cout << A[i] - B[i] << endl;
        if (A[i] - B[i] > 0)
        {
            diff.push(A[i] - B[i]);
        }
        else
        {
            s += abs(A[i] - B[i]);
            ans++;
        }
    }
}

void solve()
{
    while (!diff.empty() && s > 0)
    {
        ll front = diff.top();
        // cout << front << endl;

        diff.pop();
        s -= front;
        ans++;
    }
}

int main()
{
    input();

    if (sum < 0)
        cout << -1 << endl;
    else
    {
        if (need)
        {
            solve();
            cout << ans << endl;
        }
        else
            cout << 0 << endl;
    }
}

