		flg = 0;
		for(i = 1;i < N;i++) {
			if(A.at(i) < A.at(i-1)) {
				j = A.at(i);
				A.at(i) = A.at(i-1);
				A.at(i-1) = j;
				j = B.at(i);
				B.at(i) = B.at(i-1);
				B.at(i-1) = j;
				flg = 1;
			}
		}
	}
	for (i = 0; i < N; i++) {
		C.at(i) = A.at(i);
	}
	for(i = 0;i < N;i++) {
		if(C.at(i) < B.at(i)) {			// 準備数不足
			j = i + 1;
			while(j < N) {
				if((C.at(j) >= B.at(i)) && (C.at(i) >= B.at(j))) {
					k = C.at(j);
					C.at(j) = C.at(i);
					C.at(i) = k;
					break;
				}
				j++;
			}
		}

