int main() {
	int N; cin >> N;
	V<ll> A(N), B(N);
	REP(i, N) cin >> A[i];
	REP(i, N) cin >> B[i];
	ll sum = 0, ans = 0;
	REP(i,N) {
		if (A[i] > B[i]) A[i] -= B[i];
		else if(A[i] < B[i]){
			sum += B[i] - A[i];
			A[i] = 0;
			ans++;
		}		
	}
	sort(ALL(A),greater<ll>());
	REP(i,N){
		sum -= A[i];
		ans++;
		if (sum <= 0) break;
	}
	cout << (sum <= 0 ? ans : -1) << endl;

	return 0;
}

