int main(){
    int N;cin>>N;
    vector<int> a(N),b(N);
    for(int i=0;i<N;i++)cin>>a.at(i);
    for(int i=0;i<N;i++)cin>>b.at(i);

    long S=0;
    int count=0;
    vector<int> dif;
    for(int i=0;i<N;i++){
        if(a.at(i)<b.at(i)){
            S+=b.at(i)-a.at(i);
            count++;
        }
        else dif.push_back(a.at(i)-b.at(i));
    }
    int ans=0;
    if(S==0){
        ans=0;
    }
    else{
        sort(dif.begin(),dif.end(),greater<int>());
        for(int i=0;i<dif.size();i++){
            S-=dif.at(i);
            if(S<0){
                ans+=i+1;
                break;
            }
        }
        if(S>0)ans=-1;
        else ans+=count;
    }

    cout<<ans<<endl;

    return 0;
}

