#define MAX_N 100000
int A[MAX_N], B[MAX_N], C[MAX_N];

int main() {
  int N; scanf("%d", &N);
  for (int i{}; i < N; ++i) scanf("%d", &A[i]);
  for (int i{}; i < N; ++i) {
    scanf("%d", &B[i]);
    C[i] = A[i] - B[i];
  }
  sort(C, C + N);

  set<int> mod;
  int i{}, j{N - 1};
  while (i < N && j >= 0 && C[i] < 0 && C[j] > 0) {
    int move = MIN(-C[i], C[j]);
    C[i] += move;
    C[j] -= move;
    mod.insert(i);
    mod.insert(j);
    if (C[i] == 0) ++i;
    if (C[j] == 0) --j;
  }

  printf("%d\n", i < N && C[i] >= 0 ? mod.size() : -1);
  return 0;
}

