using ll = long long;

const ll mod = 1e9+7;
const int maxn = 1e6 + 5;



int n;
ll a[maxn], b[maxn];

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    cin>>n;
    ll tota=0;
    ll totb=0;
    for (int i=0; i<n; i++) {
	cin>>a[i];
	tota+=a[i];
    }
    for (int i=0; i<n; i++) {
	cin>>b[i];
	totb+=b[i];
    }

    if (tota<totb) out(-1);

    priority_queue<ll> pq;
    vector<ll> todo;
    for (int i=0; i<n; i++) {
	if (a[i]-b[i]>0) {
	    pq.push(a[i]-b[i]);
	}
	if (b[i]-a[i]>0) {
	    todo.push_back(b[i]-a[i]);
	}
    }

    int used = todo.size();
    ll cur = 0;

    while (todo.size()) {
	if (cur==0) {
	    assert(pq.size());
	    cur = pq.top();
	    pq.pop();
	    used++;
	}
	ll tmp = min(todo.back(), cur);
	todo.back() -= tmp;
	cur -= tmp;
	if (todo.back()==0) {
	    todo.pop_back();
	}
    }

    cout<<used<<endl;    
    return 0;
}

