	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	for (int i = 0; i < n; i++) {
		cin >> b[i];
		c[i] = a[i] - b[i];
		change[i] = false;
	}

	sort(c, c + n);
	start = 0;
	end = n - 1;

	while (1) {
		if ((start == end && c[start] < 0) || c[end] < 0) {
			check = false;
			break;
		}
		if (c[start] >= 0) { 
			break; 
		}

		if (c[end] + c[start] == 0) {
			c[end] = 0;
			c[start] = 0;
			change[end] = true;
			change[start] = true;
			start++;
			end--;
		}
		else if (c[end] + c[start] > 0) {
			c[end] += c[start];
			c[start] = 0;
			change[end] = true;
			change[start] = true;
			start++;
		}
		else {
			c[start] += c[end];
			c[end] = 0;
			change[end] = true;
			change[start] = true;
			end--;
		}

	}

	count = 0;
	for (int i = 0; i < n; i++) {
		if (change[i]) {
			count++;
		}
	}

	if (check) {
