using namespace std;
typedef long long int ll;
vector<ll> A, B;
deque<ll> diff;

int N;
ll sum = 0;
bool need = false;
void input()
{
    cin >> N;
    for (int i = 0; i < N; i++)
    {
        ll ai;
        cin >> ai;
        A.push_back(ai);
    }
    for (int i = 0; i < N; i++)
    {
        ll bi;
        cin >> bi;
        B.push_back(bi);
    }
    for (int i = 0; i < N; i++)
    {
        if (A[i] - B[i] < 0)
        {
            need = true;
        }
        sum += A[i] - B[i];
        diff.push_back(A[i] - B[i]);
    }
}

int ans = 0;
void solve()
{
    while (!diff.empty())
    {
        ll plus = diff.back();
        diff.pop_back();
        ans++;
        while (plus >= 0)
        {
            ll minus = diff.front();
            diff.pop_front();
            if (minus >= 0)
                return;

            if (plus >= minus)
            {
                plus += minus;
                ans++;
            }
            else
            {
                diff.push_front(plus + minus);
                plus += minus;
                ans++;
            }
        }
    }
}

int main()
{
    input();
    sort(diff.begin(), diff.end());

    if (sum < 0)
        cout << -1 << endl;
    else
    {
        if (need)
        {
            solve();
            cout << ans << endl;
        }
        else
            cout << 0 << endl;
    }
}

