void solve() {
  ll n; cin >> n;
  ll ans = 0, minus = 0;
  vector<ll> a(n);
  vector<P> v(n);
  rep(i, n) cin >> a[i];
  rep(i, n) {
    ll b; cin >> b;
    if (a[i] < b) {
      minus += b - a[i];
      ans++;
    }
    v[i] = make_pair(b - a[i], a[i]);
  }
  sort(v);

  for (int i = 0; i < n && v[i].first < 0 && minus > 0; i++) {
    ll ai = v[i].second;
    ll bi = v[i].first + ai;
    debug2(ai, bi);
    minus -= ai - bi;
    ans++;
  }

  if (minus > 0) outl(-1);
  else outl(ans);
}

