  for (auto const d : ds) {
    if (d >= 0) {
      break;
    }
    move += -d;
    ret++;
  }

  for (auto it = ds.rbegin(); it != ds.rend(); ++it) {
    auto const d = *it;
    move -= d;
    ret++;
    if (move < 0) {
      break;
    }
  }

  return ret;
}

