        cin >> prev[i];
        sumprev += (ll)prev[i];
    }

    vector<int> bord(n, 0);
    ll sumbord = 0;
    vector<int> cost(n, 0);
    // n
    rep(i, 0, n) {
        cin >> bord[i];
        sumbord += (ll)bord[i];
        cost[i] = prev[i] - bord[i];
    }

    if (sumprev < sumbord) {
        cout << -1 << endl;
        return 0;
    }

    // else
    sort(cost.begin(), cost.end());
    vector<int> tmpcost(n, 0);
    // n/2
    copy(cost.begin(), cost.end(), tmpcost.begin());

    int mnsidx = 0;
    int plsidx = n - 1;
    // n/2
    while (cost[mnsidx] < 0 && cost[plsidx] > 0) {
        // for (int c : cost) {
        //     cout << c << " ";
        // }
        // cout << endl;
        // change pls only
        if (abs(cost[mnsidx]) > cost[plsidx]) {
            cost[plsidx] = 0;
            cost[mnsidx] += cost[plsidx];
            plsidx--;
        }
        // change pls and mns
        else if (abs(cost[mnsidx]) == cost[plsidx]) {
            cost[plsidx] = 0;
            cost[mnsidx] = 0;
            mnsidx++;
            plsidx--;
        }
        // change mns only
        else {  // mns < pls
            cost[plsidx] += cost[mnsidx];
            cost[mnsidx] = 0;
            mnsidx++;
        }
