        std::cin >> A[i];
    }

    int64_t total = 0;
    for (int i = 0; i < N; ++i) {
        std::cin >> B[i];
        total += (A[i] - B[i]);
        if (A[i] < B[i]) {
            minus.push_back(B[i] - A[i]);
        } else if (B[i] < A[i]) {
            plus.push_back(A[i] - B[i]);
        }
    }

    if (total < 0) {
        std::cout << -1 << std::endl;
        return 0;
    } else if (minus.size() == 0) {
        std::cout << 0 << std::endl;
        return 0;
    }

    std::sort(plus.begin(), plus.end(), std::greater<uint64_t>());

    int m_pos = 0;
    int p_pos = 0;
    while (m_pos < minus.size()) {
        if (minus[m_pos] <= plus[p_pos]) {
            plus[p_pos] = plus[p_pos] - minus[m_pos];
            ++m_pos;
        } else {
            minus[m_pos] = minus[m_pos] - plus[p_pos];
            ++p_pos;
        }
    }

    std::cout << minus.size() + (p_pos + 1) << std::endl;

