    cin >> tmp;
    sub *= (int)(a[i] - tmp >= 0);
    if(a[i] - tmp > 0) upper.emplace_back(vector<int>({i, a[i] - tmp}));
    else if(a[i] - tmp < 0) under.emplace_back(vector<int>({i, a[i] - tmp}));
  }
