    int upper_res = upper.back()[1], under_res = -under.back()[1];
    upper.pop_back();
    under.pop_back();
    res = 2;
    while (true){
      if (upper_res < under_res){
        if (upper.empty()){
          res = -1;
          break;
        }
        under_res -= upper_res;
        upper_res = upper.back()[1];
        upper.pop_back();
        res++;
      }
      else if (upper_res > under_res){
		if (under.empty()) break;
        upper_res -= under_res;
        under_res = -under.back()[1];
        under.pop_back();
