    return os << '(' << p.first << ',' << p.second << ')';
}


auto solve() {
    int n;
    cin >> n;
    vi A(n), B(n);
    for (auto &&e: A) cin >> e;
    for (auto &&e: B) cin >> e;

    ll sumA = accumulate(all(A), 0ll);
    ll sumB = accumulate(all(B), 0ll);

    if (sumA < sumB) return -1;

    vi T(n);
    REP(i, n) {
        T[i] = A[i] - B[i];
    }
    sort(all(T));

    ll lack_v = 0, lack_num = 0;
    vi over;
    for (auto &&e: T) {
        if (e < 0) {
            lack_v += abs(e);
            lack_num++;
        }
        if (e > 0) {
            over.push_back(e);
        }
    }

    if (lack_num == 0) return 0;

    ll over_v = 0;
    int over_use = 0;

    reverse(all(over));
    for (auto &&e: over) {
        over_use++;
        over_v += e;
        if (over_v >= lack_v) break;
    }

    return (int)(lack_num + over_use);
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cout << solve() << endl;

    return 0;
}

