	vector<long long> v, w;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) cin >> b[i];
	for(int i = 0; i < n; i++) {
		if(a[i] < b[i]) v.push_back(b[i] - a[i]);
		if(a[i] > b[i]) w.push_back(a[i] - b[i]);
	}
	int ans = v.size();
	long long need = 0;
	for(int i = 0; i < v.size(); i++) {
		need += v[i];
	}
	int siz = w.size();
	sort(w.rbegin(), w.rend());
	/*for(int i = 0; i < v.size(); i++) {
