typedef long long LL;

using namespace std;

LL gcd(LL a, LL b) {
	LL r;
	while ((r = a % b) != 0) {
		a = b;
		b = r;
	}
	return b;
}
LL lcm(LL a, LL b) {
	return (a / gcd(a, b) * b);
}

int main(void) {
	int n;
	cin >> n;
	vector<LL>a(n), b(n), c(n);
	LL sum_a = 0, sum_b = 0;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		c[i] = a[i];
		sum_a += a[i];
	}
	for (int i = 0; i < n; i++) {
		cin >> b[i];
		sum_b += b[i];
	}
	if (sum_b > sum_a) {
		cout << -1;
		return 0;
	}
	LL d_p = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] < b[i]) {
			d_p += b[i] - a[i];
			a[i] = b[i];
		}
	}
	for (int i = 0; i < n; i++) {
		if (d_p <= 0) {
			break;
		}
		else {
			if (a[i] > b[i]) {
				d_p -= a[i] - b[i];
				a[i] = b[i];
			}
		}
	}
	LL ans = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] != c[i]) {
			ans++;
		}
	}
	cout << ans;
	return 0;
}

