  long long int difSum = 0;

  for( int i = 0; i < n; i++ )
  {

    dif.at(i) = vecA.at(i) - vecB.at(i);
    pair<int,int> pairDifIndex = make_pair( dif.at(i), i );
    pairDifVec.push_back(pairDifIndex);

    difSum += dif.at(i);
  }

  if( difSum < 0 )
  {
    cout << -1 << endl;
    return 0;
  }

  sort(pairDifVec.begin(), pairDifVec.end());

  vector<pair<int,int>> pairDifVecOrg = pairDifVec;

  for( int i = 0; i < n; i++ )
  {
  	while( pairDifVec.at(i).first < 0 )
    {
      	for( int j = n-1; j >= 0; j-- )
        {
			if( pairDifVec.at(j).first + pairDifVec.at(i).first >= 0 )
           {
             	int tempMove = pairDifVec.at(j).first + pairDifVec.at(i).first;
             	pairDifVec.at(j).first -= tempMove;
             	pairDifVec.at(i).first = 0;
             	break;
           }
           else
           {
              int tempMove = pairDifVec.at(j).first;
              pairDifVec.at(j).first = 0;
              pairDifVec.at(i).first += pairDifVec.at(j).first;
           }
        }
    }
  }

  int count = 0;
  for( int i = 0; i < pairDifVec.size(); i++ )
  {
     if( pairDifVec.at(i).first != pairDifVecOrg.at(i).first )
     {
        count++;
     }
  }

  cout << count << endl;


  return 0;

}

