int main() {
  int n;
  std::cin >> n;
  std::vector<int> a(n), b(n), sup;
  for (auto& x : a) std::cin >> x;
  for (auto& x : b) std::cin >> x;
  int dem = 0;
  int cnt = 0;
  for (int ni = 0; ni < n; ++ni) {
    int d = b[ni] - a[ni];
    if (d > 0) {
      dem += d;
      ++cnt;
    }
    if (d < 0) sup.push_back(-d);
  }
  std::sort(sup.begin(), sup.end());
  std::reverse(sup.begin(), sup.end());
  std::vector<int> acc(n + 1, 0);
  for (int ni = 0; ni < n; ++ni) acc[ni + 1] = acc[ni] + sup[ni];
  for (int ni = 0; ni <= n; ++ni) {
    if (acc[ni] >= dem) {
      std::cout << cnt + ni << std::endl;
      return 0;
    }
  }
  std::cout << -1 << std::endl;
  return 0;
}

