typedef long long ll;
const int MAXN = 100005;

ll N, A[MAXN], B[MAXN];

int main() {
    ios::sync_with_stdio(0); cin.tie(0);

    cin >> N;
    for (ll i = 1; i <= N; i++) cin >> A[i];
    for (ll i = 1; i <= N; i++) cin >> B[i];

    ll ans = 0;
    ll kurang = 0;
    priority_queue<ll> pq;
    for (ll i = 1; i <= N; i++) {
        if (A[i] < B[i]) {
            ans++;
            kurang += B[i]-A[i];
        } else {
            pq.push(A[i]-B[i]);
        }
    }

    while (kurang > 0) {
        if (pq.empty()) {
            cout << "-1\n";
            return 0;
        }
        ll now = pq.top(); pq.pop();
        kurang -= now;
        ans++;
    }
    cout << ans << endl;
}

