inline void solve(void){
  int N;
  in(N);
  vector<int>A(N),B(N);
  ins(A);ins(B);
  priority_queue<int>q;
  long lack=0;
  long cnt=0;
  long sum=0;
  rep(i,N)sum+=A[i]-B[i];
  if(sum<0){
    out(-1);
    return;
  }
  rep(i,N){
    if(A[i]>B[i])q.push(A[i]-B[i]);
    if(A[i]<B[i])lack+=B[i]-A[i],cnt++;
  }
  while(!q.empty()){
    int e=q.top();q.pop();
    out(e);
    if(lack<=0){
      out(cnt);
      return;
    }
    lack-=e;
    cnt++;
  }
  if(lack<=0)out(cnt);
}
