	ll check = 0;
	int ans = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] > b[i]) {
			q.push(a[i] - b[i]);
		}
		else if (a[i] < b[i]) {
			check += b[i] - a[i];
			ans++;
		}
		suma += a[i];
		sumb += b[i];
	}

	if (suma < sumb) {
