typedef pair<int, int> P;

bool pairCompare(const P &firstElof, const P &secondElof)
{
    return firstElof.second < secondElof.second;
}

int main() {
    int N, i;
    scanf("%d",&N);
    int A[N],B;
    P D[N];
    for (i=0; i<N; i++) 
        scanf("%d",&A[i]);
    for (i=0; i<N; i++) {
        scanf("%d",&B);
        D[i].first = i;
        D[i].second = A[i]-B;
    }
    sort(D, D+N, pairCompare);
    int a=0, b=N-1, count=2;
    if (D[0].second >= 0) count = 0;
    while (true) {
        if (D[a].second >= 0 || a >= b) break;
        if (D[b].second <= 0) {
            count = -1;
            break;
        }
        if (D[a].second + D[b].second > 0) {
            D[b].second += D[a].second;
            D[a].second = 0;
            a++;
            count++;
        } else if (D[a].second + D[b].second == 0) {
            a++; b--;
            D[a].second = 0;
            D[b].second = 0;
            count += 2;
        } else {
            D[a].second += D[b].second;
            D[b].second = 0;
            b--;
            count++;
        }
    }
    if (a-b== 1) count -= 2;
    else if (count >= 2) count --;
    printf("%d\n",count);
    return 0;
}

