const int N=1e5+10;
ll n, a[N], b[N], d[N], sum=0, cnt=0, les=0;
inline bool cmp( int x, int y )
{
	return x>y;
}
int main()
{
	scanf( "%lld", &n );
	for ( int i=1; i<=n; i++ )
	  scanf( "%lld", &a[i] );
	for ( int i=1; i<=n; i++ )
	  scanf( "%lld", &b[i] );
	for ( int i=1; i<=n; i++ )
	{
	    if ( a[i]<b[i] ) sum+=b[i]-a[i], ++les;
	    if ( a[i]>b[i] ) d[++cnt]=a[i]-b[i];
	}
	sort( d+1, d+cnt+1, cmp );
