struct Item
{
	int value;
	int pos;
	int c;
};

Item d[100010];	//差异 

bool compareValue(const Item &a, const Item &b)
{
	return a.value > b.value;
}

bool comparePos(const Item &a, const Item &b)
{
	return a.pos < b.pos;
}


int main()
{
	sumA = 0;
	sumB = 0;
	scanf("%d", &n);

	sumA = 0;
	for (int i = 0 ; i < n ; i++)
	{
		scanf("%d", &(a[i]));
		sumA = sumA + a[i];
	}

	long long totalDToAdd = 0;
	sumB = 0;
	for (int i = 0 ; i < n ; i++)
	{
		scanf("%d", &(b[i]));
		sumB = sumB + b[i];

		d[i].value = b[i] - a[i];
		d[i].pos = i;
		if (d[i].value > 0)
			totalDToAdd = totalDToAdd + d[i].value;
	}

	if (sumA < sumB)
	{
		printf("-1\n");
		return 0;
	}

	sort(d, d + n, compareValue);

	int changeCount = 0;
	totalDToAdd = 0;

	for (int i = 0 ; i < n ; i++)
	{
		if (d[i].value > 0)
		{
			d[i].c = b[d[i].pos];
			totalDToAdd = totalDToAdd + b[d[i].pos] - a[d[i].pos];
			changeCount++;
		}
		else if (d[i].value == 0)
		{
			d[i].c = b[d[i].pos];
		}
		else 
			break;
	}

	for (int i = n - 1 ; i >= 0 ; i--)
	{
		if (d[i].value >= 0)
			break;
		if (totalDToAdd > -d[i].value)
		{
			d[i].c = b[d[i].pos];
			totalDToAdd = totalDToAdd - (-d[i].value);	//注意是负值
			changeCount++;
		}
		else if (totalDToAdd > 0)
		{
			d[i].c = b[d[i].pos] - totalDToAdd;
			totalDToAdd = 0;
			changeCount++;
		}
		else
		{
			if (d[i].value < 0)
				d[i].c = a[d[i].pos];
			else
				break;
		}
	}

	printf("%d\n", changeCount);
//	sort(d, d + n, comparePos);
//	for (int i = 0 ; i < n ; i++)
//		printf("%d ", d[i].c);
//	printf("\n");

	return 0;
}

