using namespace std;
typedef long long ll;
int main() {
  ll n, i, j, cnt = 0, ans = 0, check1, check2;
  cin >> n;
  vector<int> a(n), b(n), d(n), d_copy(n);
  for (i = 0; i < n; ++i) {
    cin >> a[i];
  }
  for (i = 0; i < n; ++i) {
    cin >> b[i];
  }
  for (i = 0; i < n; ++i) {
    d[i] = a[i] - b[i];
    cnt += d[i];
  }
  if (cnt < 0) {
    ans = -1;
  } else {
    sort(d.rbegin(), d.rend());
    d_copy = d;
    i = 0;
    j = n - 1;
    check1 = 1;
    check2 = 1;
    while (i < j) {
      if (d[i] > 0 && d[j] < 0 && d[i] + d[j] >= 0) {
        d[i] += d[j];
        if (check1 == 1) {
          ++ans;
          check1 = 0;
        }
        d[j] = 0;
        if (check2 == 1) {
          ++ans;
          check2 = 0;
        }
      } else if (d[i] > 0 && d[j] < 0 && d[i] + d[j] < 0) {
        d[i] = 0;
        if (check1 == 1) {
          ++ans;
          check1 = 0;
        }
        d[j] += d[i];
        if (check2 == 1) {
          ++ans;
          check2 = 0;
        }
      }
      if (d[i] <= 0) {
        ++i;
        check1 = 1;
        if (i >= j || d[i] <= 0) {
          break;
        }
      }
      if (d[j] >= 0) {
        --j;
        check2 = 1;
        if (i >= j || d[j] >= 0) {
          break;
        }
      }
    }
  }
  cout << ans << "\n";
  return 0;
}

