	{
		cin >> A[i];
	}

	for (int i = 0; i < N; i++)
	{
		cin >> B[i];
	}

	vector<long long> larges;
	long long point = 0;
	int p_count = 0;
	for (int i = 0; i < N; i++)
	{
		long long x = B[i] - A[i];

		if (x > 0)
		{
			point += x;
			p_count++;
		}
		else if (x < 0)
		{
			larges.push_back(-x);
		}
	}


	if (p_count <= 0)
	{
		cout << 0 << endl;
		return 0;
	}


	sort(larges.begin(), larges.end(), greater<long long>());

	int use_count = 0;
	for (int i = 0; i < larges.size(); i++)
	{
		point -= larges[i];
		use_count++;

		if (point <= 0)
		{
			break;
		}
	}

	if (point > 0)
	{
		cout << -1 << endl;
	}
	else
	{
		cout << use_count + p_count << endl;
	}

	return 0;
}

