#include"bits/stdc++.h"
using namespace std;
#define REP(k,m,n) for(int (k)=(m);(k)<(n);(k)++)
#define rep(i,n) REP((i),0,(n))
using ll = long long;

int main()
{
	int N;
	cin >> N;
	vector<ll> A(N), B(N);
	rep(i, N)cin >> A[i];
	rep(j, N)cin >> B[j];

	ll leave = 0;
	priority_queue<ll> pq;
	rep(i, N) {
		ll now = A[i] - B[i];
		if (now >= 0)pq.push(now);
		else leave -= now;
	}
	int res = N - pq.size();
	while (!pq.empty() && leave > 0) {
		ll now = pq.top(); pq.pop();
		leave -= now;
		res++;
	}
	cout << (leave > 0 ? -1 : res) << endl;
	return 0;
}

