int Solve(int N, vector<int> A, vector<int> B) {
    vector<int> record;
    int res = 0, residue = 0;
    for (int i =0; i < N; i++) {
        if (A[i] > B[i]) {
            record.push_back(A[i] - B[i]);
        }
        if (A[i] < B[i]){
            residue += B[i] - A[i];
            res++;
        }
    }
    sort(record.begin(), record.end(), greater<int>());
    int i = 0, n = record.size();
    while (residue > 0 && i < n) {
        residue -= record[i++];
        res++;
    }
    if (residue > 0) {
        return -1;
    }
    return res;
}


