int main() {
  int n; 
  cin >> n;
  vector<int> a(n);
  vector<int> b(n);
  for (int i=0; i<n; i++){
    cin >> a.at(i);
  }
  for (int i=0; i<n; i++){
    cin >> b.at(i);
  }
  vector<int> d(n);
  for (int i=0; i<n; i++){
    d.at(i) = a.at(i) - b.at(i);
  }
  sort(d.begin(), d.end());
  int j=0; //j：A<Bとなる個数
  for (int i=0; i<n; i++){
    if (d.at(i) < 0){
      j++;
    }
    else break;
  }

  if (j == 0){
    cout << 0 << endl;
  }

  else if (j == n){
    cout << -1 << endl;
  }

  else {
  int dif = 0;
  for (int i=0; i<j; i++){
    dif += d.at(i);
  }
  int k=0; //k:分配に必要な個数
  int x=0;
  for (int i=0; i<n-j; i++){
    x += d.at(n-1-i);
    k++;
    if (x >= dif*(-1)){
      cout << j+k << endl;
      break;
    }
    else if (i == n-j-1 && x < dif*(-1)){
      cout << -1 << endl;
    }
  }
  }
  return 0;
}

