int N;
array<ll, 2> S[100010];

int main() {

    scanner >> N;
    repeat(i, N) {
        scanner >> S[i][0];
    }
    repeat(i, N) {
        ll b;
        scanner >> b;
        S[i][0] -= b;
        S[i][1] = b;
    }

    sort(S, S + N); // S[i][0] が負<=>たりない

    int backi = N;
    int ans = 0;

    repeat(i, N) {
        ll si = S[i][0];
        if (si >= 0) break;
        ++ans; // i
        while (si < 0) {
            while (S[backi][0] == 0) {
                --backi;
                ++ans; // back
            }
            if (S[backi][0] < 0) bye("-1");
            ll m = min(-si, S[backi][0]);
            si += m;
            S[backi][0] -= m;
        }
        assert(si == 0);
        S[i][0] = si;
    }

    printer << ans << '\n';


    return 0;
}

