int main(){
  int N;
  cin >> N;
  int sumA=0,sumB=0,sumC=0,aB=0;
  for(int i=0;i<N;++i){
    cin >> A[i];
    sumA += A[i];
  }
  for(int i=0;i<N;++i){
    cin >> B[i];
    sumB += B[i];
  }

  for(int i=0;i<N;++i){
    C[i] = B[i] - A[i]; // 準備できてないほど正
    if(C[i]>0){
      sumC += C[i]; // テストの方がでかい場合の自分との差の和
      aB++;
    }
  }

  if(sumA < sumB){ // 不可能
    cout << "-1" << endl;
    return 0;
  }
  sort(C,C+N); // C[0]は B - A が最小　-> 
  if(C[0]>=0){ // 何もしなくても可能
    cout << "0" << endl;
    return 0;
  }

  int index = 0, ans = 0,sumD=0;

  while(sumC > sumD){ // 余裕がある方の余裕っぷりを計算  
    sumD += abs(C[index]);
    ans++;
    index++;
  }
  cout << aB + ans << endl;

  return 0;
}

