  }

  for(int i=0;i<N;++i){
    C[i] = B[i] - A[i]; // 準備できてないほど正
    if(C[i]>0){
      sumC += C[i]; // テストの方がでかい場合の自分との差の和
      aB++;
    }
  }

  if(sumA < sumB){ // 不可能
    cout << "-1" << endl;
