  if(C[0]>=0){ // 何もしなくても可能
    cout << "0" << endl;
    return 0;
  }

  int index = 0, ans = 0,sumD=0;

  while(sumC > sumD){ // 余裕がある方の余裕っぷりを計算  
    sumD += abs(C[index]);
    ans++;
    index++;
  }
  cout << aB + ans << endl;

  return 0;
}

