	sort(c.begin(), c.end());
	int ans = 0;
	long long sum = 0;
	for(int i=0; i<n; ++i){
		if(c[i] >= 0) break;
		sum -= c[i];
		++ans;
	}
	for(int i=n-1; i>=0; --i){
		if(c[i] <= 0 || sum <= 0) break;
		sum -= c[i];
		++ans;
	}
	if(sum > 0) cout << -1 << "\n";
	else cout << ans << "\n";
}

