int main() {
  //A1 < B1ならi=0でB1-A1を足さなければならない
  //A2 < B2ならi=1でB2-A2を足さなければならない
  //i=0,N-1において、Ai<Biだとしたら、Bi-Ai不足する
  //これを穴埋めするために、Ai>Biとなっているところから補っていく必要がある
  //Ai-Biの大きい順に並べていく
  //大きい方からAi-Biを不足分から引いていく
  //不足分が負になったらその時のカウンターがi
  //不足分が負になる前にAi-Biが負になったら-1
  int N;
  cin >> N;
  vector<long> Ai(N);
  vector<long> Bi(N);
  vector<long> minus(N);
  int i;
  for (i=0;i<N;i++){
    cin >> Ai.at(i);
  }
  for (i=0;i<N;i++){
    cin >> Bi.at(i);
  }
  for (i=0;i<N;i++){
    minus.at(i) = Ai.at(i) - Bi.at(i);
  }
  sort(minus.begin(),minus.end());
  reverse(minus.begin(),minus.end());
  long lack = 0;
  int minus_count=0;
  for (i=0;i<N;i++){
    if (minus.at(i)<0){
      lack += abs(minus.at(i));
      minus_count++;
    }
  }
  int ans = -1;
  if (lack == 0){
      ans = 0;
  } else {
    for (i=0;i<N;i++){
      if (minus.at(i) <= 0){
        ans = -1;
        break;
      }
      lack -= minus.at(i);
      if (lack <= 0){
        ans = minus_count + i + 1;
        break;
      }
    }
  }
  cout << ans << endl;
}

