typedef long long ll;

struct solver_2019_c {
    int run(int N, std::vector<ll> A, std::vector<ll> B) {
        int num_less = 0, num_same = 0, num_over = 0;
        ll less_sum = 0;
        std::vector<ll> over_list;
        for(int i = 0; i < N; ++i) {
            // std::cerr << i << std::endl;
            // std::cerr << A[i] << "\t" << B[i] << std::endl;
            if(A[i] < B[i]) {
                num_less++;
                less_sum += (B[i] - A[i]);
                // std::cerr << "ls: " << less_sum << std::endl;
            }else if(A[i] == B[i]) {
                num_same++;
            }else{
                num_over++;
                over_list.push_back(A[i] - B[i]);
                // std::cerr << "ov: " << A[i] - B[i] << std::endl;
            }
        }
        ll over_sum = 0;
        std::sort(over_list.begin(), over_list.end(), std::greater<ll>());
        if(num_less == 0) {
            return 0;
        }
        for(int i = 0; i < over_list.size(); ++i) {
            over_sum += over_list[i];
            if(less_sum <= over_sum) {
                // success
                return num_less + i + 1;
            }
        }

        return -1;
    }
};

int main(void) {
    solver_2019_c solver;

    int N;
