const ld EPS = 1e-8;

int solve(int N, const vector<int>& A, const vector<int>& B) {
  vector<int> difp, difm;
  REP(i,N){
    int tmp = A[i] - B[i];
    if(tmp >= 0) difp.push_back(tmp);
    else difm.push_back(tmp);
  }
  sort(difp.rbegin(), difp.rend());
  sort(ALL(difm));

  if(difm.empty()) return 0;

  int sum = 0;
  for(int e: difm) {
    sum += e;
  }
  REP(i, difp.size()) {
    sum += difp[i];
    if(sum >= 0) return i + difm.size() + 1;
  }
  return -1;
}

