typedef long long LL;
LL A[maxn], B[maxn];
vector<LL> v;
int main(){
	int N;
	cin >> N;
	for(int i = 0; i < N; i += 1) cin >> A[i];
	for(int i = 0; i < N; i += 1) cin >> B[i];
	LL ans = 0, sum = 0;
	for(int i = 0; i < N; i += 1){
		if(A[i] < B[i]){
			sum += B[i] - A[i];
			ans += 1;
		}
		if(A[i] > B[i]) v.push_back(A[i] - B[i]);
	}
	sort(v.begin(), v.end(), greater<int>());
	for(LL x : v){
		if(sum <= 0) break;
		sum -= x;
		ans += 1;
	}
	if(sum > 0) cout << - 1;
	else cout << ans;
}

