typedef long long ll;
int main(){
  int N;
  std::cin >> N;
  std::vector<int> a(N,0),b(N,0);
  ll asum=0,bsum=0,lack=0;
  for(int i = 0; i < N; i++){
    std::cin >> a[i];
    asum+=a[i];
  }
  int cnt=0,rcnt=0;
  for(int i = 0; i < N; i++){
    std::cin >> b[i];
    bsum+=b[i];
    if (b[i]>a[i]) {
      lack+=b[i]-a[i];
      cnt++;
    }
    if (b[i]==a[i]) rcnt++;
  }
  if(bsum>asum){
    std::cout << -1 << std::endl;
    return 0;
  }
  int bufi=0;
  std::vector<int> rest(N-cnt-rcnt,0);
  for(int i = 0; i < N; i++){
    if (b[i]<a[i]) {
      rest[bufi]=a[i]-b[i];
      bufi++;
    }
  }
  bufi=N-cnt-rcnt;
  std::sort(rest.begin(),rest.end(),std::greater<int>());
  for(int i = 0; i < N-cnt-rcnt; i++){
    std::cout << rest[i] << std::endl;
  }
  for(int i = 0; i < bufi; i++){
