  ll result = 0;
  for (ll j=0; j < N; ++j) {
    cin >> A[j];
    Asum += A[j];
  }
  for (ll j=0; j < N; ++j) {
    cin >> B[j];
    Bsum += B[j];
  }
  if (Asum >= Bsum) {
    vector<ll> D;
    for (ll j=0; j < N; ++j) {
      ll d = A[j] - B[j];
      if (d != 0) {
        D.push_back(d);
      }
    }
    priority_queue<ll> minus, plus;
    for (ll d: D) {
      if (d > 0) {
        plus.push(d);
      } else {
        minus.push(d);
        result += 1;
      }
    }
    ll ptop = plus.top(); plus.pop();
    bool modified = false;
    while (!minus.empty()) {
      ll mtop = minus.top();
      if (ptop >= -mtop) {
        ptop += mtop;
        if (!modified) {
          modified = true;
          result += 1;
        }
        minus.pop();
      } else {
        mtop += ptop;
        if (!modified) {
          modified = true;
          result += 1;
        }
        ptop = plus.top(); plus.pop();
        modified = false;
      }
    }
    cout << result << endl;
  } else {
    cout << -1 << endl;
  }
}

