	}

	priority_queue<ll> bigger;
	priority_queue<ll, vector<ll>, greater<ll> > smaller;
	rep(i, n) {
		if (a[i] - b[i] < 0) smaller.push(a[i] - b[i]);
		else if (a[i] - b[i] > 0) bigger.push(a[i] - b[i]);
