//	cout << bigger.size() << " " << smaller.size() << endl;

	int cnt = smaller.size();
//	cout << cnt << endl;
	ll over = 0;
	int overcnt = 0;
	while (!smaller.empty()) {
		ll lack = smaller.top();
//		cout << lack << endl;
		smaller.pop();
		if (lack + over >= 0) {
//			cout << "over" << endl;
			over -= lack;
			overcnt++;
			continue;
		} else {
//			cout << "lack" << endl;
			while (lack < 0) {
//				cout << "in" << endl;
				ll point = bigger.top();
//				cout << point << endl;
				bigger.pop();
				cnt++;
				lack += point;
			}
			over = lack;
		}
	}

	cout << cnt + overcnt - 1 << endl;

	return 0;
}

