intmax_t hoge(const std::vector<intmax_t>& A, const std::vector<intmax_t>& B) {
  std::vector<intmax_t> gt, lt;
  size_t N = A.size();
  for (size_t i = 0; i < N; ++i) {
    if (A[i] < B[i]) {
      lt.push_back(B[i]-A[i]);
    } else if (A[i] > B[i]) {
      gt.push_back(A[i]-B[i]);
    }
  }

  std::sort(lt.begin(), lt.end());
  std::sort(gt.begin(), gt.end());
  std::vector<intmax_t> f(gt.size(), 1);
  intmax_t res = lt.size();
  while (!gt.empty() && !lt.empty()) {
    intmax_t ll = lt.back();
    intmax_t gg = gt.back();
    if (gg >= ll) {
      lt.pop_back();
      gt.back() -= ll;
      res += f.back();
      f.back() = 0;
      if (gt.back() == 0) {
        gt.pop_back();
        f.pop_back();
      }
    } else {
      lt.back() -= gg;
      gt.pop_back();
      res += f.back();
      f.pop_back();
    }
  }
  if (!lt.empty()) return -1;
  return res;
}

