  {
    intmax_t SA = std::accumulate(A.begin(), A.end(), 0L);
    intmax_t SB = std::accumulate(B.begin(), B.end(), 0L);
    if (SA < SB)
      return puts("-1"), 0;
  }
  {
    bool valid = true;
    for (size_t i = 0; i < N; ++i)
      if (A[i] < B[i]) {
        valid = false;
        break;
      }
    if (valid)
      return puts("0"), 0;
  }

  printf("%jd\n", hoge(A, B));
}

