    int N;
    cin >> N;
    int answer = 0;
    int A[N];
    int B[N];
    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];
    priority_queue<int> amari;
    ll S = 0;
    for (int i = 0; i < N; i++)
    {
        if (A[i] < B[i])
        {
            answer++;
            S += B[i] - A[i];
        }
        else if (A[i] > B[i])
            amari.push(A[i] - B[i]);
    }
    ll sum = 0;
    while (sum < S || !amari.empty())
    {
        answer++;
        sum += amari.top();
        amari.pop();
    }
    if (sum >= S)
        cout << answer << endl;
    else
        cout << -1 << endl;
    return 0;
}

