struct exam {
    ll A, B;
};

static bool cmp(const exam &x, const exam &y) {
    return (x.A - x.B) > (y.A - y.B);
}
int main() {
    ll n;
    cin >> n;
    vector<exam> nums(n);
    ll sumA = 0;
    ll sumB = 0;
    for (auto i = 0; i < n; ++i) {
        cin >> nums[i].A;
        sumA += nums[i].A;
    }
    for (auto i = 0; i < n; ++i) {
        cin >> nums[i].B;
        sumB += nums[i].B;
    }
    if (sumA < sumB) {
        cout << -1 << endl;
    } else {
        ll res = 0;
        ll c = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i].A < nums[i].B) {
                ++res;
                c += nums[i].B - nums[i].A;
            }
        }
        if (res == 0) {
            cout << 0 << endl;
            return 0;
        }
        sort(nums.begin(), nums.end(), cmp);
        for (int i = 0; i < n; ++i) {
            ll diff = (nums[i].A - nums[i].B);
            if (diff <= 0) continue;
            ++res;
            if (diff >= c) {
                break;
            } else {
                c -= diff;
            }
        }
        cout << min(res, n) << endl;
    }
    return 0;
}

