    if (disp.back() <= 0) {
      disp.pop_back();
      res += changed_back;
      changed_back = false;
      continue;
    }
    if (disp.front() >= 0) {
      disp.pop_front();
      res += changed_front;
      changed_front = false;
      continue;
    }

    if (disp.front() + disp.back() >= 0) {
      ll temp = disp.back();
      disp.back() += disp.front();
      disp.front() += temp;
      changed_front = true;
      changed_back = true;
    } else {
      ll temp = disp.front();
      disp.front() += disp.back();
      disp.back() += temp;
      changed_front = true;
      changed_back = true;
    }
  }

  printf("%d\n", res + changed_front + changed_back);
}

