        diff.push_back(A[i] - B[i]);
        C.push(A[i] - B[i]);
    }
}

ll ans = 0;
void solve()
{
    while (!C.empty())
    {
        ll front = C.top();
        C.pop();
        if (front < 0)
        {
            return;
        }

        bool update = false;
        for (int i = 0; i < (int)diff.size() - 1; i++)
        //        for (int i = diff.size() - 1; i >= 0; i--)
