        cin >> i;
        sumB += i;
    }
    if (sumA < sumB) return -1;
    vector<int> g;
    int l = 0, cnt = 0;
    for (int i = 0; i < N; i++) {
        auto t = A[i] - B[i];
        if (t > 0) g.push_back(t);
        else if (t < 0) {
            l += -t;
            cnt++;
        }
    }
    if (l == 0) return 0;
    sort(g.begin(), g.end(), greater<int>());
    for (size_t i = 0; i < g.size(); i++) {
        if ((l -= g[i]) <= 0) return cnt + i + 1;
    }
    return -1;
}
