#include <stdio.h>
#include <stdlib.h>
#include <algorithm>
#include <queue>

#define MAX_N (100000)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  long N, as[MAX_N], bs[MAX_N];
  scanf("%ld", &N);
  for (long i = 0; i < N; i++) {
    scanf("%ld", &as[i]);
  }
  for (long i = 0; i < N; i++) {
    scanf("%ld", &bs[i]);
  }

  // impossible case
  long sa = 0, sb = 0;
  for (long i = 0; i < N; i++) {
    sa += as[i];
    sb += bs[i];
  }
  if (sa < sb) {
    printf("-1\n");
    return 0;
  }

  // possible find ans
  priority_queue<long> que;
  long shortage = 0, ans = 0;
  for (int i = 0; i < N; i++) {
    const int a = as[i], b = bs[i];
    if (a < b) {
      shortage += b - a;
      ans++;
    } else {
      que.push(a - b);
    }
  }
  while (shortage > 0) {
    const int x = que.top();
    que.pop();
    shortage -= x;
    ans++;
  }
  printf("%ld\n", ans);

  return 0;
}

