		} // end if
	} // end rep

	ll totalRack = accumulate(ALL(rack), 0LL);
//	cerr << "totalRack: " << totalRack << endl;
	sort(ALL(redundant));

//	cerr << "rack_sz: " << (int)rack.size() << endl;
//	cerr << "redu_sz: " << (int)redundant.size() << endl;

	ll total = 0LL;
	vector<LI> usedIndex; usedIndex.clear();

	rep (i, (int)redundant.size()){
		ll curr = -redundant[i].first;
		int ind = redundant[i].second;
//		cerr << "curr: " << curr << " ind: " << ind << endl;
		usedIndex.push_back(LI(curr,ind));
		if (total + curr >= totalRack){
			ll used = totalRack - total;
			usedIndex[(int)usedIndex.size() - 1] = LI(used, ind);
			break;
		}else{
			total += curr;
		} // end if
	} // end rep

//	cerr << "usedIndex_sz: " << (int)usedIndex.size() << endl;

	vector<ll> C(N, 0LL);
	rep (i, N){
		if (A[i] < B[i]){
			C[i] = B[i];
		}else
		if (A[i] >= B[i]){
			C[i] = A[i];
		} // end if
	} // end rep

	rep (i, (int)usedIndex.size()){
		ll used = usedIndex[i].first;
		int ind = usedIndex[i].second;
		C[ind] = A[ind] - used;
	} // end rep

/*
	rep (i, N){
		cerr << C[i] << (i != N - 1 ? ' ' : '\n');
	} // end rep
*/
	int res = 0;
	rep (i, N){
		if (A[i] != C[i]){
			++res;
		} // end if
	} // end rep

	cout << res << endl;

	return 0;
}

