using namespace std;

vector<int> buildIncrementList(int N, const vector<long long> &A, const vector<long long> &B)
{
	vector<int> inc;
	for (int i = 0; i < N; ++i) {
		if (A[i] < B[i]) {
			inc.push_back(i);
		}
	}
	return inc;
}

vector<int> buildDecrementList(int N, const vector<long long> &A, const vector<long long> &B)
{
	vector<int> dec;
	for (int i = 0; i < N; ++i) {
		if (A[i] > B[i]) {
			dec.push_back(i);
		}
	}

	sort(dec.begin(), dec.end(), [&](int i, int j) {
		return A[i] - B[i] < A[j] - B[j];
	});

	return dec;
}

vector<long long> solve(int N, const vector<long long> &A, const vector<long long> &B)
{
	auto inc = buildIncrementList(N, A, B);
	auto dec = buildDecrementList(N, A, B);
	auto C = A;

	for (auto i : inc) {
		while (C[i] < B[i]) {
			int j = dec.back();
			long long x = min(B[i] - C[i], C[j] - B[j]);
			C[i] += x;
			C[j] -= x;
			if (C[j] == B[j]) {
				dec.pop_back();
			}
		}
	}

	return C;

}

