int main(){
    int n;
    cin >> n;
    priority_queue<pair<int,int>> mx,mn;
    ll m = 0;
    ll o = 0;
    vector<int> a(n),b(n);
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }
    for(int i = 0; i < n; i++){
        cin >> b[i];
    }
    for(int i = 0; i < n; i++){
        if(a[i] > b[i]){
            mx.push({a[i],i});
            o += a[i]-b[i];
        }
        else if(a[i] < b[i]){
            mn.push({a[i],i});
            m += a[i]-b[i];
        }
    }    
    int cnt = 0;
    if(-m > o) cout << -1 << endl;
    if(m == 0) cout << 0 << endl;
    else{
        pair<int,int> more = mx.top();
        pair<int,int> less = mn.top();
        cnt == 2;
        while(!mn.empty()){
            more.first -= min(more.first,less.first);
            less.first += min(more.first,b[less.second]-less.first);
            if(less.first == b[less.second]){
                mn.pop();
                less = mn.top();
                cnt++;
            }
            else if(more.first == 0){
                mx.pop();
                more = mx.top();
                cnt++;
            }
        }
        cout << cnt << endl;
    }

}

