            sum1 += v1[i];
            ans[i] = v1[i];
        }
    }
    for (int i = 0; i < n; ++i) {
        if(ans[i] == -1){
            ans[i] = v[i];
            sum1 += v[i];
        }
    }
    if(sum1 > sum ){
        int adjust = sum1- sum;
        for (int i = 0; i < n; ++i) {
            int x1 = ans[i];
            ans[i] -= min(adjust , abs(x1 - v1[i]));
            adjust -= min(adjust , abs(x1 - v1[i]));
        }
        if(adjust != 0){
            printf("-1");
            return 0;
        }
    }
    else if(sum1 < sum){
        int adjust = sum - sum1;
        for (int i = 0; i < n; ++i) {
            if(ans[i] != v[i]){
                ans[i] += adjust;
                break;
            }
        }
