typedef long long ll;

using namespace std;

int main() {
	int N;
	cin >> N;
	vector<ll> a(N);
	vector<ll> b(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }
	for (int i = 0; i < N; ++i) { cin >> b[i]; }

	vector<ll> x(N);
	vector<ll> y(N);
	ll sum_x = 0;
	ll sum_y = 0;
	int size_x = 0;
	int size_y = 0;
	for (int i = 0; i < N; ++i) {
		if (a[i] > b[i]) {
			x[size_x++] = (a[i] - b[i]);
			sum_x += (a[i] - b[i]);
		}
		if (a[i] < b[i]) {
			y[size_y++] = (b[i] - a[i]);
			sum_y += (b[i] - a[i]);
		}
	}

	if (sum_y > sum_x) {
		cout << -1 << endl;
		return 0;
	}

	sort(x.begin(), x.end(), greater<ll>());
	int ix = 0, iy = 0;
	vector<bool> used(N, false);
	int lp = 0;
	while ((iy < size_y) && (lp++ < 1e7)) {
		if (x[ix] >= y[iy]) {
			y[iy] = 0;
			++iy;
			x[ix] -= y[iy];
			used[ix] = true;
		}
		if (x[ix] < y[iy]) {
			x[ix] = 0;
			used[ix] = true;
			y[iy] -= x[ix];
			++ix;
		}
	}

	int res = size_y;
	for (int i = 0; i < N; ++i) {
		if (used[i]) { ++res; }
	}

	cout << res << endl;

	return 0;
}

