    for (i64 i = 1; i <= n; i++) {
        cin >> a[i];
    }

    for (i64 i = 1; i <= n; i++) {
        cin >> b[i];
    }

    for (i64 i = 1; i <= n; i++) {
        c[i] = a[i] - b[i];
    }

    sort(c + 1, c + n + 1);

    i64 i = 1;
    i64 j = n;

    set<i64> R;
    for (;;) {
        if (i >= j) {
            if (c[i] < 0) {
                cout << -1 << endl;
                return 0;
            }
        }
        if (c[i] == 0) {
            i++;
            continue;
        }
        if (c[j] == 0) {
            j--;
            continue;
        }
        if (c[i] > 0) {
            break;
        }
        if (c[j] < 0) {
            cout << -1 << endl;
            return 0;
        }
        R.insert(i);
        R.insert(j);
        if (c[j] + c[i] >= 0) {
            c[j] += c[i];
            c[i] = 0;
            i++;
        }
        else {
            c[i] += c[j];
            c[j] = 0;
            j--;
        }
    }

    cout << R.size() << endl;

    return 0;
}

