#include <bits/stdc++.h>
using namespace std;
int main() {
	int N;
	int i,j,ta=0,tb=0,acount=0,atotal=0,ccount=0,flg;
	cin >> N;
	vector <int> A(N);
	vector <int> B(N);
	vector <int> C(N);
	for (i = 0; i < N; i++) {
		cin >> A.at(i);
		ta+=A.at(i);					// ta：準備度合計
		C.at(i) = 0;					// C:準備度余分数格納用配列クリア
	}
	for (i = 0; i < N; i++) {
		cin >> B.at(i);
		tb+=B.at(i);					// tb：必要準備度合計
		if(A.at(i) < B.at(i)) {				// 準備が不足の試験
			acount++;				// acount:準備度不足試験数
			atotal+=(B.at(i)-A.at(i));		// atotal:準備度不足数合計
		}
		if(A.at(i) > B.at(i)) {				// 準備度が余分の試験
			C.at(ccount) = A.at(i) - B.at(i);	// C：準備度余分数
			ccount++;				// ccount：準備度余分試験数
		}
	}
	if(ta < tb) {						// 準備度合計が必要準備度合計より小さいので不可能⇒-1出力
		cout << "-1" << endl;
	}
	else {							// 準備度を変更することで全ての試験に合格可能
		flg = 1;
		while(flg == 1) {				// C：準備度余分数を降順ソート
			flg = 0;
			for(i = 1;i<ccount;i++) {
				if(C.at(i) > C.at(i-1)) {	// Cの後の方が大きい場合は入れ替えて、入替フラグを1
					j = C.at(i);
					C.at(i) = C.at(i-1);
					C.at(i-1) = j;
					flg = 1;
				}
			}
		}
		i = 0;
		while (atotal > 0) {				// 準備不測数合計が0以下になるまで
			atotal-=C.at(i);			// 不足準備数合計から準備度余分数を大きい方から減じる
			i++;					// 不足準備度を補う為に使用された準備度余分試験数
		}
		j = acount + i;					// acount：補充され変更になる試験数、i：補充で変更になる試験数
		cout << j << endl;
	}
	return 0;
}

