	for (negC = 0;negC < N && diff[negC] < 0;++ negC) neg += diff[negC];
	for (posC = N - 1;posC >= negC && neg < 0;-- posC) neg += diff[posC];
	if (neg < 0) cout << -1;
	else cout << negC + N - posC - 1;
	return 0;
}
