int main(int argc, char* argv[])
{
  int N;
  std::cin >> N;

  std::vector<int> A, B;
  A.resize(N);
  B.resize(N);

  for (auto& a : A) {
    std::cin >> a;
  }
  for (auto& b : B) {
    std::cin >> b;
  }

  std::vector<int> ok;
  ok.reserve(N);
  int ng_sum = 0, ng_count;
  for (int i = 0; i < N; ++i) {
    const auto diff = A[i] - B[i];
    if (diff < 0) {
      ng_sum += -diff;
      ++ng_count;
    }
    else if (0 < diff) {
      ok.push_back(diff);
    }
  }

  std::sort(ok.begin(), ok.end());

  int result = ng_count;
  for (auto it =  ok.rbegin(), it_end = ok.rend(); it != it_end; ++it) {
    if (ng_sum <= 0) break;
    ng_sum -= *it;
    ++result;
  }

  if (ng_sum <= 0) std::cout << result;
  else std::cout << -1;

  return 0;
}

