				cor++;
				used[right]=1;
			}
			if(!used[left]){
				cor++;
				used[left]=1;
			}
			a[right]+=a[left];
			left++;
		}
		else{
			if(!used[right]){
				cor++;
				used[right]=1;
			}
			a[right-1]+=a[right];
			right--;
