int main() {
  int n;
  cin >> n;
  vector<ll> a(n), b(n);
  rep(i, n) cin >> a[i];
  rep(i, n) cin >> b[i];

  ll asum = 0, bsum = 0;
  rep(i, n) asum += a[i];
  rep(i, n) bsum += b[i];
  if (asum < bsum) {
    cout << -1 << endl;
    return 0;
  }
  priority_queue<ll> pq;
  rep(i, n) {
    if (a[i] > b[i]) pq.push(a[i] - b[i]);
  }
  int ans = 0;
  ll res = 0;
  rep(i, n) {
    if (a[i] >= b[i]) continue;
    ans++;
    ll lack = b[i] - a[i];
    while (lack > 0) {
      if (res >= lack) {
        res -= lack;
        break;
      }
      lack -= res;
      res = pq.top();
      pq.pop();
      ans++;
    }
  }
  cout << ans << endl;



  return 0;
}

