int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  VL as(N), bs(N);
  cin >> as >> bs;

  VL ds(N);
  REP(i,N) ds[i] = as[i] - bs[i];
  SORT(ds);

  if(ds[0] >= 0){
    cout << 0 << endl;
    return 0;
  }
  if(accumulate(ALL(ds), 0ll) < 0){
    cout << -1 << endl;
    return 0;
  }

  LL acc = 0;
  int ans = 0;
  for(int b=0,e=N-1;b<=e;){
    if(ds[b] >= 0) break;
    if(ds[b] + acc >= 0){
      acc += ds[b];
      ++ans;
      ++b;
    }
    else{
      acc += ds[e];
      ++ans;
      --e;
    }
  }
  cout << ans << endl;

  return 0;
}

