        if (c[i] > b[i] && cnt) {
            if (c[i] - b[i] >= cnt) {
                c[i] -= cnt;
                cnt = 0;
            } else {
                cnt -= c[i] - b[i];
                c[i] -= c[i] - b[i];
            }
        }
    }
    if (cnt > 0) { //負債が残る
        cout << -1 << endl;
        return 0;
    }
    for (int i = 0; i < n; ++i) { //どこを削ればうまいことai = ci
        if (a[i] < c2[i] && c2[i] - a[i] <= cnt) {
            cnt -= c2[i] - a[i];
            c2[i] -= c2[i] - a[i];
        }
    }
    cnt = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] != c[i]) {
            cnt++;
        }
    }
    cout << cnt << endl;
    return 0;
}

