#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}

ll solve(int N, vi& a, vi& b) {
    priority_queue<int> rest;

    int L = 0, R = 0;
    vi as, bs;
    rep(i,N){
        if (a[i] < b[i]) {
            as.pb(a[i]);
            bs.pb(b[i]);
            ++L;
        } else {
            rest.push(a[i]);
            ++R;
        }
    }
    if (L == 0) return 0;
    sort(ALL(as)); sort(ALL(bs));

    int F = 0;
    auto it = as.begin();
    for (int i=0; i<L; ++i) {
        it = lower_bound(it, as.end(), bs[i]);
        if (it == as.end()) break;
        int ix = it - as.begin();
        ++F;
        ++it;
    }
    int manq = L - F;
    assert(manq > 0);
    if (manq > R) return -1;

    int i = 0;
    while (!rest.empty()) {
        if (rest.top() < bs[L-1 - i]) return -1;
        rest.pop(); ++i;
        if (i == manq) break;
    }
    return L + manq;
}

