#include "bits/stdc++.h"

using namespace std;

void solve()
{
	int N;
	cin >> N;
	vector<long> as(N), bs(N), ds(N);
	for (int i = 0; i < N; i++) cin >> as[i];
	for (int i = 0; i < N; i++) cin >> bs[i];
	for (int i = 0; i < N; i++)
	{
		ds[i] = as[i] - bs[i];
	}
	//sort(ps.begin(), ps.end());
	sort(ds.begin(), ds.end());

	int l = 0, r = N - 1;
	bitset<100010> used;
	while (l < r)
	{
		if (ds[l] >= 0) break;
		if (ds[r] < 0)
		{
			cout << -1 << endl;
			return;
		}
		long x = min(ds[r], -ds[l]);
		ds[r] -= x;
		ds[l] += x;
		used[l] = used[r] = 1;
		if (ds[l] < 0)
		{
			r--;
		}
		else if (ds[r] > 0)
		{
			l++;
		}
		else
		{
			l++;
			r++;
		}
		//cout << l << ' ' << r << endl;
	}

	cout << used.count() << endl;
}

int main(void)
{
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

