int n;
const int N = (int) 3e5;
int a[N], b[N];
int main() {
    ios_base::sync_with_stdio(false);
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    int ans = 0;
    long long need = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < b[i]) {
            ans++;
            need += b[i] - a[i];
        }
    }
    vector<int> free;
    for (int i = 0; i < n; i++) {
        if (a[i] > b[i]) {
            free.push_back(a[i] - b[i]);
        }
    }
    sort(free.begin(), free.end());
    reverse(free.begin(), free.end());
    for (auto x: free) {
        if (need == 0) {
            break;
        }
        long long take = min(need, 1ll * x);
        need -= take;
        ans++;
    }
    if (need > 0) {
        cout << "-1\n";
        return 0;
    }
    cout << ans << "\n";
    return 0;
}

