using namespace std;
typedef long long LL;
typedef pair<int, int> P;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> A(n), B(n);
    rep(i, n) cin >> A[i];
    rep(i, n) cin >> B[i];
    LL sum = accumulate(all(A), 0LL) - accumulate(all(B), 0LL);
    if(sum < 0){
        cout << -1 << endl;
        return 0;
    }
    int ans = n;
    priority_queue<LL> p;
    priority_queue<LL, vector<LL>, greater<LL> > q;
    rep(i, n){
        if(A[i] - B[i] > 0) p.push(A[i] - B[i]);
        else if(A[i] - B[i] < 0) q.push(B[i] - A[i]);
        else ans--;
    }
    int f = 0;
    LL x = -1;
    while(!q.empty()){
        LL np = p.top();
        if(f) np = x;
        LL nq = q.top();

        x = np - nq;
        if(x >= 0){
            q.pop();
            if(!f) p.pop();
            if(x > 0){
                f = 1;
            }else{
                f = 0;
            }
        }else{
            if(!f) p.pop();
            q.pop();
            q.push(nq-np);
            x = 0;
            f = 0;
        }
    }
    cout << ans - p.size() << endl;

}

