int calc(const std::vector<int>& as, const std::vector<int>& bs, int n) {
  std::vector<int> diff(n);
  int64_t sum = 0;
  for (int i = 0; i < n; i++) {
    diff[i] = as[i] - bs[i];
    sum += diff[i];
  }

  if (sum < 0)
    return -1;

  std::sort(diff.begin(), diff.end());

  auto head = diff.begin();
  auto tail = diff.end() - 1;
  int ans = 0;
  int64_t remain = 0;
  while (*head < 0) {
    int minus = *head;
    head++;
    ans++;
    while (minus + remain < 0) {
      remain += *tail;
      tail--;
      ans++;
    }
    remain += minus;
  }

  return ans;
}

