        sumA += A[i];
    }
    for(long int i=0; i<N; i++){
        cin >> B[i];
        sumB += B[i];
    }

    if(sumA < sumB){
        cout << -1 << endl;
        return 0;
    }

    bool pass = true;
    for(long int i=0; i<N; i++){
        if(A[i] < B[i]){ pass=false; }
    }
    if(pass){
        cout << 0 << endl;
        return 0;
    }

    //main
    vector<long int> diff(N), diffbefore(N);
    for(long int i=0; i<N; i++){
        diff[i] = A[i] - B[i];
    }

    //diffをsort
    sort(diff.begin(),diff.end());
    diffbefore = diff;

    //差分を埋める
    long int backpointer = N-1;
    for(long int i=0; i<N;i++){
        if( diff[i] < 0 ){
            //backpointerが十分大きい
            if((diff[backpointer] + diff[i]) > 0){
                //backpointerを分け与えて次へ。
                diff[backpointer] += diff[i];
                diff[i] = 0;
                continue;
            }else{
                //backpointerの限界まで分けて次のbackpointerへ
                diff[i] += diff[backpointer];
                diff[backpointer] = 0;
                backpointer--;
                i--;
                continue;
            }
        } 
    }

    //変化があった数をカウントして表示する
    long int counter=0;
    for(long int i=0; i<N; i++){
        if(diff[i] != diffbefore[i]){ counter++; }
    }
    cout << counter << endl;

    return 0;
}

