int main() {
  i64 N;
  std::cin >> N;
  std::vector<i64> A, B;
  tools::read(A, N);
  tools::read(B, N);

  std::vector<i64> diffs;
  diffs.reserve(N);
  for (i64 i = 0; i < N; ++i) {
    diffs.push_back(A[i] - B[i]);
  }

  std::vector<i64> riches, poors;
  for (const i64& diff : diffs) {
    if (diff > 0) {
      riches.push_back(diff);
    } else if (diff < 0) {
      poors.push_back(-diff);
    }
  }

  std::sort(riches.begin(), riches.end(), std::greater<i64>());
  std::vector<i64> riches_sum({0});
  riches_sum.reserve(riches.size() + 1);
  std::partial_sum(riches.begin(), riches.end(), std::back_inserter(riches_sum));

  const i64 lack = std::accumulate(poors.begin(), poors.end(), static_cast<i64>(0));

  const auto it = std::lower_bound(riches_sum.begin(), riches_sum.end(), lack);
  if (it == riches_sum.end()) {
    std::cout << -1 << std::endl;
  } else {
    std::cout << std::distance(riches_sum.begin(), it) + poors.size() << std::endl;
  }

  return 0;
}

