int main(){

    // 1. 入力情報.
    int N;
    scanf("%d", &N);
    rep(i, N) scanf("%lld", &A[i]);
    rep(i, N) scanf("%lld", &B[i]);

    // 2. 数列 C[1], ... , C[N] を 構成できるか？
    priority_queue<LL> pq;
    LL diff = 0, ans = 0;
    rep(i, N){
        if(B[i] > A[i]) diff += (B[i] - A[i]), ans++;
        else            pq.push(A[i] - B[i]);
    }

    // 3. 数列 C[1], ... , C[N] を 構成できるか？
    while(!pq.empty()){
        LL d = pq.top();
        pq.pop();
        if(diff > 0) diff -= d, ans++;
        if(diff <= 0) break;
    }

    // 4. 出力.
    if(diff <= 0) printf("%d\n", ans); 
    else          puts("-1");
    return 0;

}

