void solve(long long N, std::vector<long long> A, std::vector<long long> B){
    // 総和のチェック
    if(accumulate(A.begin(), A.end(), 0) < accumulate(B.begin(), B.end(), 0)){
        cout << -1 << endl;
        return;
    }
    ll negnum = 0;
    ll negsum = 0;
    vector<ll> pos;
    REP(i, N){
        if(A.at(i) < B.at(i)){
            negnum++;
            negsum += B.at(i) - A.at(i);
        }else if(A.at(i) > B.at(i)){
            pos.push_back(A.at(i) - B.at(i));
        }
    }
    sort(pos.begin(), pos.end(), greater<ll>());
    ll tmp = 0;
    ll ans = 0;
    for(ans = 0; tmp < negsum; ++ans){
        tmp += pos.at(ans);
    }
    cout << ans + negnum << endl;
}

