signed main() {
    /* input part */
    int N;
    cin >> N;
    vint A(N), B(N);
    cin >> A >> B;
    vint pl, mi;
    for(int i : range(N)) {
        if(A[i] > B[i]) {
            pl.emplace_back(A[i] - B[i]);
        } else if(A[i] < B[i]) {
            mi.emplace_back(B[i] - A[i]);
        }
    }
    // print(pl, mi);
    if(sum(pl) < sum(mi)) {
        print(-1);
        return 0;
    }
    if(sum(mi) == 0) {
        print(0);
        return 0;
    }
    for(int i : range(1, pl.size())) pl[i] += pl[i - 1];
    // 汎用的な二分探索のテンプレ
    auto isOK = [&](int x, int v) -> bool { return pl[x] > v; };
    auto binary_search = [&](int key) {
        int ng = -1;  //「index = 0」が条件を満たすこともあるので、初期値は -1
        int ok = (int)pl.size();

        /* ok と ng のどちらが大きいかわからないことを考慮 */
        while(abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;

            if(isOK(mid, key))
                ok = mid;
            else
                ng = mid;
        }
        return ok;
    };
    print(binary_search(sum(mi)) + 1 + mi.size());
}

