			high.push_back(a[i] - b[i]);
		}
	}

	sort(all(high),[]( ll a,ll b){
		return a < b;
	});
	sort(all(low),[](ll a,ll b){
		return a > b;
	});
	int counter = 0;
	bool flag = true;
	while(low.size() > 0 && high.size() > 0){
		if(high[high.size()-1] + low[low.size() - 1] > 0){
			if(flag)
			{
				++counter;
				flag = false;
			}
			high[high.size()-1] += low[low.size() - 1];
			low.pop_back();
			++counter;
		}else if(high[high.size()-1] + low[low.size() - 1] < 0){
			high.pop_back();
			low.pop_back();
			counter +=2;
		}else{

			low[low.size() - 1] += high[high.size()-1];
			high.pop_back();
			flag = true;
		}
	}
	if(low.size() == 0)
		cout << counter;
	else
		cout << -1;

	return 0;
}

