void solve()
{
	sort(W, W + NN);
	int l = 0, r = NN - 1;
	modl = -1;	modr = NN;
	while (W[r] > 0) {
		if (W[l] + W[r] < 0) {
			W[l] += W[r];
			modr = r;
			modl = l;
			r--;
		}
		else {
			W[r] += W[l];
			modr = r;
			modl = l;
			if (W[r] == 0)
				r--;
			l++;
		}
	}
	cout << NN - max(0, modr - modl - 1) << endl;
}	

