			minus += b[i] - a[i];
		}
		else{
			plus.push(a[i] - b[i]);
		}
	}
	while(!plus.empty() && minus > 0){
		ll p = plus.top();
		plus.pop();
		minus -= p;
		++ans;
	}
	if(minus <= 0) cout << ans << endl;
	else cout << -1 << endl;
	return 0;
}

