                preparedness.push_back(A[i] - B[i]);
            }
            if(A[i] < B[i]){
                not_preparedness.push_back(A[i] - B[i]);
            }
        }
        if(not_preparedness.size() == 0){
            cout << 0 << endl;
            return 0;
        }
        int ans = not_preparedness.size();
        sort(preparedness.begin(), preparedness.end(), greater <long long>());
        sort(not_preparedness.begin(), not_preparedness.end());

        int not_preparedness_index = 0;
        //bool first_change = true;
        for(int i = 0; i < preparedness.size(); i++){
            ans ++;
            while(preparedness[i] > 0 && not_preparedness_index < not_preparedness.size()){
                if(preparedness[i] + not_preparedness[not_preparedness_index] >= 0){
                    preparedness[i] += not_preparedness[not_preparedness_index];
                    not_preparedness_index ++;
                } else {
                    not_preparedness[not_preparedness_index] += preparedness[i];
                    preparedness[i] = 0;
                }
