using namespace std;
struct exam{
    int a,b,c;
};
bool comp(exam x, exam y){
    return x.a - x.b < y.a - y.b;
}
exam arr[100001];
void solve(){
    int n,ans = 0,sum1 = 0,sum2 = 0;
    cin >> n;
    for(int i = 0; i < n; i++){
        cin >> arr[i].a;
        sum1 += arr[i].a;
        arr[i].c = arr[i].a;
    }
    for(int i = 0; i < n; i++){
        cin >> arr[i].b;
        sum2 += arr[i].b;
    }
    sort(arr,arr + n,comp);
    int ind = 0,last_ind = n - 1;
    while(arr[ind].b > arr[ind].c && sum1 >= sum2){
        if(arr[ind].b - arr[ind].c <= arr[last_ind].c - arr[last_ind].b){
            arr[last_ind].c -= (arr[ind].b - arr[ind].c);
            arr[ind].c = arr[ind].b;
            ind++;
        }
        else {
            arr[ind].c += (arr[last_ind].c - arr[last_ind].b);
            arr[last_ind].c = arr[last_ind].b;
            last_ind--;
        }
    }
    for(int i = 0; i < n; i++){
        if(arr[i].a != arr[i].c)ans++;
    }
    if(sum1 < sum2)ans = -1;
    cout << ans << endl;
}
