            insuf += B[i]-A[i];
            insuf_num++;
        }
    }

    if (insuf == 0) {
        cout << 0 << endl;
        return 0;
    }
    sort(diff, diff+N); //大幅に足りている→全然足りてない の順にソート

    int ans=0;
    bool flag = false;
    for (int i=0; diff[i].fi < 0; i++) {
        if (insuf > -(diff[i].fi)) {
            insuf += diff[i].fi;
            ans++;
        } else {
            flag = true;
            ans++;
            break;
        }
    }

    if (flag) {
        cout << ans + insuf_num << endl;
    } else {
        cout << -1 << endl;
    }
    return 0;
}

