int N;
ll A[100100], B[100100];
std::vector<P> v;
std::queue<ll> st;

int f(){
    ll rem = 0;
    int cnt = 0;

    for(auto &e : v){
        ll diff;
        int idx;

        std::tie(diff, idx) = e;

        if(diff > 0){
            st.emplace(diff);
        }else if(diff < 0){
            diff = -diff;

            while(rem < diff && !st.empty()){
                rem += st.front();
                cnt += 1;
                st.pop();
            }

            if(rem < diff){
                return -1;
            }

            rem -= diff;
            cnt += 1;
        }
    }

    return cnt;
}

