using namespace std;

class Solution {
  struct Exam {
    int a, b;
  };
  vector<Exam> A;
  int n;
public:
  void run(istream &in, ostream &out) {
    in >> n;
    A.resize(n);
    long long suv = 0, need = 0;
    for (int i = 0; i < n; ++i) in >> A[i].a, suv += A[i].a;
    for (int i = 0; i < n; ++i) in >> A[i].b, need += A[i].b;
    if (suv < need) {
      out << -1 << '\n';
      return;
    }
    need = 0;
    vector<int> left;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
      if (A[i].a < A[i].b) need += A[i].b - A[i].a, ++ans;
      else left.push_back(A[i].a - A[i].b);
    }
    sort(left.begin(), left.end(), greater<int>());
    int i = 0;
    while (need > 0) {
      need -= left[i++];
    }
    out << ans + i << '\n';
  }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  Solution().run(cin, cout);
  return 0;
}

