    ll N;
    cin >> N;
    vector<ll> As;
    As.reserve(N);
    copy_n(istream_iterator<ll>(cin), N, back_inserter(As));
    vector<ll> Bs;
    Bs.reserve(N);
    copy_n(istream_iterator<ll>(cin), N, back_inserter(Bs));

    vector<ll> ABdiffs;
    ABdiffs.reserve(N);
    transform(begin(As), end(As), begin(Bs), back_inserter(ABdiffs),
        [](int a, int b) { return a - b; });

    // 準備度が足りない試験の数
    auto ans = count_if(begin(ABdiffs), end(ABdiffs), [](auto n) { return n < 0; });

    // 足りない準備度の合計
    auto short_point_total = accumulate(begin(ABdiffs), end(ABdiffs), 0LL,
        [](auto acc, auto n) {
            return (n >= 0) ? acc : acc - n;
        });
    if (short_point_total <= 0) {
        cout << 0 << endl;
        return;
    }

    sort(begin(ABdiffs), end(ABdiffs), greater<ll>());

    // 準備度に余裕のある試験から順に余剰準備度の累積和を計算
    vector<ll> enough_sums;
    partial_sum(begin(ABdiffs), end(ABdiffs), back_inserter(enough_sums));

    auto it = lower_bound(begin(enough_sums), end(enough_sums), short_point_total);
    if (it == end(enough_sums)) {
        cout << -1 << endl;
        return;
    }

    ans += distance(begin(enough_sums), it) + 1;
    cout << ans << "\n";
}
int main()
{
    cin.tie(nullptr);
    cout.tie(nullptr);
    ios_base::sync_with_stdio(false);
    main_();
    return 0;
}

