#include <bits/stdc++.h>
using namespace std;
int main() {
	int N;
	int i,j,k,acount=0,atotal=0,ccount=0,flg;
	cin >> N;
	vector <int> A(N);
	vector <int> B(N);
	vector <int> C(N);
	for (i = 0; i < N; i++) {
		cin >> A.at(i);			// 準備度入力
	}
	for (i = 0; i < N; i++) {
		cin >> B.at(i);			// 合格ライン入力
		k = A.at(i) - B.at(i);
		if(k < 0) {			// 準備不足
			acount++;		// acount：準備不足な試験数（調整で変更される対象）
			atotal-=k;		// atotal：準備不足数の合計
		}
		else if(k > 0) {		// 準備余裕（不足分を埋める候補）
			C.at(ccount) = k;	// C: 余裕数
			ccount++;		// ccount：余裕がある試験数
		}
	}
//	if(acount == 0) {			// acount=0:全て準備が十分
//		cout << acount << endl;		// 変更になる数が0、acountをそのまま出力
//		return 0;
//	}
	flg = 1;				// 不足を埋める候補を降順ソートする
	while(flg == 1) {
		flg = 0;
		for(i = 1;i<ccount;i++) {
			if(C.at(i) > C.at(i-1)) {
				j = C.at(i);
				C.at(i) = C.at(i-1);
				C.at(i-1) = j;
				flg = 1;
			}
		}
	}
	i = 0;
	while ((i < ccount) && (atotal > 0)) {	// 不足を埋める候補があり かつ 準備不足の調整残がある
		atotal-=C.at(i);		// 大きい数の埋める候補から調整に使用していく
		i++;				// 不足を埋める為に使われた個数、変更になる数に加算
	}
	if(atotal > 0) {			// 不足が埋めきれないのでｰ1を出力
		cout << "-1" << endl;
	}
	else {					// 不足の調整が済んだ
		cout << (acount + i) << endl;	// acount：不足を埋めてもらった試験数、i：不足を埋めるのに使われた試験数
	}
	return 0;
}

