			minus+=abs(A[i]-B[i]);
			ans++;
		}

	}
	if(minus==0){
		p(0);return;
	}
	while(minus>0 && !q.empty()){
		ll t=q.top();
		q.pop();
		minus-=t;
		ans++;
	}

	if(minus>0){
		p(-1);return;
	}
	printf("%lld\n", ans);

}

