const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 100010

ll N;
vector<ll> A, B;

vector<ll> C;
vector< pair<ll, ll> > sub; // first: B[i] - A[i] second: i

ll solve() {
    ll sum_a = 0, sum_b = 0;        // 総和
    vector<ll> remain;              // 条件を満たしていない C のインデックス
    // C と sub の作成
    REP(i, N) {
        C.push_back(A[i]);
        sum_a += A[i];
        sum_b += B[i];
        if(B[i] - A[i] > 0) { remain.push_back(i); }
        if(A[i] - B[i] > 0) {
            sub.push_back(make_pair(A[i] - B[i], i));
        }
    }
    // 総和が負けてるなら無理
    if(sum_a < sum_b) { return -1; }
    if(remain.size() == 0) { return 0; }

    sort(sub.begin(), sub.end(), greater< pair<ll, ll> >());
    // 差が大きいやつから余剰を分配
    for(auto& s : sub) {
        ll val = s.first;
        ll ind = s.second;

        while(val > 0 && remain.size() > 0) {
            ll c_ind = remain[remain.size()-1];
            remain.pop_back();
            ll c_need = B[c_ind] - C[c_ind];     // 条件を満たすために必要な値
            if(c_need <= val) {
                C[c_ind] += c_need;
                val -= c_need;
            }
            else {
                C[c_ind] += val;
                val = 0;
                remain.push_back(c_ind);
            }
        }
        C[ind] = B[ind] + val;
        if(remain.size() == 0) { break; }
    }
    // ret の作成
    ll ret = 0;
    REP(i, N) {
        if(A[i] != C[i]) { ret++; }
    }
    return ret;
}

signed main()
{
    cin >> N;
    A.resize(N);
    REP(i, N) { cin >> A[i]; }
    B.resize(N);
    REP(i, N) { cin >> B[i]; }
    ll ans = solve();
    printf("%lld\n", ans);
    return 0;
}

