int main()
{
    long long n, ans, suma, sumb;
    cin >> n;
    vector<long long> a(n);
    vector<long long> b(n);
    vector<long long> diff_minus;
    priority_queue<long long> diff_plus;
    ans = 0;
    suma = 0;
    sumb = 0;
    for (int i=0; i<n; ++i){
        cin >> a[i];
        suma += a[i];
    }
    for (int i=0; i<n; ++i){
        cin >> b[i];
        sumb += b[i];
    }
    if(suma < sumb){
        ans = -1;
    }
    else {
        for (int i=0; i<n; ++i){
            if(a[i] == b[i]){
                continue;
            }
            else {
                long long diff = a[i] - b[i];
                if(diff < 0){
                    diff_minus.push_back(diff);
                }
                else if(diff > 0){
                    diff_plus.push(diff);
                }
            }
        }
        long long plus_itr = 0;
        sort(diff_minus.begin(), diff_minus.end());
        long long p = 0;
        for (int i=0; i<diff_minus.size(); ++i){
            long long d = diff_minus[i];
            // cout << i+1 << " -> " << d << endl;
            while(d < 0){
                if(p > 0){
                    if(abs(d) <= abs(p)){
                        p += d;
                        d = 0;
                    }
                    else {
                        d += p;
                        p = 0;
                    }
                    // cout << "(d, p) -> " << d << ", " << p << endl;
                }
                else if(p == 0){
                    p = diff_plus.top();
                    diff_plus.pop();
                    plus_itr++;
                }
            }
        }
        ans = plus_itr + diff_minus.size();
    }
    cout << ans << endl;
    return 0;
}

