    sort(diffAB,diffAB+N);
    for(long long i=0;i<N;i++){
        DEBUG(diffAB[i]);
    }
    long long l=0,r=N-1;
    bool changed=false;
    while(diffAB[l]<0){
        while(diffAB[l]<0){
            if(diffAB[l]<=-diffAB[r]){
                diffAB[l]+=diffAB[r];
                diffAB[r]=0;
                r--;
                changed=false;
            }else{
                diffAB[r]+=diffAB[l];
                diffAB[l]=0;
                changed=true;
            }
        }
        l++;
    }
    DEBUG(l);
    DEBUG(r);
    DEBUG(changed);
    ans=l+(N-r-1)+(changed?1:0);
    cout<<ans<<endl;
    return ;
}

