int main(){
	int N;
	cin >> N;

	long int i, j, A[N], B[N];
	for(i=0; i<N; i++){
		cin >> A[i];
	}
	for(i=0; i<N; i++){
		cin >> B[i];
	}

	int ans = 0;
	long int C[i];//各々の猶予分
	long int D[i];//C>0のときの移す場
	long int minus = 0;//不足分の合計
	long int plus = 0;
	j=0;

	for(i=0; i<N; i++){
		C[i] = A[i] - B[i];
		if(C[i]<0){
			minus += C[i];
			ans++;
		}
		if(C[i]>0){
			plus += C[i];
			D[j] = C[i];
			j++;
		}
	}


	if(minus + plus < 0){
		cout << -1 << endl;
		return 0;
	}

	int dj = j;

	if(ans == 0){//不足している組合せがない
		cout << ans << endl;
		return 0;
	}

	//小さい順に並べる
	for(j=0; j<dj; j++){
		for(i=0; i<dj-1; i++){
			if(D[i]>D[i+1]){
				int tmp = D[i];
				D[i] = D[i+1];
				D[i+1] = tmp;
			}
		}
	}


	i = dj-1;
	do{
		minus += D[i];
		i--;
		ans++;
	}while(minus<0);

	cout << ans << endl;
	return 0;
}

