typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef vector<int> vi;
typedef vector<ll> vl;
const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

void solve(long long N, std::vector<long long> A, std::vector<long long> B) {
  vl C(N);

  priority_queue<pll> pq;

  // 足りないところは補填する
  ll supplied = 0;
  rep(n, N) {
    if (A[n] < B[n]) {
      C[n] = B[n];
      supplied += B[n] - A[n];
    } else {
      C[n] = A[n];
      if (A[n] - B[n] != 0) {
        pq.push(mp(A[n] - B[n], n));
      }
    }
  }

  // 補填するときは、差が少ないところから
  while (!pq.empty() && supplied > 0) {
    pll top = pq.top();
    ll minus = min(supplied, top.first);
    ll n = top.second;
    C[n] = A[n] - minus;
    supplied -= minus;
    pq.pop();
  }

  if (supplied > 0) {
    print(-1);
    return;
  }

  // iの個数を取得する
  ll ans = 0;
  rep(n, N) {
    if (A[n] != C[n]) {
      ans++;
    }
  }
  print(ans);
}

int main() {
  long long N;
  scanf("%lld", &N);
  std::vector<long long> A(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &A[i]);
  }
  std::vector<long long> B(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &B[i]);
  }
  solve(N, std::move(A), std::move(B));
  return 0;
}

