    auto Bs = read<i64>(N);
    auto ps = Vector<i64>();
    ps.reserve(N);
    auto ns = Vector<i64>();
    ns.reserve(N);
    REP (i, N) {
        auto X = As[i] - Bs[i];
        if (X > 0) {
            ps.push_back(X);
        } else if (X < 0) {
            ns.push_back(X);
        }
    }

    sort(CTR(ps));
    reverse(CTR(ps));
    auto total = - std::accumulate(CTR(ns), i64(0));
    i64 ans = ns.size();
    REP (i, ps.size()) {
        if (total <= 0) {
            break ;
        }
        total -= ps[i];
        ans += 1;
    }

    if (total <= 0) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
}

