int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for(int i=0;i<n;i++) cin >> a[i];
    vector<int> b(n);
    for(int i=0;i<n;i++) cin >> b[i];
    vector<int> d(n);
    for(int i = 0; i < n; i++) d[i]=-b[i]+a[i];
    int m=0;
    vector<int> x;
    queue<int> q,y;
    for(int i = 0; i < n; i++) {
        if(d[i]<0) {
            m++;
            y.push(d[i]);
        }
        if(d[i]>0){
            x.push_back(d[i]);
        }
    }
    sort(x.begin(),x.end());
    reverse(x.begin(),x.end());
    int z=x.size();
    for(int i = 0; i < z; i++) {
        q.push(x[i]);
    }
    int p=0;
    while(!q.empty() && !y.empty()){
        int l=q.front();
        q.pop();
        p++;
        while(l>0 && !y.empty()){
            int r=y.front();
            y.pop();
            if(l>=abs(r)) l += r;
            else{
                l=0;
                r += l;
                y.push(r);
            }
        }
    }
    if(y.empty()){
        cout << m+p << endl;
    }
    else{
        cout << -1 << endl;
    }

    return 0;
}

