    rest_sum += rest;
    if (rest > 0) {
      rests.push_back(rest);
    }
    if (lack > 0) {
      lack_cnt++;
    }
  }

  if (lack_sum > rest_sum) {
    cout << -1 << endl;
    return 0;
  }

  if (lack_sum == 0) {
    cout << 0 << endl;
    return 0;
  }

  sort(rests.begin(), rests.end(), greater<int>());

  for (int i = 1; i < rests.size(); i++) {
    rests[i] += rests[i - 1];
  }

  if (rests.size() == 1) {
    cout << lack_cnt + 1 << endl;
    return 0;
  }

  int l = 0, r = rests.size();
  while (r - l > 1) {
    int m = (l + r) / 2;
    if (rests[m] >= lack_sum) {
      r = m;
    } else {
      l = m;
    }
  }

  cout << lack_cnt + r + 1 << endl;

  return 0;
}

