int main(){
    int n;cin >>n;
    vector<int> a(n),b(n);
    ll sum_a=0,sum_b=0;
    REP(i,n){
        cin >> a[i];
        sum_a+=a[i];
    }
    REP(i,n){
        cin >> b[i];
        sum_b+=b[i];
    }
    int ans=0;
    if(sum_a<sum_b)ans=-1;
    else{
        vector<int> diff;
        ll sum_diff=0;
        REP(i,n){
            if(a[i]<b[i]){
                sum_diff+=(b[i]-a[i]);
                ans++;
            }
            else if(a[i]>b[i]){
                diff.push_back(a[i]-b[i]);
            }
        }
        sort(diff.begin(),diff.end(),greater<>());
        if(ans!=0){
            for(int x:diff){
                sum_diff-=x;
                ans++;
                if(sum_diff<=0)break;
            }
        }
    }
    COUT(ans);
    return 0;
}

