  }
  vector<int> d(n);
  for (int i=0; i<n; i++){
    d.at(i) = a.at(i) - b.at(i);
  }
  sort(d.begin(), d.end());
  int j=0; //j：A<Bとなる個数
  for (int i=0; i<n; i++){
    if (d.at(i) < 0){
      j++;
    }
    else break;
  }

  if (j == 0){
    cout << 0 << endl;
  }

  else if (j == n){
    cout << -1 << endl;
  }

  else {
  int dif = 0;
