  int k=1; //k:分配に必要な個数
  int x=0;
  for (int i=0; i<n-j; i++){
    x += d.at(n-1-i);
    if (x >= dif*(-1)){
      cout << j+k << endl;
      break;
    }
    if (i == n-j-1 && x < dif*(-1)){
      cout << -1 << endl;
      break;
    }
