void solve()
{
	READ(llong, N);
	auto A = read<llong>(N);
	auto B = read<llong>(N);
	auto C = deque<llong>();
	llong totalA = accumulate(allof(A),0ll);
	llong totalB = accumulate(allof(B),0ll);
	if (totalB > totalA )
	{
		WRITE(-1);
		return;
	}

	REP(i, N)
	{
		C.push_back(A[i] - B[i]);
	}
	sort(allof(C));

	int ans = 0;
	int sp = 0;
	while (!C.empty() && C.front() < 0)
	{
		llong need = -C.front();
		while(sp < need)
		{
			ans++;
			sp += C.back();
			C.pop_back();
		}

		ans++;
		sp -= need;
		C.pop_front();
	}

	WRITE(ans);
}

