            amari.push(A[i] - B[i]);
    }
    ll sum = 0;
    while (sum < S || !amari.empty())
    {
        answer++;
        sum += amari.top();
        amari.pop();
    }
    if (sum >= S)
    {
        ans(answer);
        return 0;
    }
    else
    {
        ans(-1);
        return 0;
    }
