	for(ll i=0;i<N;i++){
		cin >> A[i];
	}
	for(ll i=0;i<N;i++){
		cin >> B[i];
	}

	ll S = 0;
	ll num1 = 0;
	vector<ll> res;
	for(int i=0;i<N;i++){
		if(A[i]<B[i]){
			S += B[i]-A[i];
			num1 ++;
		}
		else{
			res.push_back(A[i]-B[i]);
		}
	}

	ll sum(0);
	for(ll i=0; i<res.size(); i++){
		sum += res[i];
	}

	if(num1==0) cout << 0 << endl;
	else if(sum < S) cout << -1 << endl;
	else{
		std::sort(res.begin(), res.end(), std::greater<ll>());
		ll sum2(0);
		ll num2(0);
		while(sum2 < S){
			sum2 += res[num2];
			num2 ++;
		}
		cout << num1+num2 << endl;
	}

	return 0;
}

