using namespace std;

int main(int argc, char *argv[]) {
    int N;
    cin >> N;

    int cur;
    vector<int> a_arr;
    vector<int> b_arr;
    for (int i = 0; i < N; i++) {
        cin >> cur;
        a_arr.push_back(cur);
    }
    for (int j = 0; j < N; j++) {
        cin >> cur;
        b_arr.push_back(cur);
    }

    int ans = 0;
    int64_t sum_a = accumulate(a_arr.begin(), a_arr.end(), 0);
    int64_t sum_b = accumulate(b_arr.begin(), b_arr.end(), 0);

    int64_t sum_sub = 0;
    vector<int> m;
    if (sum_b > sum_a) {
        ans = -1;
    } else {
        int same = 0;
        for (int k = 0; k < N; k++) {
            if (a_arr[k] < b_arr[k]) {
                ans++;
                int sub_b = b_arr[k] - a_arr[k];
                sum_sub += sub_b;
            } else if (a_arr[k] == b_arr[k]) {
                // do nothing
                same++;
            } else {
                int sub_a = a_arr[k] - b_arr[k];
                m.push_back(sub_a);
            }
        }
        sort(m.begin(), m.end(), greater<int>());

        if (sum_sub > 0) {
            sum_sub += same;
            for (int l = 0; l < m.size(); ) {
                if (m[l] >= sum_sub) {
                    ans++;
                    break;
                } else {
                    sum_sub -= m[l];
                    ans++;
                    l++;
                }
                if (sum_sub == 0) {
                    break;
                }
            }
        }
    }

    cout << ans << endl; 
	return 0;
}

