void solve() {
    int N;
    cin >> N;
    vector<ll> A(N), B(N);
    ll sumA = 0, sumB = 0;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        sumA += A[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> B[i];
        sumB += B[i];
    }
    if (sumA < sumB) {
        cout << -1 << endl;
        return;
    }
    priority_queue<ll> Q;

    ll sum = 0;
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] >= B[i]) {
            Q.push(A[i] - B[i]);
        } else {
            sum += B[i] - A[i];
            ans++;
        }
    }

    while(!Q.empty() && sum > 0) {
        sum -= Q.top(); Q.pop();
        ans++;
    }

    cout << ans << endl;

}

