using namespace std;

typedef long long ll;

int N;
vector<int> A, B, D;

void input_init(void) {
	cin >> N;
	A.resize(N);
	B.resize(N);
	D.resize(N);
	for (int i = 0; i < N; ++i)
		cin >> A[i];
	for (int i = 0; i < N; ++i)
		cin >> B[i];
	for (int i = 0; i < N; ++i)
		D[i] = A[i] - B[i];
}

int solve(void) {
	ll sum = accumulate(D.begin(), D.end(), (ll)0);
	if (sum < (ll)0)
		return -1;

	sort(D.begin(), D.end());
	int cnt = 0;
	ll minus_v = (ll)0;
	for (int i = 0; i < N; ++i) {
		if (D[i] >= 0)
			break;
		minus_v += (ll)D[i];
		++cnt;
	}
	if (cnt != 0) {
		for (int i = N - 1; i >= 0; --i) {
			++cnt;
			minus_v += (ll)D[i];
			if (minus_v >= 0)
				break;
		}
	}
	return cnt;
}

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	input_init();
	int ans = solve();

	cout << ans << '\n';
	return 0;
}

