const int N = 100 * 1000 + 10;

int n;
int A[N], B[N];
vector <int> extra;
long long need;

void input() {
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> A[i];
    for (int i = 0; i < n; i++)
        cin >> B[i];
    return;
}

void solve() {
    int cnt = 0;
    for (int i = 0; i < n; i++)
        if (A[i] - B[i] > 0)
            extra.push_back(A[i] - B[i]) ;
        else if (A[i] - B[i] < 0) {
            need += B[i] - A[i];
            cnt++;
        }

    sort(extra.begin(), extra.end(), greater <int> ()) ;

    int pnt = 0;
    while (need > 0 && pnt < extra.size())
        need -= extra[pnt++];

    if (need > 0)
        cout << -1 << endl;
    else
        cout << pnt + cnt << endl;
    return;
}

int main() {
    input() ;
    solve() ;
    return 0;
}

