#include <bits/stdc++.h>
using namespace std;
int main() {
	int N;
	int i,j,k,l,ac=0,at=0,cc=0;
	cin >> N;
	vector <int> A(N);
	vector <int> B(N);
	vector <int> C(N);
	for (i = 0; i < N; i++) {
		cin >> A.at(i);			// 準備ライン
	}
	for (i = 0; i < N; i++) {		// 合格ライン
		cin >> B.at(i);	
	}
	for(i=0;i<N;i++) {
		j = A.at(i) - B.at(i);
		if(j < 0) {
			ac++;			// 補充数
			at-=j;			// 補充総量
		}
		else if(j > 0) {
			C.at(cc) = j;		// 補充可能総量
			cc++;			// 補充可能数
		}
	}
	k = 1;					// 補充候補を降順ソート
	while(k==1) {
		k = 0;
		for(l=1;l<cc;l++) {
			if(C.at(l) > C.at(l-1)) {
				j = C.at(l);
				C.at(l) = C.at(l-1);
				C.at(l-1) = j;
				k = 1;
			}
		}
	}
	i = 0;
	while(i < cc) {
		at-=C.at(i);
		if(at > 0) {
			i++;
		}
		else {
			break;
		}
	}
	if(at > 0) {
		cout << "-1" << endl;
	}
	else {
		cout << (ac + i + 1) << endl;
	}
	return 0;
}

