        d[i] = a[i] - b[i];
        if(d[i] < 0) msum += -d[i];
    }
    if(bsum > asum) {
        cout << -1 << endl;
        return;
    }
    if(cnt == 0) {
        cout << 0 << endl;
        return;
    }
    sort(all(d));
    reverse(all(d));
    vector<int> dsum(n + 1, 0);
    rep(i, n) {
        dsum[i + 1] = dsum[i] + d[i];
    }
    int pcnt = lower_bound(all(dsum), msum) - dsum.begin();
    cout << cnt + pcnt << endl;
}

