			c.push_back(a[i] - b[i]);
		} else if (a[i] < b[i]) {
			d.push_back(b[i] - a[i]);
		}
	}
	LL x = accumulate(c.begin(), c.end(), 0LL);
	LL y = accumulate(d.begin(), d.end(), 0LL);
	int ans = 0;
	if (y > x) {
		ans = -1;
	} else if (y > 0) {
		int i = 0;
		sort(c.rbegin(), c.rend());
		sort(d.rbegin(), d.rend());
		LL p = 0, q = 0;
		for (LL r : d) {
			++ans;
			q = r;
			while (q > 0) {
				if (!p) {
					++ans;
					p = c[i++];
				}
				LL e = min(p, q);
				p -= e;
				q -= e;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

