const int MOD = 1000000007;  // 1 000 000 007


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N;
    cin >> N;
    vector<ll> Taka(N), Must(N);
    REP(i, N) cin >> Taka[i];
    REP(i, N) cin >> Must[i];

    // calculation
    int sum = 0;
    REP(i, N) {
        if (Taka[i] >= Must[i]) sum++;
    }

    if (sum == N) {
        cout << 0 << "\n";
    } else if (SUM(Taka) < SUM(Must)) {
        cout << -1 << "\n";
    } else {
        vector<ll> Taka_plus, Taka_minus;
        REP(i, N) {
            if (Taka[i] > Must[i]) {
                Taka_plus.push_back(Taka[i] - Must[i]);
            } else if (Taka[i] < Must[i]) {
                Taka_minus.push_back(Taka[i] - Must[i]);
            }
        }

        ll minus = SUM(Taka_minus);
        sort(Taka_plus.begin(), Taka_plus.end(), greater<ll>());  // int big -> small

        ll num = (ll)Taka_minus.size(), len = (ll)Taka_plus.size();

        REP(i, len) {
            num++;
            minus += Taka_plus[i];
            if (minus >= 0) {
                cout << num << "\n";
                return 0;
            }
        }

        cout << -1 << "\n";
    }

    return 0;
}

