			REP(j, G[i].size()) {
				if (d[G[i][j].to] > d[i] + G[i][j].cap) {
					d[G[i][j].to] = d[i] + G[i][j].cap;
				}						   
			}
		}
	}
	REP(k, G.size() - 2) {
		REP(i, G.size()) {
			REP(j, G[i].size()) {
				if (d[G[i][j].to] > d[i] + G[i][j].cap) {
					d[G[i][j].to] = d[i] + G[i][j].cap;
