void solve(long long N, vector<long long> A, vector<long long> B){
  long long suma = accumulate(A.begin(), A.end(), 0LL);
  long long sumb = accumulate(B.begin(), B.end(), 0LL);
  if (suma < sumb) {
    std::cout << -1 << std::endl;
    return;
  }
  vector<long long> diff(N, 0);
  for (int i = 0; i < N; i++) {
    diff[i] = A[i] - B[i];
  }

  sort(diff.begin(), diff.end());
  long long minus_amount = 0LL;
  long long ret = 0LL;
  for (int i = 0; i < N; i++) {
    if (diff[i] < 0) {
      minus_amount += diff[i];
      ret++;
    } else {
      break;
    }
  }
  for (int i = N-1; i >= 0; i--) {
    if (minus_amount >= 0) {
      std::cout << ret << std::endl;
      return;
    }
    minus_amount += diff[i];
    ret++;
  }
}

