		sum_a += A[i];
	}

	for (i = 0; i < N; i++) {
		scanf("%llu", &B[i]);
		sum_b += B[i];

		diff[i] = A[i] - B[i];
	}

	if (sum_a < sum_b) {
		printf("-1\n");
		return 0;
	}

	// for (i = 0; i < N; i++) {
	// 	printf("%lld ", diff[i]);
	// }
