	// for (i = 0; i < N; i++) {
	// 	printf("%lld ", diff[i]);
	// }
	// printf("\n");

	if (0 <= diff[0]) {
		printf("0\n");
		return 0;
	}

	for (i = 0, j = N-1; i < j && diff[i] < 0; i++) {
		if (-diff[i] < diff[j]) {
			diff[j] += diff[i];
		} else {
			diff[i] += diff[j];
			diff[j] = 0;
