			ac++;			// 補充数
			at = at - j;		// 補充総量
		}
		else if(j > 0) {
			C.at(cc) = j;		// 補充可能総量
			cc++;			// 補充可能数
		}
	}
	k = 1;					// 補充候補を降順ソート
	while(k==1) {
		k = 0;
		for(l=1;l<cc;l++) {
			if(C.at(l) > C.at(l-1)) {
				j = C.at(l);
				C.at(l) = C.at(l-1);
				C.at(l-1) = j;
				k = 1;
			}
		}
	}
	i = 0;
	while(i < cc) {
		at = at - C.at(i);
		if(at > 0) {
			i++;
		}
		else {
			cout << (ac + i + 1) << endl;
			return 0;
		}
	}
	cout << "-1" << endl;
	return 0;
}

