ll b[100010];
ll d[100010];
int solve(){
  if(accumulate(a,a+n, 0LL)<accumulate(b,b+n, 0LL)) return -1;
  REP(i,n)d[i]=a[i]-b[i];
  sort(d,d+n,greater<int>());
  int zero;
  ll lack=0;
  for(int i=0;i<n;i++){
    if(d[i]>=0){
      zero=i+1;
      continue;
    }
    lack-=d[i];
  }
  if(n==zero) return 0;
  for(int i=1;i<zero;i++){
    d[i]+=d[i-1];
  }
  int used=distance(d,lower_bound(d,d+zero,lack))+1;
  return n-zero+used;
}

