auto findIncrement(int N, vector<long long> &A, const vector<long long> &B)
{
	for (int i = 0; i < N; ++i) {
		if (A[i] < B[i]) {
			return i;
		}
	}
	return N;
}

auto findDecrement(int N, vector<long long> &A, const vector<long long> &B)
{
	auto k = N;

	for (int i = 0; i < N; ++i) {
		if (A[i] > B[i]) {
			if (k == N || A[i] - B[i] > A[k] - B[k]) {
				k = i;
			}
		}
	}
	return k;
}

vector<long long> solve(int N, const vector<long long> &A, const vector<long long> &B)
{
	auto C = A;
	for (;;) {
		int dec = findDecrement(N, C, B);
		if (dec == N) {
			return C;
		}
		for (;;) {
			int inc = findIncrement(N, C, B);
			if (inc == N) {
				return C;
			}
			long long x = min(C[dec] - B[dec], B[inc] - C[inc]);
			C[inc] += x;
			C[dec] -= x;
			if (C[dec] == B[dec]) {
				break;
			}
		}
	}
}

