using namespace std;

typedef long long ll;
typedef pair<int, ll> P;

bool pairCompare(const P &firstElof, const P &secondElof)
{
    return firstElof.second < secondElof.second;
}

int main() {
    int N, i;
    scanf("%d",&N);
    ll A[N],B;
    P D[N];
    for (i=0; i<N; i++) 
        scanf("%lld",&A[i]);
    for (i=0; i<N; i++) {
        scanf("%lld",&B);
        D[i].first = i;
        D[i].second = A[i]-B;
    }
    sort(D, D+N, pairCompare);
    int a=0, b=N-1, count=0, last=0;
    if (D[0].second >= 0) count = 0;
    while (true) {
        if (D[a].second >= 0 || a >= b) break;
        if (D[b].second <= 0) {
            printf("-1\n");
            return 0;
        }
        if (D[a].second + D[b].second > 0) {
            D[b].second += D[a].second;
            D[a].second = 0;
            a++;
            count++;
            last = 1;
        } else if (D[a].second + D[b].second == 0) {
            D[a].second = 0;
            D[b].second = 0;
            a++;
            b--;
            count += 2;
            last = 0;
        } else {
            D[a].second += D[b].second;
            D[b].second = 0;
            b--;
            count++;
            last = 1;
        }
    }
    count += last;
    printf("%d\n",count);
    return 0;
}

