    /* A, Bの取得 */
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    for (int i = 0; i < N; i++) {
        cin >> B[i];
    }

    /* A < Bとなるものを数える */
    int result = 0;
    long long num = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] < B[i]) {
            result++;
            num += B[i] - A[i];
            sabun[i] = 0;
        } else {
            sabun[i] = A[i] - B[i];
        }
    }
    if (result != 0) {
        sort(sabun, sabun + N);
        for (int i = N - 1; i >= 0; i--) {
            result++;
            if (num - sabun[i] <= 0) {
                break;
            } else {
                num -= sabun[i];
            }
            if (i == 0) {
                result = -1;
            }
        }
    }

    /* 結果の出力 */
    cout << result << endl;

    return 0;
}

