  ll tsub = 0;
  int res = 0;
  for(int i = 0;i < n;i++) {
    if(a[i] < b[i]) {
      tsub -= b[i]-a[i];
      a[i]+= b[i] - a[i];
      res++;
    }
  }

  for(int i = 0;i < n;i++){
    if(a[i] > b[i]) {
      ll tmp = a[i] - b[i];
      tsub += tmp;
      res++;
    }
    if(tsub > 0) {
      break;
    }
  }

  if(sub >= 0) {
    cout << res << endl;
  } else {
    cout << -1 << endl;
  }

}

