        if(a[i] - b[i] > 0){
            plus.push_back(a[i]-b[i]);
        }
        else if(a[i] - b[i] < 0){
            minus.push_back(b[i]-a[i]);
        }
    }

    sort(plus.begin(), plus.end(), greater<long long>());
    sort(minus.begin(), minus.end(), greater<long long>());

    if(minus.size() == 0){
        printf("0\n");
        return 0;
    }

    long long count = 0;

    while(minus.size() != 0){
        if(plus[0] > minus[0]){
            plus[0] -= minus[0];
            count++;
            minus.erase(minus.begin());
        }
        else if(plus[0] < minus[0]){
            minus[0] -= plus[0];
            count++;
            plus.erase(plus.begin());
        }
        else{
            count += 2;
            minus.erase(minus.begin());
            plus.erase(plus.begin());
        }
    }

