  cin >> N;
  vector<int> A;
  vector<int> B;
  vector<int> C;
  rep(i, N) {
    int a;
    cin >> a;
    A.push_back(a);
  }
  rep(i, N) {
    int b;
    cin >> b;
    B.push_back(b);
  }

  if (accumulate(A.begin(), A.end(), 0) < accumulate(B.begin(), B.end(), 0)) {
    cout << -1 << endl;
    return 0;
  }

  // 差をとる
  vector<int> D;
  rep(i, N) {
    int d = A[i] - B[i];
    D.push_back(d);
  }
  sort(D.begin(), D.end());
  // cout << "sorted" << endl;
  // printV(D);

  int count = 0;
  int temp = 0;
  int i = 0;
  while (true) {
    //終了条件
    if (D[i] >= 0) {
      break;
    }

    // 大きいほうの値をかりる
    if (temp <= 0) {
      for (int j = N; j >= 0; j--) {
        if (D[j] > 0) {
          temp = D[j];
          D[j] = 0;
          count++;
          // cout << "big" << endl;
          // printV(D);
          break;
        }
      }
    }

    // 小さいやつに分け与える
    if (-D[i] > temp) {
      D[i] += temp;
      temp = 0;
    } else {
      temp += D[i];
      D[i] = 0;
      count++;
      i++;
    }
    // cout << "temp" << temp << endl;
    // printV(D);
  }

  cout << count << endl;

  return 0;
}

