int N;
ll A[int(1e5 + 5)], B[int(1e5 + 5)];
ll deg[int(1e5 + 5)];
bool visited[int(1e5 + 5)];

int main(){
  cin >> N;
  ll suma = 0, sumb = 0;
  for (int i = 0; i < N; i++) cin >> A[i], suma += A[i];
  for (int i = 0; i < N; i++) cin >> B[i], sumb += B[i];

  if (suma < sumb){
    cout << -1 << endl;
    return 0;
  }

  for (int i = 0; i < N; i++){
    deg[i] = A[i] - B[i];
  }
  sort(deg, deg + N);

  int ans = 0, R = N - 1;
  for (int i = 0; i < N; i++){
    if (deg[i] >= 0) break;
    ans++;
    while (deg[i] < 0){
      if (!visited[R]){
        ans++; visited[R] = true;
      }
      if (deg[i] + deg[R] >= 0){
        deg[R] += deg[i];
        deg[i] = 0;
        continue;
      }else{
        deg[i] += deg[R];
        R--;
      }
    }
  }

  cout << ans << endl;

  return 0;
}

