typedef long long ll;

using namespace std;

int main()
{
	ll N = 0;
	cin >> N;

	std::vector<ll> A(N);
	std::vector<ll> B(N);

	for (ll i = 0; i < N; ++i)
	{
		cin >> A[i];
	}

	for (ll i = 0; i < N; ++i)
	{
		cin >> B[i];
	}

	vector<bool> changed(N);
	for (ll i = 0; i < N; ++i)
	{
		changed[i] = false;
	}

	std::vector<ll> husoku(N);
	for (ll i = 0; i < N; ++i)
	{
		husoku[i] = B[i] - A[i];
	}

	while (true)
	{
		ll idx_max_husoku = max_element(husoku.begin(), husoku.end()) - husoku.begin();
		ll max_husoku = husoku[idx_max_husoku];
		if (max_husoku <= 0)
		{
			break;
		}

		ll idx_min_gap = -1;
		for (ll i = 0; i < N; ++i)
		{
			//if (husoku[i] > 0) continue;
			ll gap = A[idx_max_husoku] - B[i];
			if (gap >= 0)
			{
				if (idx_min_gap == -1)
				{
					idx_min_gap = i;
					continue;
				}
				else
				{
					if (gap < A[idx_max_husoku] - B[idx_min_gap])
					{
						idx_min_gap = i;
					}
				}
			}
		}

		const ll idx_max_yoyu = idx_min_gap;

		if (idx_max_yoyu == -1)
		{
			cout << -1 << endl;
			return 0;
		}

		changed[idx_max_husoku] = true;
		changed[idx_max_yoyu] = true;

		swap(A[idx_max_husoku], A[idx_max_yoyu]);
		husoku[idx_max_husoku] = B[idx_max_husoku] - A[idx_max_husoku];
		husoku[idx_max_yoyu] = B[idx_max_yoyu] - A[idx_max_yoyu];

		//cout << "sw" << idx_max_yoyu << " " << idx_max_husoku << endl;
	}

	ll k = 0;
	for (ll i = 0; i < N; ++i)
	{
		if (changed[i]) ++k;
	}

	cout << k << endl;
	return 0;
}

