/**
問題文
大学生の高橋君は N 個の試験を受けてすべてに合格する必要があります．
現在，i 番目の試験の準備度は A_{i} です．
また，高橋君の入念な調査によって，i 番目の試験に合格するためには準備度を B_{i} 以上にしなくてはならないことが分かっています．
このままだとすべての試験に合格できないかもしれないと思った高橋君は，魔法使いの青木君に頼んで，
試験の準備度の総和は変えずに，なるべく少ない数の試験の準備度を変更してもらうことで試験を乗り切ることにしました．
高橋君に代わって，以下の条件を満たす数列 C_1, C_2, ..., C_{N} を考えたときの A_i と C_i が異なるような i の個数の最小値を求めてください．
そのような数列 C_1, C_2, ..., C_{N} が構成できない場合は -1 を出力してください．
・数列 A_1, A_2, ..., A_{N} の総和と数列 C_1, C_2, ..., C_{N} の総和は等しい
・どの i に対しても，B_i <= C_i が成り立つ
制約
・1 <= N <= 10^5
・1 <= A_i <= 10^9
・1 <= B_i <= 10^9
・A_i, B_i は整数
 */
void solve()
{
    ll n;
    cin >> n;
    vll a(n), b(n);
    cin >> a >> b;

    vll d(n);
    REP(i, 0, n)
    {
        d[i] = a[i] - b[i];
    }
    sort(ALL(d));
    if (accumulate(ALL(d), 0LL) < 0)
    {
        cout << -1 << endl;
        return;
    }
    ll minussum = 0;
    ll minuscnt = 0;
    REP(i, 0, n)
    {
        if (d[i] >= 0)
            break;
        ++minuscnt;
        minussum += -d[i];
    }
    ll plussum = 0;
    ll pluscnt = 0;
    REPR(i, n - 1, 0)
    {
        if (plussum >= minussum)
            break;
        ++pluscnt;
        plussum += d[i];
    }
    cout << (minuscnt + pluscnt) << endl;
}

/**
 * エントリポイント．
 * @return 0.
 */
int main()
{
    solve();
    return 0;
}

