#define REP(i,n) for(int i=0; i < (n); ++i)
#define REPR(i,n) for(int i=(n); i >= 0; --i)
#define FOR(i, m, n) for(ll i = (m); i < (n); ++i)

#define INF 1e9

int main(){
  int N;
  cin >> N;
  vector<int> A(N), B(N), diff;
  REP(i, N){
    cin >> A[i];
  }
  REP(i, N){
    cin >> B[i];
  }
  REP(i, N){
    if(A[i] > B[i]){
      diff.push_back(A[i] - B[i]);
    }
  }
  sort(diff.rbegin(), diff.rend());
  ll sum = 0;
  int cnt = 0;
  REP(i, N){
    if(A[i] >= B[i]) continue;
    sum += B[i] - A[i];
    cnt++;
  }
  ll diff_sum = 0;
  REP(i, diff.size()){
    if(sum <= diff_sum) break;
    cnt++;
    diff_sum += diff[i];
  }
  if(diff_sum < sum){
    cout << -1 << endl;
  }
  else{
    cout << cnt << endl;
  }

  return 0;
}

