typedef long long ll;
int main(){
  int N;
  std::cin >> N;
  std::vector<int> a(N,0),b(N,0);
  ll asum=0,bsum=0,rest=0,lack=0;
  for(int i = 0; i < N; i++){
    std::cin >> a[i];
    asum+=a[i];
  }
  int cnt=0;
  for(int i = 0; i < N; i++){
    std::cin >> b[i];
    bsum+=b[i];
    if (b[i]>a[i]) {
      lack+=b[i]-a[i];
      cnt++;
    }
  }
  if(bsum>asum){
    std::cout << -1 << std::endl;
    return 0;
  }
  bsum=0;
  for(int i = 0; i < N; i++){
    if(b[i]<a[i]){
      lack-=b[i]-a[i];
      cnt++;
    }
    if(lack<=0) break;
  }
  std::cout << cnt << std::endl;
  return 0;
}

