void solve()
{
	ll s1 = accumulate(A, A+N, 0LL), s2 = accumulate(B, B+N, 0LL);
	int ans = 0;
	if(s1 < s2) ans = -1;
	else{
		vector<int> diff;
		for(int i=0;i<N;++i) if(A[i]>B[i]) diff.pb(A[i]-B[i]);
