struct UnionFind {
  vector<ll> par;
  map<ll, ll> s;

  UnionFind(ll n) : par(n) {
    REP(i, n) {
      par[i] = i;
      s[i]++;
    }
  }

  ll root(ll x) {
    if(par[x] == x) return x;
    return root(par[x]);
  }

  void unite(ll x, ll y) {
    ll rx = root(x);
    ll ry = root(y);
    if(rx == ry) return;

    if(size(rx) > size(ry)) {
      s[rx] = s[rx] + s[ry];
      par[root(y)] = rx;
    } else {
      s[ry] = s[ry] + s[rx];
      par[root(x)] = ry;
    }
  }

  bool same(ll x , ll y) {
    return root(x) == root(y);
  }

  ll size(ll x) {
    return s[root(x)];
  }
};


 // base^{exp}%mod
ll mod_pow(ll base, ll exp, ll mod) {
  if(exp == 1) return base%mod;
  if(exp%2 == 1) return (base*mod_pow(base, exp-1, mod))%mod;
  ll t = mod_pow(base, exp/2, mod);
  return (t*t)%mod;
}

// nPr
ll mod_permutation(ll n, ll r) {
  ll t = 1;
  while(r != 0){
    t = (t%MOD) * (n%MOD);
    n--;
    r--;
  }
  return t;
}

ll mod_factorial(ll r) {
  ll v = 1;
  while(r != 0){
    v= (v%MOD) * (r%MOD);
    r--;
  }
  return v;
}


vector<ll> prime_factorization(ll n) {
  vector<ll> P;
  ll nn = sqrt(n)+2;
  vector<ll> prime(nn+1, true);

  for(ll i = 2; i <= nn; i++ ){
    if(prime[i]){
        for(ll j = 2 * i; j <= nn; j += i ){
            prime[j] = false;
        }
        P.emplace_back(i);
    }
  }

  vector<ll> d;
  REP(i, P.size()) {
    while(n%P[i] == 0) {
      d.push_back(P[i]);
      n/=P[i];
    }
  }
  if(n > nn) d.push_back(n);
  return d;
}

vector<ll> sieve(ll n) {
  vector<ll> P;
  ll nn = sqrt(n)+2;
  vector<ll> prime(nn+1, true);

  for(ll i = 2; i <= nn; i++ ){
    if(prime[i]){
        for(ll j = 2 * i; j <= nn; j += i ){
            prime[j] = false;
        }
        P.emplace_back(i);
    }
  }
  return P;
}

bool is_prime(ll n) {
  ll nn = sqrt(n)+2;
  vector<ll> prime(nn+1, true);
  if (n % 2 == 0) {
    return false;
  }
  vector<ll> primes = sieve(nn);
  REP(i, primes.size()) {
    if(n%primes[i] == 0) {
      return false;
    }
  }
  return true;
}



