int N;
const int MAX_N = 1.0e5 + 100;
ll A[MAX_N], B[MAX_N];

int main() {
    cin >> N;
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];

    ll C[N];
    ll old_C[N];
    ll a_sum = 0, b_sum = 0;
    for (int i = 0; i < N; i++) {
        C[i] = A[i] - B[i];
        old_C[i] = C[i];
        a_sum += A[i];
        b_sum += B[i];
    }

    if (a_sum < b_sum) {
        cout << -1 << endl;
    }
    else {
        sort(C, C+N);
        sort(old_C, old_C+N);

        int i = 0, j = N-1;
        while (C[i] < 0 && C[j] > 0) {
            if (abs(C[i]) <= C[j]) {
                    C[j] += C[i];
                C[i] = 0;
                i++;
            }
            else {
                C[i] += C[j];
                C[j] = 0;
                j--;
            }
        }

        ll ans = 0;
        for (int k = 0; k < N; k++) {
            if (C[k] != old_C[k]) {
                ans++;
            }
        }

        cout << ans << endl;
    }

    return 0;
}

