int main(){
    int N;
    cin >> N;
    vector<long long> A(N), B(N), D(N);
    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];

    for(int i=0; i<N; i++)
        D[i] = A[i] - B[i];

    sort(D.begin(), D.end());

    long long ans = 0;
    long long sm = 0;
    for(int i=0; i<N; i++)
        if(D[i] < 0){
            ans++;
            sm += -D[i];
        }

    if(sm == 0){
        cout << 0 << endl;
        return 0;
    }

    for(int i=N-1; i>=0; i--){
        if(D[i] < 0){
            cout << -1 << endl;
            return 0;
        }
        if(D[i] >= sm){
            ans++;
            cout << ans << endl;
            return 0;
        }else{
            sm -= D[i];
            ans++;
        }
    }
    return 0;
}

