int main(void)
{
    int N;
    cin >> N;

    vector<int> a(N);
    vector<int> b(N);
    set<int> s;

    for(auto& e : a)
        cin >> e;
    for(auto& e : b)
        cin >> e;

    vector<int> c(N);
    int64_t psum = 0;
    int64_t msum = 0;
    for(int i = 0; i < N; ++i)
    {
        c[i] = a[i] - b[i];
        if(c[i] < 0)
            msum += c[i];
        else if (c[i] >= 1)
        {
            psum += c[i];
            s.insert(c[i]);
        }
    }

    if(psum + msum < 0)
    {
        cout << -1 << endl;
        return 0;
    }
    if(msum == 0)
    {
        cout << 0 << endl;
        return 0;
    }

    int ans = 0;
    auto si = s.rbegin();
    int p = *si;
    for(int i = 0; i < N; ++i)
    {
        if(c[i] < 0)
        {
            ans++;
            p += c[i];
            if(p <= 0)
            {
                ++si;
                int tmp = *si;
                tmp += p;
                p = tmp;
            }
        }
    }

    ans += distance(s.rbegin(), si) + 1;
    cout << ans << endl;
    return 0;
}

