    ll ok = N; // 「index =
               // a.size()-1」が条件を満たさないこともあるので、初期値は
               // a.size()

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while(abs(ok - ng) > 1LL) {
        ll mid = (ok + ng) / 2LL;

        if(isOK(mid))
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

