typedef int64_t ll;

int solve(int N, const vector<ll>& A, const vector<ll>& B) {
  vector<ll> difp, difm;
  REP(i,N){
    ll tmp = A[i] - B[i];
    if(tmp >= 0) difp.push_back(tmp);
    else difm.push_back(tmp);
  }
  sort(difp.rbegin(), difp.rend());

  if(difm.empty()) return 0;

  ll sum = 0;
  for(ll e: difm) {
    sum += e;
  }
  REP(i, difp.size()) {
    sum += difp[i];
    if(sum >= 0) return i + difm.size() + 1;
  }
  return -1;
}

