        long long p = 0;//埋め立ててあげる余地の和
        for (int i = 0; i < plus.size(); ++i) {
            p += plus[i];
            ++num;
            if (p >= sum) break;
        }

        if (p >= sum) cout << num << endl;
        else cout << -1 << endl;
    }
}

