typedef long long ll;

const int MAX_N = 100005;

int n;
ll a[MAX_N];
ll b[MAX_N];
ll c[MAX_N];
bool changed[MAX_N];

int main()
{
	ios::sync_with_stdio(false);
	cin >> n;
	ll aSum = 0;
	for (int i = 0; i < n; i++)
	{
		cin >> a[i];
		aSum += a[i];
	}
	for (int i = 0; i < n; i++)
		cin >> b[i];

	ll cSum = 0;
	set<pair<ll, int>, greater<pair<ll, int>>> s;
	for (int i = 0; i < n; i++)
	{
		if (a[i] >= b[i])
		{
			cSum += a[i];
			c[i] = a[i];
			s.emplace(a[i] - b[i], i);
		}
		else
		{
			cSum += b[i];
			c[i] = b[i];
			changed[i] = true;
		}
	}

	while (cSum > aSum && !s.empty())
	{
		ll diff = s.begin()->first;
		int pos = s.begin()->second;
		s.erase(s.begin());
		if (cSum - diff < aSum)
			diff = cSum - aSum;
		if (diff == 0)
			continue;
		c[pos] -= diff;
		changed[pos] = true;
		cSum -= diff;
	}

	if (cSum != aSum)
		cout << "-1" << endl;
	else
	{
		int cnt = 0;
		for (int i = 0; i < n; i++)
			if (changed[i])
				cnt++;
		cout << cnt << endl;
	}
}

