//二分探索(その要素があるかないか判定するだけならsetとか二分木使う) (0(logN))
ll BS(vector<ll> V, ll Q) {
  sort(V.begin(), V.end());
  int L = -1; // Q未満の最大の要素
  int R = V.size(); // Q以上の最小の要素
  while (R - L > 1) {
    int M = (L + R) / 2;
    if (V.at(M) < Q) L = M;
    else R = M;
  }
  if (R == int(V.size())) return INF; // Qより大きい要素がない時はINFを返す
  return V.at(R); // Lを返すとQ未満の最大の要素が出てくる。
}
//素数判定 
//一つ一つの判定ではこっちの方が速い(一つ当たりO(√N))
//一方100までに何個あるかなどはEratosthenesの篩の方が良い（O(NlogN))
bool PN(int x) {
  if (x <= 1) return false; // 1や0,-1は素数ではない
  if (x == 2) return true; // √2 + 1 > 2 なので下でやると 2 ％ 2 = 0 となり判定できない
  for (int i = 2; i < sqrt(x) + 1; i++) {
    if (x % i == 0) return false; // 割れたら素数じゃない
  }
  return true;
}
// A^N mod M を計算する。modしたくなかったらM = LINFとかにすればよい (O(√N))
ll modpow(ll A, ll N, ll M) {
  ll ans = 1;
  while (N > 0) {
    if (N & 1) ans = ans * A % M;
      A = A * A % M;
      N >>= 1;
   }
  return ans;
}

