void init() {
	cin >> n;
	for(int i = 0; i < n; i++){
	    long long a;
	    cin >> a;
	    va.push_back(a);
	}
	for(int i = 0; i < n; i++){
	    long long b;
	    cin >> b;
	    vb.push_back(b);
	}
	for(int i = 0; i < n; i++){
	    long long d;
	    d = va.at(i) - vb.at(i);
	    vd.push_back(d);
	}
	sort(vd.begin(), vd.end());
