long long solve(){
    int iPlus = 0;
    long long sumD = 0;
    int cnt = 0;
    for(int i = 0; i < n; i++){
        if(vd.at(i) >= 0){
            iPlus = i;
            break;
        }
        sumD += vd.at(i);
        cnt++;
    }
    for(int i = n - 1; i >= 0; i--){
        if(sumD >= 0) return cnt;
        if(vd.at(i) <= 0){
            break;
        }
        sumD += vd.at(i);
        cnt++;
    }
    return -1;
}

