void bsort_reverse(int *a, int size)
{
  int i;
  int change = 1;
  int tmp;

  while (change) {
    change = 0;
    for(i=0; i<(size - 1); i++) {
      if (a[i] < a[i+1]) {
        tmp = a[i];
        a[i] = a[i+1];
        a[i+1] = tmp;
        change = 1;
      }
    }// for
  }//while

  return;
}

