class PriQueMax<T>() :
        PriorityQueue<T>(Collections.reverseOrder()) {}

fun solve() {
    val N = rd.readInt()
    val A = rd.readLongArray()
    val B = rd.readLongArray()

    if (A.sum() < B.sum()) {
        println(-1)
        return
    }

