        if (A[i] < B[i]) {
            ok = false
            break
        }
    }
    if (ok) {
        println(0)
        return
    }

    val diff = ArrayList<Long>()
    val pq = PriQueMax<Long>()
    for (i in 0 until N) {
        if (A[i] < B[i]) diff.add(B[i] - A[i])
        else if (A[i] > B[i]) pq.add(A[i] - B[i])
    }

    var cnt = diff.size
    var sum = diff.sum()

    while (sum > 0) {
        val hi = if (pq.isNotEmpty()) pq.poll()!! else -1
        if (hi < 0) {
            println(-1)
            return
        }
        sum -= hi
        cnt++
    }

    val ans = cnt
    println(ans)
}


