fun problem2019c(n: Int, a: List<Long>, b: List<Long>): Int {
    val diff = LongArray(n)
    var plusList = mutableListOf<Long>()
    val minusList = mutableListOf<Long>()
    for (i in 0 until n) {
        val diffI = a[i] - b[i]
        diff[i] = diffI
        if (diffI > 0) {
            plusList.add(diffI)
        } else if (diffI < 0) {
            minusList.add(diffI)
        }
    }
    if (minusList.isEmpty()) return 0
//    if (plusList.sum() < Math.abs(minusList.sum())) return -1
    plusList = plusList.sortedDescending().toMutableList()
    var plusIndex = 0
    var plusRemain = plusList[0]
    var minusIndex = 0
    var minusRemain = minusList[0] * -1
    var count = 0
    while (minusIndex != minusList.size) {
        val remain = plusRemain - minusRemain
        if (remain <= 0) {
            plusIndex++
            if (plusIndex < plusList.size) {
                plusRemain = plusList[plusIndex]
                count++
            }
        } else {
            plusRemain -= Math.abs(remain)
        }
        if (remain >= 0) {
            minusIndex++
            if (minusIndex < minusList.size) {
                minusRemain = minusList[minusIndex] * -1
                count++
            }
        } else {
            minusRemain -= Math.abs(remain)
        }
    }
    return plusIndex + minusIndex
}

