		for (int i = 0; i < b.length; i++) {
			b[i] = a[i] - in.nextLong();
			sum += b[i];
		}
		if (sum < 0) {
			out.println(-1);
			return;
		}
		Arrays.sort(b);
		int l = 0;
		int r = n - 1;
		int[] change = new int[n];
		while (b[l] < 0) {
			change[l] = 1;
			change[r] = 1;
			if (b[l] + b[r] >= 0) {
				b[r] += b[l];
				b[l] = 0;
				l++;
			} else {
				b[l] += b[r];
				b[r] = 0;
				r--;
			}
		}
		int ans = 0;
		for (int i = 0; i < change.length; i++) {
			ans += change[i];
		}
		out.println(ans);
	}

