		//Implement solution here.
		int n = ni();
		int[] a = new int[n];
		int[] b = new int[n];
		int[] dif = new int[n];
		long asum = 0;
		long bsum = 0;
		for(int i = 0; i < n; i++) {
			int tmpa = ni();
			a[i] = tmpa;
			asum += tmpa;
		}
		for(int i = 0; i < n; i++) {
			int tmpb = ni();
			b[i] = tmpb;
			bsum += tmpb;
			dif[i] = a[i] - b[i];
		}

		int result = 0;
		long csum = asum - bsum;

		if(asum < bsum) {
			result = -1;
		} else {
			Arrays.sort(dif);
			for(int i = 0; i < n; i++) {
				if(dif[i] < 0) {
					result++;
				} else if(dif[i] == 0){
					continue;
				} else {
					if(dif[i] <= csum) {
						csum -= dif[i];
					} else {
						result++;
					}
				}
			}
