	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			long[] a = new long[n], b = new long[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextLong();
			}
			for (int i = 0; i < n; i++) {
				b[i] = in.nextLong();
			}
			long sa = 0;
			int ans = 0, idx = 0;
			List<Long> list = new ArrayList<>();
			for (int i = 0; i < n; i++) {
				if (a[i] < b[i]) {
					 sa += Math.abs(b[i] - a[i]);
					 ans++;
				} else {
					list.add(a[i] - b[i]);
				}
			}
			Collections.sort(list, Comparator.reverseOrder());

