    static class Solver
    {

        public void solve(int ca,InputReader in,PrintWriter out)
        {
            while(ca -- != 0)
            {
                int n = in.nextInt();
                int a[] = new int[n];
                int b[] = new int[n];
                int d[] = new int[n];
                for(int i = 0;i<n;i++) a[i] = in.nextInt();
                for(int i = 0;i<n;i++) b[i]= in.nextInt();
                long sum =  0;
                int ans = 0;
                for(int i =  0;i<n;i++)
                {
                    d[i] = a[i] - b[i];

                    if(b[i] > a[i])
                    {
                        ans++;
                        sum += b[i] - a[i];
                    }
                }
                Arrays.sort(d);
                for(int i =  n-1;i >= 0;i--)
                {
                    if(sum == 0) break;
                    if(sum < d[i])sum = 0;
                    else sum -= d[i];
                    ans++;
                }
                if(sum != 0) out.println(-1);
                else out.println(ans);

            }
        }
