			sum -= Bi;
			if(Bi > A[i]) {
				gap += Bi - A[i];
				n++;
			}
			C[i] = A[i] - B[i];
		}
		if(sum >= 0) {
			Arrays.sort(C);
			for(int i = C.length-1;i >=0;i--) {
				if(gap <= 0) {
					break;
				}
