        while (D[excessiveHead] > 0) {
            di = D[excessiveHead];
            if (D[shortageHead] >= 0)
                break;
            while (di > 0 && D[shortageHead] < 0) {
                if (di >= Math.abs(D[shortageHead])) {
                    di += D[shortageHead];
                    shortageHead++;
                    count++;
                } else {
                    D[shortageHead] += di;
                    di = 0;
                }
            }
            count++;
            excessiveHead--;
        }

        System.out.println(count);

        sc.close();
    }
}

