        for(int i = 0; i < n; ++i){
            a[i] = sc.scanLong();
        }
        for(int i = 0 ; i < n; ++i){
            a[i] -= sc.scanLong();
        }
        Arrays.sort(a);
        int i = 0;
        long need = 0;
        while(i < n){
            if(a[i]>=0)
                break;
            need+=a[i];
            ++i;
        }
        if(i==n){
            System.out.println("-1");
            return;
        }
        int j = n-1;
        need *= -1;
        long cum = 0;
        for(; j >= i; --j){
            cum += a[j];
            if(cum >= need)
                break;
        }
        if(cum < need){
            System.out.println("-1");
            return;
        }
        System.out.println(i + (n-j));
    }
}

class Scan
{
    private byte[] buf=new byte[1024];
    private int index;
    private InputStream in;
    private int total;
    public Scan()
    {
        in=System.in;
    }
    public int scan()throws IOException
    {
        if(total<0)
        throw new InputMismatchException();
        if(index>=total)
        {
            index=0;
            total=in.read(buf);
            if(total<=0)
            return -1;
        }
        return buf[index++];
    }
    public int scanInt()throws IOException
    {
        int integer=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n))
        {
            if(n>='0'&&n<='9')
            {
                integer*=10;
                integer+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        return neg*integer;
    }
    public long scanLong() throws IOException {
        long integer=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n))
        {
            if(n>='0'&&n<='9')
            {
                integer*=10;
                integer+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        return neg*integer;
    }
    public double scanDouble()throws IOException
    {
        double doub=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n)&&n!='.')
        {
            if(n>='0'&&n<='9')
            {
                doub*=10;
                doub+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        if(n=='.')
        {
            n=scan();
            double temp=1;
            while(!isWhiteSpace(n))
            {
                if(n>='0'&&n<='9')
                {
                    temp/=10;
                    doub+=(n-'0')*temp;
                    n=scan();
                }
                else throw new InputMismatchException();
            }
        }
        return doub*neg;
    }
    public String scanString()throws IOException
    {
        StringBuilder sb=new StringBuilder();
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        while(!isWhiteSpace(n))
        {
            sb.append((char)n);
            n=scan();
        }
        return sb.toString();
    }
    private boolean isWhiteSpace(int n)
    {
        if(n==' '||n=='\n'||n=='\r'||n=='\t'||n==-1)
        return true;
        return false;
    }
}

import java.io.*;
import java.math.*;
import java.util.*;
public class Main{

	public static void main(String[] args) { 
		Scanner input = new Scanner(System.in);
		int N = input.nextInt();
		long[] a = new long[N];
		long[] b = new long[N];
		long[] d = new long[N];
		boolean[] vis = new boolean[N];
		long Sa = 0;
		long Sb = 0; //Total sums of arrays (use longs for this) 10^9*10^5 = 10^14
		int ans = 0;
		for (int i = 0; i < N; i++) {
			a[i]=input.nextLong();
			Sa+=a[i];
		}
		for (int i = 0; i < N; i++) {
			b[i]=input.nextLong();
			Sb+=b[i];
		}
		if (Sb>Sa) ans=-1;
		else {
			for (int i = 0; i < N; i++) {
				d[i]=a[i]-b[i];
			}
			Arrays.sort(d);
			int L = 0;
			int R = N-1;
			while (true) {
				if (d[L]>=0) break;
				long min = Math.min(Math.abs(d[L]), d[R]);
				d[L]+=min;
				d[R]-=min;
				if (!vis[L]) ans++;
				if (!vis[R]) ans++;
				vis[L]=true;
				vis[R]=true;
				if (d[R]==0) R--;
				if (d[L]==0) L++;
			}
		}
		System.out.println(ans);
	}
}

