        int N = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];
        for (int i=0; i<N; i++) {
            A[i] = sc.nextInt();
        }
        for (int i=0; i<N; i++) {
            B[i] = sc.nextInt();
        }

        int ans = solve4000334(N, A, B);

        System.out.println(ans);
    }

    private static int solve(int N, int[] A, int[] B) {

        List<Integer> pos = new ArrayList<>();
        List<Integer> neg = new ArrayList<>();

        for (int i=0; i<N; i++) {
            if (A[i] - B[i] >= 0) {
                pos.add(A[i] - B[i]);
            } else {
                neg.add(B[i] - A[i]);
            }
        }

        Collections.sort(pos, Collections.reverseOrder());
        Collections.sort(neg, Collections.reverseOrder());

        int count = 0;
        int possum = 0;
        while (neg.size() > 0) {
            count++;
            int value = neg.remove(0);

            // System.err.println("current negative = " + value);
            while (possum < value && pos.size() > 0) {
                possum += pos.remove(0);
                // System.err.println("current pos:" + possum);
                count++;
                if (value <= possum) break;
            }

            if (possum < value) return -1;

            possum -= value;
        }

        return count;
    }

    private static int solve4000334(int N, int[] A, int[] B) {
        long bal = 0;
        int[] C = new int[N];

        for (int i=0; i<N; i++) {
            bal += B[i];
            bal -= A[i];
            C[i] = A[i] - B[i];
        }

        if (bal > 0) return -1;

        int ch = 0;
        long f = 0;
        for (int i=0; i<N; i++) {
            if (C[i] < 0) {
                ch++;
                f -= C[i];
                C[i] = 0;
            }
        }

        Arrays.sort(C);
        for (int i=N-1; i>=0; i--) {
            long m = Math.min(f, C[i]);
            if (m > 0) {
                ch++;
                f -= m;
                C[i] -= m;
            }
        }

        return ch;
    }
}

