        int[] A = in.nextIntArray(N);
        int[] B = in.nextIntArray(N);

        long small = 0;
        List<Long> diffs = new ArrayList<>();
        long aTotal = 0, bTotal = 0;

        long res = 0;
        for (int i = 0; i < N; i++) {
            aTotal += A[i];
            bTotal += B[i];
            if (A[i] > B[i]) {
                diffs.add((long) (A[i] - B[i]));
            } else if (A[i] < B[i]) {
                res++;
                small += B[i] - A[i];
            }
        }

        if (aTotal < bTotal) {
            System.out.println("-1");
            return;
        }

        diffs.sort((i1, i2) -> Long.compare(i2, i1));
        for (long d : diffs) {
            if (small <= 0) break;
            res++;
            small -= d;
        }
        System.out.println(res);
    }

