        if(sum(A)<sum(B)){
            System.out.println("-1");
            return;
        }
        int notEnoughStudy = 0;
        long extraStudy = 0;
        PriorityQueue<Long> margin = new PriorityQueue<>();
        for(int n=0; n<N; n++){
            if(A[n]<B[n]){
                notEnoughStudy++;
                extraStudy += (B[n]-A[n]);
            }else{
                margin.add(B[n]-A[n]);
            }
        }
