	public void solve() throws IOException {
		FastScanner fs = new FastScanner();

		int n = fs.nextInt();
		int[] aArr = new int[n];
		int[] bArr = new int[n];

		long aSum = 0;
		for(int i = 0; i < n; i++) {
			int a = fs.nextInt();
			aSum += a;
			aArr[i] = a;
		}

		long bSum = 0;
		for(int i = 0; i < n; i++) {
