	int num = ni();
	long a[] = nl(num);
	long b[] = nl(num);
	for(int i = 0; i < num; i ++) {
		a[i] -= b[i];
	}
	Arrays.sort(a);
	reverse(a);
	long sum = 0;
	int ans = 0;
	for(int i = 0; i < num; i ++) {
		if(a[i] < 0) {
			sum += - a[i];
			ans ++;
		}
	}
	int index = 0;
	while(sum > 0 && index < num) {
		sum -= a[index ++];
		ans ++;
	}
	prtln(sum <= 0 ? ans : -1);
