        Arrays.sort(P, (p1, p2) -> p1.d - p2.d);

        long sumA = sum(A);
        long sumB = sum(B);
        long sumDiff = sumA - sumB;
        if (sumDiff < 0) {
            so.println(-1);
            return;
        }

        int ans = 0;
        for (int i = 0; i < N; i++) {
            if (sumDiff < P[i].d) {
                break;
            }
            sumDiff -= P[i].d;
            ans++;
        }
        so.println(N - ans);
    }
    static long sum(int[] a) {
        return Arrays.stream(a).sum();
    }

    static class Prep {
        int a;
        int b;
        int d;
        public Prep(int a, int b, int d) {
            this.a = a;
            this.b = b;
            this.d = d;
        }

        @Override
        public String toString() {
            return "(a: " + a + ", b: " + b + ", d: " + d + ")";
        }
    }
}

