import java.io.*;
import java.util.*;

public class Main {
  private static int solve(int n, int[] as, int[] bs) {
    int count = 0;
    long totalNegativeGap = 0;
    List<Integer> positiveGaps = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      if (as[i] < bs[i]) {
        totalNegativeGap += bs[i] - as[i];
        count++;
      } else if (as[i] > bs[i]) {
        positiveGaps.add(as[i] - bs[i]);
      }
    }

    if (totalNegativeGap == 0) {
      return 0;
    }

    Collections.sort(positiveGaps);
    for (int i = positiveGaps.size() - 1; i >= 0; i--) {
      totalNegativeGap -= positiveGaps.get(i);
      count++;
      if (totalNegativeGap <= 0) {
        return count;
      }
    }
    return -1;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int[] as = reader.nextInt(n);
    int[] bs = reader.nextInt(n);
    out.println(solve(n, as, bs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

