public class Main {
    private static InputStream is;
    private static PrintWriter out;
    private static String INPUT = "";

    void solve() {
        int n = ni(), a[] = na(n), b[] = na(n);
        int sa = IntStream.of(a).sum();
        int sb = IntStream.of(b).sum();
        if (sa < sb) {
            out.println(-1);
            return;
        }
        class P {
            int a, b;
        }
        P[] p = new P[n];
        for (int i = 0; i < n; ++i) {
            p[i] = new P();
            p[i].a = a[i];
            p[i].b = b[i];
        }
        Arrays.sort(p, (r, l) -> (r.b - r.a) - (l.b - l.a));
        long x = 0, s = 0;
        for (int i = 0; i < n; ++i) {
            P t = p[i];
            if (t.a < t.b) {
                x++;
                s += t.b - t.a;
            }
        }
        for (int i = 0; i < n && s > 0; ++i) {
            P t = p[i];
            if (t.a > t.b) {
                x++;
                s -= t.a - t.b;
            }
        }
        out.println(x);
    }

