		long sumdiff=0;
		long sup=0;
		long kaz=0;
		for(int i=0; i<N; i++) {
			if(a[i]>=b[i]) {
				sup+=a[i]-b[i];
			}
			else {
				sumdiff+=b[i]-a[i];
				kaz++;
			}
			diff[i]=a[i]-b[i];
		}
		if(sumdiff>sup) {
			pl(-1);
		}
		else if(sumdiff==0) {
			pl(0);
		}
		else {
			Arrays.sort(diff);
			for(int i=N-1; i>=0; i--) {
