import java.util.Arrays;
import java.util.Scanner;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static int N = sc.nextInt();
	static long[] A = new long[N];
	static long[] B = new long[N];
	static long[] D = new long[N];
	static {
		Arrays.setAll(A, i->sc.nextLong());
		Arrays.setAll(B, i->sc.nextLong());
	}
	public static void main(String[] args) {
		for (int i = 0; i < N; i++) {
			D[i] = A[i] - B[i];
		}
		if (Arrays.stream(D).sum() < 0) {
			System.out.println(-1);
			return;
		}
		if (Arrays.stream(D).allMatch(i-> i >= 0)) {
			System.out.println(0);
			return;
		}
		long ans = Arrays.stream(D).filter(i-> i < 0).count();
		long shortage = Arrays.stream(D).filter(i-> i < 0).sum();
		long[] remains = Arrays.stream(D).filter(i-> i > 0).sorted().toArray();
//		System.out.println(Arrays.toString(remains));
		for (int i = remains.length - 1; i >= 0; i--) {
			shortage += remains[i];
			ans++;
			if (shortage >=0 ) {
				break;
			}
		}
		System.out.println(ans);
	}
}

import java.util.*;
public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int[][] arr = new int[n][2];

      int sumA = 0;
      for(int i = 0; i < n; i++) {
        arr[i][0] = sc.nextInt();
        sumA += arr[i][0];
      }

      int sumB = 0;
      for(int i = 0; i < n; i++) {
        arr[i][1] = sc.nextInt();
        sumB += arr[i][1];
      }

      if(sumA < sumB) {
        System.out.println(-1);
        return;
      }

      Arrays.sort(arr, (a1, a2) -> (a1[0] - a1[1]) - (a2[0] - a2[1]));
      int cnt = 0;
      long diffSum = 0;
      for(int i = 0; i < n; i++) {
        if(arr[i][0] >= arr[i][1]) break;
        cnt++;
        diffSum += arr[i][1] - arr[i][0];
      }

      for(int i = n - 1; i >= 0 && diffSum > 0; i--) {
        diffSum -= (arr[i][0] - arr[i][1]);
        cnt++;
      }
      System.out.println(cnt);
  }
}

