using System;
using System.Collections.Generic;
using System.Text;

namespace AtTest.Keyence
{
    class C
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] array = ReadInts();
            int[] bArray = ReadInts();
            long aSum = 0;
            long bSum = 0;
            for(int i = 0; i < n; i++)
            {
                aSum += array[i];
                bSum += bArray[i];
            }
            if (aSum < bSum)
            {
                Console.WriteLine(-1);
                return;
            }
            var pluses = new List<int>();
            var minuses = new List<int>();
            for(int i = 0; i < n; i++)
            {
                if (array[i] < bArray[i]) minuses.Add(bArray[i] - array[i]);
                if (array[i] > bArray[i]) pluses.Add(array[i] - bArray[i]);
            }
            if (minuses.Count == 0)
            {
                Console.WriteLine(0);
                return;
            }

            long mSum = 0;
            for(int i = 0; i < minuses.Count; i++)
            {
                mSum += minuses[i];
            }

            long pSum = 0;
            for (int i = 0; i < pluses.Count; i++)
            {
                pSum += pluses[i];
                if (pSum >= mSum)
                {
                    Console.WriteLine(minuses.Count + i + 1);
                    return;
                }
            }
        }

        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

using System;
using static System.Console;

namespace B
{
  class Program
  {
    static void Main(string[] args)
    {
      string input = ReadLine();

      string keystr = "keyence";

      bool flag = false;

      for(int i = 0; i<6; i++) {
        string frontstr = keystr.Substring(0, i);
        string backstr = keystr.Substring(i, 7-i);
        int frontidx = input.IndexOf(frontstr);
        if(frontidx == -1) continue;
        int backidx = input.IndexOf(backstr, frontidx);
        if(backidx == -1) continue;
        if(frontidx == 0 || backidx == input.Length-7-1) {
          flag = true;
          break;
        }
      }

      if(input.IndexOf(keystr) != -1)
        if(input.IndexOf("k") != input.IndexOf(keystr))
          if(input.IndexOf(keystr)-1 != input.Length-7-1)
            flag = false;

      WriteLine(flag ? "YES" : "NO");
      Read();
    }
  }
}

