using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static Scanner cin = new Scanner();

    static void Main(string[] args) {
        int N = cin.Int();
        var A = cin.ArrayLong(N);
        var B = cin.ArrayLong(N);

        long a_sum = 0, b_sum = 0;
        for (int i = 0; i < N; i++) {
            a_sum += A[i];
            b_sum += B[i];
        }

        if (a_sum < b_sum) Console.WriteLine(-1);
        else {
            long ans = 0;
            long shortage = 0;
            for (int i = 0; i < N; i++) {
                if (A[i] < B[i]) {
                    shortage += B[i] - A[i];
                    ans++;
                }
            }
            var rest = new long[N];
            for (int i = 0; i < N; i++) {
                if (A[i] > B[i]) rest[i] = A[i] - B[i];
            }
            rest = rest.OrderByDescending(x => x).ToArray();
            int index = 0;
            while(shortage > 0) {
                shortage -= rest[index];
                ans++;
                index++;
            }
            Console.WriteLine(ans);
        }
        Console.ReadLine();
    }
}

class Scanner //標準入力
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int Int()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = Int() + add;
        }
        return Array;
    }

    public long Long()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = Long() + add;
        }
        return Array;
    }

    public double Double()
    {
        return double.Parse(next());
    }


    public double[] ArrayDouble(int N, double add = 0)
    {
        double[] Array = new double[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = Double() + add;
        }
        return Array;
    }
}

