namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            string[] A = Console.ReadLine().Split(' ');
            string[] B = Console.ReadLine().Split(' ');

            int[] a = new int[N];
            int[] b = new int[N];
            int[] r = new int[N];

            Int64 pos = 0, neg = 0;
            int Counter = 0;
            int posCounter = 0;

            for (int i=0;i<N;i++)
            {
                a[i] = int.Parse(A[i]);
                b[i] = int.Parse(B[i]);

                r[i] = a[i] - b[i];

                if (r[i] > 0)
                {
                    pos += r[i];
                    posCounter++;
                }
                else if(r[i] < 0)
                {
                    neg += r[i];
                    Counter++;
                }
            }

            if(pos + neg < 0)
            {
                Console.WriteLine("-1");
                return;
            }

            int[] p = new int[posCounter];
            int index = 0;
            for(int i=0;i<N;i++)
            {
                if(r[i] > 0)
                {
                    p[index] = r[i];
                    index++;
                }
            }

            int temp;

            for (int i = 0; i < posCounter - 1; i++)
            {
                for (int j = (posCounter - 1); j > i; j--)
                {
                    if (p[j - 1] < p[j])
                    {
                        temp = p[j - 1];
                        p[j - 1] = p[j];
                        p[j] = temp;
                    }
                }
            }

            for(int i=0; i<posCounter;i++)
            {
                neg += p[i];
                Counter++;

                if(neg>=0)
                    Console.Write(Counter.ToString());
            }

            Console.Write(Counter.ToString());

        }
    }
}

