class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long[] numsb = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long sumBefore = 0;
		long sumAfter = 0;
		List<long> plusList = new List<long>();
		long mustPlus = 0;
		long answer = 0;

		for(int i = 0; i < n; i++)
		{
			sumBefore += nums[i];
			sumAfter += numsb[i];
			if(nums[i] < numsb[i])
			{
				mustPlus += numsb[i] - nums[i];
				answer++;
			}
			else if(nums[i] > numsb[i]) plusList.Add(nums[i] - numsb[i]);
		}
		plusList.Sort((a, b) => a.CompareTo(b));

		if(sumBefore < sumAfter) Console.WriteLine(-1);
		else
		{
			while(mustPlus > 0)
			{
				mustPlus -= plusList[plusList.Count()-1];
				plusList.RemoveAt(plusList.Count()-1);
				answer++;
			}
			Console.WriteLine(answer);
		}
	}
}

