namespace AtCoder {

    class Comparator : IEqualityComparer<long> {

        public bool Equals(long x, long y) {
            return x >= y;
        }

        public int GetHashCode(long obj) {
            return obj.GetHashCode();
        }
    }
    class Program {

        static void Main(string[] args) {

            var N = int.Parse(Console.ReadLine());

            var An = Console.ReadLine().Split(' ').Select(s => long.Parse(s)).ToList();
            var Bn = Console.ReadLine().Split(' ').Select(s => long.Parse(s)).ToList();

            var Asum = An.Sum();
            var Bsum = Bn.Sum();

            if(Asum < Bsum) {

                Console.WriteLine(-1);
                return;
            }

            if(An.SequenceEqual(Bn, new Comparator())) {

                Console.WriteLine(0);
                return;
            }

            var result = 0;

            var Cn = new List<long>();

            for(int i = 0; i < N; i++) {

                var a = An[i];
                var b = Bn[i];
                Cn.Add(b);

                Asum -= b;
            }
            var TT = Asum / N + 1;
            for (int i = 0; i < N; i++) {

                if(Asum <= 0) {

                    break;
                }
                if(Asum < TT) {

                    TT = Asum;
                }
                Asum -= TT;
                Cn[i] = Cn[i] + TT;
            }

            for (int i = 0; i < N; i++) {

                if(An[i] != Cn[i]) {

                    result++;
                }
            }


            if (result == 0) {

                Console.WriteLine("-1");
            } else {

                Console.WriteLine(result);
            }
        }
    }
