        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] array = ReadInts();
            int[] bArray = ReadInts();
            long aSum = 0;
            long bSum = 0;
            for(int i = 0; i < n; i++)
            {
                aSum += array[i];
                bSum += bArray[i];
            }
            if (aSum < bSum)
            {
                Console.WriteLine(-1);
                return;
            }
            var pluses = new List<int>();
            var minuses = new List<int>();
            for(int i = 0; i < n; i++)
            {
                if (array[i] < bArray[i]) minuses.Add(bArray[i] - array[i]);
                if (array[i] > bArray[i]) pluses.Add(array[i] - bArray[i]);
            }
            if (minuses.Count == 0)
            {
                Console.WriteLine(0);
                return;
            }

            int plusIndex = 0;
            int nowPlusOrigin = pluses[plusIndex];
            for (int i = 0; i < minuses.Count; i++)
            {
                int delta = minuses[i];
                while (delta > 0)
                {
                    if (pluses[plusIndex] > delta)
                    {
                        pluses[plusIndex] -= delta;
                        delta = 0;
                    }
                    else
                    {
                        delta -= pluses[plusIndex];
                        plusIndex++;
                        if (plusIndex < pluses.Count)
                            nowPlusOrigin = pluses[plusIndex];
                    }
                }
            }
            int res = minuses.Count + plusIndex;
            if (plusIndex < pluses.Count
                && pluses[plusIndex] < nowPlusOrigin) res++;
            Console.WriteLine(res);
        }

