public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        string[] line = Console.ReadLine().Trim().Split(' ');
        var a = Array.ConvertAll(line, long.Parse);
         line = Console.ReadLine().Trim().Split(' ');
        var b = Array.ConvertAll(line, long.Parse);
        if (a.Sum() < b.Sum()) { Console.WriteLine(-1); goto exit; }
        var c = new List<long>();
        var b1 = 0L;  var b1c = 0;
        for (int i = 0; i < n; i++)
        {
            var w = a[i] - b[i];
            if (w < 0) { b1c++; b1 += -w; }
            else c.Add(w);
        }
        if (b1c == 0) { Console.WriteLine(0); goto exit; }
        if (b1 > c.Sum()) { Console.WriteLine(-1); goto exit; }
        var c1 = c.OrderByDescending(x => x).ToArray();
        var ans = getAns(c1, b1, n);
        Console.WriteLine(ans + b1c);
        exit:;
    }
    static int getAns (long[] c , long a , int n)
    {
        for (int i = 0; i < c.Length; i++)
        {
            a -= c[i];
            if (a <= 0) return i + 1;
        }
        return -1;
    }
}

