        public static void Solve()
        {
            var n = GetNumber<long>();
            var array = GetArray<long>();
            var bs = GetArray<long>();
            if (array.Sum() < bs.Sum())
            {
                Write(-1); return;
            }

            var list = new List<long>();
            var diff = 0L;
            var count = 0;
            for (int i = 0; i < n; i++)
            {
                if (bs[i] > array[i])
                {
                    count++;
                    diff += bs[i] - array[i];
                }
                else if (array[i] > bs[i])
                {
                    list.Add(array[i] - bs[i]);
                }
            }
            var que = new Queue<long>(list.OrderByDescending(x => x));
            while (diff > 0)
            {
                var margin = que.Dequeue();
                diff -= margin;
                count++;
            }
            Write(count);
        }
    }
