    {
        var n = int.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var b = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var diffs = a.Zip(b, (aa, bb) => aa - bb).OrderByDescending(v => v).ToArray();

        if (diffs.Sum() < 0)
        {
            Console.WriteLine(-1);
            return;
        }

        var remain = diffs.Where(d => d < 0).Sum();
        var changed = diffs.Count(d => d < 0);
        foreach (var d in diffs)
        {
            if (remain >= 0)
            {
                break;
            }
            remain += d;
            changed++;
        }

        Console.WriteLine(changed);
    }
