            {
                M.Enqueue(B[i] - A[i]);
            }
            else if(A[i] > B[i])
            {
                P.Enqueue(A[i] - B[i]);
            }
        }

        long remain = 0;
        int ans = M.Count;
        while (M.Any())
        {
