    class Class210
    {
        static void Main()
        {
            int N = int.Parse(Console.ReadLine());
            long[] A = Console.ReadLine().Split().Select(long.Parse).ToArray();
            long[] B = Console.ReadLine().Split().Select(long.Parse).ToArray();
            if (A.Sum() < B.Sum()) { Console.WriteLine(-1);return; }

            List<long> Minus = new List<long>();
            List<long> Plus = new List<long>();
            for(int i = 0; i < N; i++)
            {
                long d = A[i] - B[i];
                if (d < 0) Minus.Add(-d);
                else if (d > 0) Plus.Add(d);
            }
            Plus.Sort((x, y) => x.CompareTo(-y));
            Plus.Insert(0, 0);

            int changed = 0;
            int num = 0;
            for(int i = 0; i < Minus.Count; i++)
            {
                while (true)
                {
                    if (Minus[i] <= Plus[num])
                    {
                        Plus[num] -= Minus[i];
                        break;
                    }
                    else
                    {
                        Minus[i] -= Plus[num];
                        changed++;
                        num++;
                    }
                }
            }

            Console.WriteLine(changed+Minus.Count);
        }
    }
}

