class Program
{
    public void Slove()
    {
        int n = int.Parse(Console.ReadLine());
        int[] point =
            Console.ReadLine().Split()
            .Select(int.Parse)
            .ToArray();
        point =
            Console.ReadLine().Split()
            .Select(int.Parse)
            .Select((x, i) =>
                point[i] - x)
            .OrderBy(x => x)
            .ToArray();
        int result = 0;
        //Console.WriteLine(string.Join(",", point));
        for(int start = 0, end = point.Length - 1, p = 0;;)
        {
            //Console.WriteLine($"{start} {end}");
            if(p < 0)
            {
                if(point[end] <= 0 || start > end)
                {
                    result = -1;
                    break;
                }
                p += point[end--];
            }
            else
            {
                if(point[start] >= 0 || start > end)
                {
                    result = start + (point.Length - 1 - end);
                    break;
                }
                p += point[start++];
            }
        }
        Console.WriteLine(result);
    }
    static void Main(string[] args)
    {
        var p = new Program();
        p.Slove();
    }
}

