        for (int i = 0; i < N; i++)
        {
            D[i] = A[i] - B[i];
        }
        Array.Sort(D);
        Array.Reverse(D);
        //Console.WriteLine("[{0}]", string.Join(", ", D));
        int cnt = 0;
        int tail = N - 1;
        for(int i = 0;i < N;i++)
        {
            if (D[i] < 0) return "-1";
            int lest = D[i];
            if(D[tail] < 0)
            cnt++;
            while(lest > 0)
            {
                if (D[tail] < 0)
                {
                    if (lest + D[tail] >= 0)
                    {
                        lest += D[tail];
                        D[tail] = 0;
                        tail--;
                        cnt++;
                    }
                    else
                    {
                        D[tail] += lest;
                        break;
                    }
                }
                else return cnt.ToString();
            }
        }

        return cnt.ToString();
