using System;
using System.Diagnostics;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        List<int> a = Console.ReadLine().Split().Select(i => int.Parse(i)).ToList();
        List<int> b = Console.ReadLine().Split().Select(i => int.Parse(i)).ToList();
        List<int> gap = new List<int>();
        List<int> adv = new List<int>();

        for (int i = 0; i < a.Count; i++)
        {
            if (a[i] < b[i])
            {
                gap.Add(b[i] - a[i]);
            }
            else if (b[i] < a[i])
            {
                adv.Add(a[i] - b[i]);
            }
        }
        long gap_sum = gap.Sum();
        long ans = gap.Count;
        adv.Sort((x, y) => y - x);
        for (int i = 0; i < adv.Count; i++)
        {
            if (gap_sum <= 0) break;
            gap_sum -= adv[i];
            ans++;
        }
        if (0 < gap_sum) Console.WriteLine(-1);
        else Console.WriteLine(ans);
    }
}

