using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Text;


class Program
{
    static long[] a;
    static long[] b;
    static long[] diff;
    static long start;
    static long end;
    static bool ok;

    static void Main(string[] args)
    {
        // 入力
        //var s = Console.ReadLine();
        var n = int.Parse(Console.ReadLine());
        a = Console.ReadLine().Split().Select(long.Parse).ToArray();
        b = Console.ReadLine().Split().Select(long.Parse).ToArray();

        diff = new long[n];
        for (int i = 0; i < n; i++)
        {
            diff[i] = a[i] - b[i];
        }

        Array.Sort(diff);

        long[] tmp = new long[n];
        Array.Copy(diff, tmp, n);

        ok = true;
        start = 0;
        end = n - 1;
        long ans = 0;
        while (true)
        {
            if (diff[start] < 0)
            {
                //再帰関数
                F();

                if (!ok)
                {
                    ans = -1;
                    break;
                }

                start++;
            }
            else
            {
                break;
            }
        }

        if (ok)
        {
            for (int i = 0; i < n; i++)
            {
                if (tmp[i] != diff[i]) ans++;
            }
        }

        // 出力
        Console.WriteLine(ans);
    }
    static void F()
    {
        if (end < 0)
        {
            ok = false;
        }
        else if (diff[start] * -1 <= diff[end])
        {
            diff[end] = diff[end] + diff[start];
            diff[start] = 0;
        }
        else
        {
            diff[start] = diff[end] + diff[start];
            diff[end] = 0;
            end--;
            F();
        }
    }
}

