using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

namespace atcorder_keyence_2019
{
    struct DIFF_DATA
    {
        public int idx;
        public int diff;
    }

    class Program
    {
        static void Main(string[] args)
        {
            int cnt = int.Parse(Console.ReadLine());
            string[] dataA = Console.ReadLine().Split(' ');
            string[] dataB = Console.ReadLine().Split(' ');

            List<DIFF_DATA> ldd = new List<DIFF_DATA>();
            int changeCnt = 0;
            int changeDiff = 0;
            for (int i = 0; i < cnt; i++)
            {
                DIFF_DATA dd = new DIFF_DATA();

                int ia = int.Parse(dataA[i]);
                int ib = int.Parse(dataB[i]);

                if (ia > ib)
                {
                    dd.idx = i;
                    dd.diff = ia - ib;
                    ldd.Add(dd);
                }
                else if (ia < ib)
                {
                    changeCnt++;
                    changeDiff += ib - ia;
                }
            }

            int ret = 0;

            if (0 < changeCnt)
            {

                if (1 < ldd.Count)
                {
                    //バブルソートで差の昇順で並び替え
                    int lastIdx = ldd.Count - 1;
                    while (0 < lastIdx)
                    {
                        for (int i = 0; i < lastIdx; i++)
                        {
                            if (ldd[i].diff > ldd[i + 1].diff)
                            {
                                DIFF_DATA tmpDD = ldd[i + 1];
                                ldd[i + 1] = ldd[i];
                                ldd[i] = tmpDD;
                            }
                        }
                        lastIdx--;
                    }

                }

                ret = -1;

                for (int i = ldd.Count - 1; 0 <= i; i--)
                {
                    changeDiff -= ldd[i].diff;
                    changeCnt++;
                    if (changeDiff <= 0)
                    {
                        ret = changeCnt;
                        break;
                    }
                }

            }

            Console.WriteLine(ret);
        }
    }
}

