        public static int LowerBound<T>(this IReadOnlyList<T> a, T v) => LowerBound(a, v, Comparer<T>.Default);
        public static int LowerBound<T>(this IReadOnlyList<T> a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Count - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var result = cmp.Compare(a[mid], v);
                if (result == -1)
                {
                    l = mid + 1;
                }
                else
                {
                    r = mid - 1;
                }
            }
            return l;
        }
        public static int UpperBound<T>(this IReadOnlyList<T> a, T v) => UpperBound(a, v, Comparer<T>.Default);
        public static int UpperBound<T>(this IReadOnlyList<T> a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Count - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res <= 0) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }
    }

    public struct Mint
    {
        public static long MOD = (long)1e9 + 7;

        /// <summary>
        /// 0以上MOD未満の整数
        /// </summary>
        public long Value;

        public Mint(long val)
        {
            Value = val % MOD;
            if (Value < 0) Value += MOD;
        }

        private static Mint Ctor(long val)
        {
            return new Mint() { Value = val };
        }

        public static Mint operator +(Mint a, Mint b)
        {
            long res = a.Value + b.Value;
            if (res > MOD) res -= MOD;
            return Ctor(res);
        }
        public static Mint operator -(Mint a, Mint b)
        {
            long res = a.Value - b.Value;
            if (res < 0) res += MOD;
            return Ctor(res);
        }

        public static Mint operator *(Mint a, Mint b)
        {
            long res = a.Value * b.Value;
            if (res > MOD) res %= MOD;
            return Ctor(res);
        }

        public static Mint operator /(Mint a, Mint b)
        {
            return a * Inv(b);
        }

        public static Mint Pow(Mint a, long n)
        {
            if (n == 0) return new Mint(1);
            Mint b = Pow(a, n >> 1);
            b *= b;
            if ((n & 1) == 1) b *= a;
            return b;
        }

        public static Mint Inv(Mint n)
        {
            long a = n.Value;
            long b = MOD;

            long x = 1;
            long u = 0;
            while (b != 0)
            {
                long k = a / b;
                long _x = u;
                u = x - k * u;
                x = _x;

                long _a = a;
                a = b;
                b = _a - (k * b);
            }

            return new Mint(x);
        }

        public override string ToString()
        {
            return Value.ToString();
        }

        public static implicit operator Mint(long a) { return new Mint(a); }
        public static explicit operator long(Mint a) { return a.Value; }
        public static Mint Choose(long n, long k)
        {
            Mint numerator = 1, denominator = 1;
            for (int i = 0; i < k; i++)
            {
                numerator *= n - i;
                denominator *= i + 1;
            }
            return numerator / denominator;
        }
    }
    public enum Priority : byte
    {
        Smaller = 0,
        Larger = 1
    }
}

using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Text;


class Program
{
    static long[] a;
    static long[] b;
    static long[] diff;
    static long start;
    static long end;


    static void Main(string[] args)
    {
        // 入力
        //var s = Console.ReadLine();
        var n = int.Parse(Console.ReadLine());
        a = Console.ReadLine().Split().Select(long.Parse).ToArray();
        b = Console.ReadLine().Split().Select(long.Parse).ToArray();

        diff = new long[n];
        for (int i = 0; i < n; i++)
        {
            diff[i] = a[i] - b[i];
        }

        Array.Sort(diff);

        long[] tmp = new long[n];
        Array.Copy(diff, tmp, n);

        start = 0;
        end = n - 1;
        long ans = 0;
        if (a.Sum() < b.Sum())
        {
            ans = - 1;
        }
        else
        {
            while (true)
            {
                if (diff[start] < 0)
                {
                    //再帰関数
                    F();
                    start++;
                }
                else
                {
                    break;
                }
            }

            for (int i = 0; i < n; i++)
            {
                if (tmp[i] != diff[i]) ans++;
            }
        }
        // 出力
        Console.WriteLine(ans);
    }
    static void F()
    {
        if (diff[start] * -1 <= diff[end])
        {
            diff[end] = diff[end] + diff[start];
            diff[start] = 0;
        }
        else
        {
            diff[start] = diff[end] + diff[start];
            diff[end] = 0;
            end--;
            F();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            var B = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            var difference = new List<long>();
            var sumFlag = (long)0;

            for (int i = 0; i < N; i++)
            {
                var dif = A[i] - B[i];
                difference.Add(dif);
                sumFlag += dif;
            }

            if (sumFlag < 0)
            {
                Console.WriteLine("-1");
                return;
            }

            //昇順ソート
            difference.Sort();

            //変更されたか記録
            var change = new bool[difference.Count];
            for (int i = 0; i < difference.Count; i++)
            {
                change[i] = false;
            }

            var changeCount = 0;
            var startCount = 0;
            for (int index = 0; index < difference.Count; index++)
            {
                //昇順ソートなので0よりでかいのが来たら以降全部でかい => break
                if (difference[index] >= 0)
                {
                    break;
                }

                var need = difference[index] * -1;
                change[index] = true;
                changeCount++;

                var buffer = (long)0;

                for (int bring = startCount; bring < difference.Count; bring++)
                {
                    var bringPoint = difference.Count - bring - 1;

                    //bringPointから持ってくる数 == val
                    var val = (long)0;
                    if (need <= difference[bringPoint])
                    {
                        //足りないところから
                        val = need - buffer;
                    }
                    else
                    {
                        val = difference[bringPoint];
                        startCount++;
                    }

                    difference[bringPoint] -= val;
                    if (change[bringPoint] == false)
                    {
                        change[bringPoint] = true;
                        changeCount++;
                    }

                    buffer += val;
                    if (difference[index] + buffer >= 0)
                    {
                        difference[index] += buffer;
                        break;
                    }
                }
            }

            Console.WriteLine(changeCount);
        }
    }
}

using System;

namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            string[] A = Console.ReadLine().Split(' ');
            string[] B = Console.ReadLine().Split(' ');

            int[] a = new int[N];
            int[] b = new int[N];
            int[] r = new int[N];

            Int64 pos = 0, neg = 0;
            int Counter = 0;

            for (int i=0;i<N;i++)
            {
                a[i] = int.Parse(A[i]);
                b[i] = int.Parse(B[i]);

                r[i] = a[i] - b[i];

                if (r[i] >= 0)
                    pos += r[i];
                else
                {
                    neg += r[i];
                    Counter++;
                }
            }

            if(pos + neg < 0)
            {
                Console.WriteLine("-1");
                return;
            }


            while(neg < 0)
            {
                int max = 0;
                int index = 0;
                for(int i=0;i<N;i++)
                {
                    if(r[i] > max)
                    {
                        max = r[i];
                        index = i;
                    }
                }

                Counter++;
                neg += max;
                r[index] = 0;
            }

            Console.Write(Counter.ToString());

        }
    }
