	{
		public void Run() {
			var N = ReadInt();
			var NumsA = ReadIntArray();
			var NumsB = ReadIntArray();
			List<int> posis = new List<int>(N);

			long sumOfNega = 0;
			long sumOfPosi = 0;
			int cntOfNega = 0;
			for (int i = 0; i < N; i++) {
				var diff = NumsA[i] - NumsB[i];
				if (0 <= diff) {
					sumOfPosi += diff;
					posis.Add(diff);
				} else { 
					sumOfNega += diff;
					++cntOfNega;
				}
			}
			// 合格不可？
			if (sumOfNega + sumOfPosi < 0) {
				WriteLine(-1);
				return;
			}
			// 既に合格？
			if (cntOfNega == 0) {
				WriteLine(0);
				return;
