			posis.Sort();
			posis.Reverse();

			// 足りない点数合計(sumOfNega)を満たすまで、
			// diffの大きい方から取得してくる
			int ans = cntOfNega;
			foreach (var posi in posis) {
				++ans;
				sumOfNega += posi;
				if (0 <= sumOfNega)
					break;
			}

			WriteLine(ans);
		}

