namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            var B = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            var difference = new List<long>();
            var sumFlag = (long)0;

            for (int i = 0; i < N; i++)
            {
                var dif = A[i] - B[i];
                difference.Add(dif);
                sumFlag += dif;
            }

            if (sumFlag < 0)
            {
                Console.WriteLine("-1");
                return;
            }

            //昇順ソート
            difference.Sort();

            //変更されたか記録
            var change = new bool[difference.Count];
            for (int i = 0; i < difference.Count; i++)
            {
                change[i] = false;
            }

            var changeCount = 0;
            var startCount = difference.Count;
            for (int index = 0; index < difference.Count; index++)
            {
                //昇順ソートなので0よりでかいのが来たら以降全部でかい => break
                if (difference[index] >= 0)
                {
                    break;
                }

                var need = difference[index] * -1;
                change[index] = true;
                changeCount++;

                var buffer = (long)0;
                for (int bring = startCount; bring < difference.Count; bring++)
                {
                    var bringPoint = difference.Count - bring - 1;

                    //bringPointから持ってくる数 == val
                    var val = (long)0;
                    if (need <= difference[bringPoint])
                    {
                        //足りないところから
                        val = need - buffer;
                    }
                    else
                    {
                        val = difference[bringPoint];
                        startCount++;
                    }

                    difference[bringPoint] -= val;
                    if (change[bringPoint] == false)
                    {
                        change[bringPoint] = true;
                        changeCount++;
                    }

                    buffer += val;
                    if (difference[index] + buffer >= 0)
                    {
                        difference[index] += buffer;
                        break;
                    }
                }
            }

            Console.WriteLine(changeCount);
        }
    }
}

