public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        var dp = new long[N + 1, N + 1];
        for (int i = 0; i <= N; i++)
        {
            for (int j = 0; j <=N; j++)
            {
                dp[i, j] = int.MinValue;
            }
        }

        dp[0, 0] = 0;
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j <= i; j++)
            {
                if (A[i] != B[i])
                {
                    dp[i + 1, j + 1] = Math.Max(dp[i + 1, j + 1], dp[i, j] + (A[i] - B[i]));
                }
                if (A[i] >= B[i])
                {
                    dp[i + 1, j] = Math.Max(dp[i + 1, j], dp[i, j]);
                }
            }
        }

        for (int i = 0; i <= N; i++)
        {
            if (dp[N, i] >= 0)
            {
                Console.WriteLine(i);
                return;
            }
        }
        Console.WriteLine(-1);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
