                return;
            }

            Array.Sort(diff);
            Array.Reverse(diff);
            var d = 0L;

            for (var i = 0; i < N; i++)
            {
                d += diff[i];
                if (d >= sum)
                {
                    Console.WriteLine(count + i + 1);
                    return;
                }
            }

            Console.WriteLine(-1);
        }
    }
