using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
class Program
{
    static void Main(string[] args)
    {
            // 入力
            string[] sS = System.Console.ReadLine().Trim().Split(' ');
            int iN = int.Parse(sS[0]);
            List<long> lstA = new List<long>();
            List<long> lstB = new List<long>();
            sS = System.Console.ReadLine().Trim().Split(' ');
            for (int i = 0; i < sS.Length; i++) { lstA.Add(long.Parse(sS[i])); }
            sS = System.Console.ReadLine().Trim().Split(' ');
            for (int i = 0; i < sS.Length; i++) { lstB.Add(long.Parse(sS[i])); }

            System.Diagnostics.Stopwatch sw = new System.Diagnostics.Stopwatch();
            sw.Start();

            // 解析
            int iOut = 0;
            long lASm = lstA.Sum();
            long lBSm = lstB.Sum();
            if (lASm < lBSm) { iOut = -1; }                                                 // やりくり不可能
            else                                                                            // どうにかやりくり可能
            {
                List<long> lstD = new List<long>();                                         // 不足の情報
                List<long> lstU = new List<long>();                                         // 余裕の情報
                for (int i = 0; i < lstA.Count; i++)
                {
                    if (lstA[i] < lstB[i]) { lstD.Add(lstB[i] - lstA[i]); iOut += 1; }      // 不足情報保持 不足箇所加算
                    else { lstU.Add(lstA[i] - lstB[i]); }                                   // 余裕の情報
                }
                if (iOut > 0)                                                               // 不足箇所があれば以下処理
                {
                    long lDSm = lstD.Sum();                                                 // 不足箇所の不足分合計
                    lstU.Sort();
                    lstU.Reverse();                                                         // 余裕箇所の大きい順に
                    long lUSm = 0L;
                    for (int i = 0; i < lstU.Count; i++)
                    {
                        lUSm += lstU[i];                                                    // 余裕分でまかない
                        iOut += 1;                                                          // まかない数加算
                        if (lUSm >= lDSm) { break; }                                        // まかない完了で終了
                    }
                }
            }

            // 出力
            System.Console.WriteLine("{0}", iOut.ToString().Trim());

            sw.Stop();
#if DEBUG
            Console.WriteLine();
            Console.WriteLine("{0}", sw.Elapsed.ToString());
            Console.WriteLine("続行するには何かキーを押してください．．．");
            Console.ReadKey();
#endif
    }

}

