    var B = Longs;
    if (A.Sum() < B.Sum())
    {
      Put(-1);
      return;
    }
    long sum = 0;
    int cnt = 0;
    var plus = new List<long>();
    for (int i = 0; i < N; ++i)
    {
      long diff = A[i] - B[i];
      if (diff < 0) { sum += -diff; cnt++; }
      else if (diff > 0) plus.Add(diff);
    }
    if (sum == 0)
    {
      Put(0);
      return;
    }
    plus.Sort((a, b) => (int)(b - a));
    int j = 0;
    while (true)
    {
      sum -= plus[j++];
      if (sum <= 0)
      {
        Put(cnt + j);
        return;
      }
    }


  }

