using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class AtCoderA
{
    static void Main()
    {
        var sc = new Scanner();

        long n = sc.NextLong();
        long[] aa = sc.LongArray();
        long[] bb = sc.LongArray();

        List<long> under = new List<long>();
        List<long> over = new List<long>();
        long even = 0;

        for (int i = 0; i < n; i++)
        {
            if (aa[i] > bb[i])
            {
                over.Add(aa[i] - bb[i]);
            }
            else if (aa[i] < bb[i])
            {
                under.Add(bb[i] - aa[i]);
            }
            else
            {
                even++;
            }
        }

        long underSum = under.Sum();
        long underCount = under.Count();

        if (underSum > over.Sum())
        {
            Console.WriteLine(-1);
            return;
        }

        over = over.OrderByDescending(num => num).ToList();

        long answer = underCount;

        if (underSum != 0)
        {
            foreach (var o in over)
            {
                underSum -= o;
                answer++;
                if (underSum <= 0)
                {
                    break;
                }
            }
        }

        Console.WriteLine(answer);
    }

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            while (_index >= _line.Length)
            {
                _line = Console.ReadLine().Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            _line = Console.ReadLine().Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

