namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			int n = int.Parse(Console.ReadLine());
			long[] a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
			long[] b = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

			long[] d = new long[n];
			for (int i = 0; i < n; i++) {
				d[i] = a[i] - b[i];
			}

			Array.Sort(d);
			long msum = d.Where(x => x < 0).Sum() * -1;
			long psum = d.Where(x => x > 0).Sum();
			if (msum > psum) {
				Console.WriteLine(-1);
				return;
			}

			int mcount = d.Where(x => x < 0).Count();
			if (mcount == 0) {
				Console.WriteLine(0);
				return;
			}

			long sum = 0;
			for (int i = n - 1; i >= 0; --i) {
				if (d[i] <= 0) {
					Console.WriteLine(-1);
					return;
				}

				sum += d[i];
				if (sum >= msum) {
					int temp = n - i;
					Console.WriteLine(mcount + temp);
					return;
				}
			}

			Console.WriteLine(-1);
		}
	}
}

