                .Where (i => A[i] < B[i])
                .Sum (i => B[i] - A[i]);
            var Scount = Interval (0, N)
                .Count (i => A[i] < B[i]);
            var dS = Interval (0, N)
                .Where (i => A[i] >= B[i])
                .Select (i => A[i] - B[i])
