namespace atcorder_keyence_2019
{
    struct DIFF_DATA
    {
        public int idx;
        public long diff;
    }

    class Program
    {
        static void Main(string[] args)
        {

            int cnt = int.Parse(Console.ReadLine());
            string[] dataA = Console.ReadLine().Split(' ');
            string[] dataB = Console.ReadLine().Split(' ');

            List<DIFF_DATA> ldd = new List<DIFF_DATA>();
            int changeCnt = 0;
            long changeDiff = 0;
            for (int i = 0; i < cnt; i++)
            {
                DIFF_DATA dd = new DIFF_DATA();

                long ia = int.Parse(dataA[i]);
                long ib = int.Parse(dataB[i]);

                if (ia > ib)
                {
                    dd.idx = i;
                    dd.diff = ia - ib;
                    ldd.Add(dd);
                }
                else if (ia < ib)
                {
                    changeCnt++;
                    changeDiff += ib - ia;
                }
            }

            int ret = 0;

            if (0 < changeCnt)
            {

                //ソート
                ldd.Sort((a, b) => a.diff.CompareTo(b.diff));

                ret = -1;

                for (int i = ldd.Count - 1; 0 <= i; i--)
                {
                    changeDiff -= ldd[i].diff;
                    changeCnt++;
                    if (changeDiff <= 0)
                    {
                        ret = changeCnt;
                        break;
                    }
                }

            }

            Console.WriteLine(ret);
        }
    }
}

using System;

namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            string[] A = Console.ReadLine().Split(' ');
            string[] B = Console.ReadLine().Split(' ');

            int[] a = new int[N];
            int[] b = new int[N];
            int[] r = new int[N];

            int pos = 0, neg = 0;

            for(int i=0;i<N;i++)
            {
                a[i] = int.Parse(A[i]);
                b[i] = int.Parse(B[i]);

                r[i] = b[i] - a[i];

                if (r[i] > 0)
                    pos += r[i];
                else
                    neg += r[i];
            }

            if(pos + neg < 0)
            {
                Console.WriteLine("-1");
                return;
            }

            int Counter = 0;

            while(neg < 0)
            {
                int max = 0;
                int index = 0;
                for(int i=0;i<N;i++)
                {
                    if(r[i] > max)
                    {
                        max = r[i];
                        index = i;
                    }
                }

                Counter++;
                neg += max;
                r[index] = 0;
            }

            Console.Write(Counter.ToString());

        }
    }
}

