namespace Keyence
{
    class C
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            List<long> A = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            List<long> B = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList();
            List<long> D = new List<long>();
            for(int i = 0; i < N; i++)
            {
                D.Add(A[i] - B[i]);
            }
            long Asum = A.Sum();
            long Bsum = B.Sum();

            if (Bsum > Asum)
            {
                Console.WriteLine("-1");
                return;
            }

            D.Sort();
            int numMinus = D.Count(x => x < 0);
            if (numMinus == 0)
            {
                Console.WriteLine("0");
                return;

            }

            long sumMinus = -D.Where(x => x < 0).Sum();

            int counter = 0;
            long sum = 0;
            for(int i = N - 1; i > 0; i--)
            {
                sum += D[i];
                counter++;
                if (sum >= sumMinus) break;
            }

            int numChange = numMinus + counter;
            Console.WriteLine(numChange);

        }
    }
}

