            string[] B = Console.ReadLine().Split(' ');

            int[] a = new int[N];
            int[] b = new int[N];
            int[] r = new int[N];

            Int64 pos = 0, neg = 0;
            int Counter = 0;

            for (int i=0;i<N;i++)
            {
                a[i] = int.Parse(A[i]);
                b[i] = int.Parse(B[i]);

                r[i] = a[i] - b[i];

                if (r[i] >= 0)
                    pos += r[i];
                else
                {
                    neg += r[i];
                    Counter++;
                }
            }

            if(pos + neg < 0)
            {
                Console.WriteLine("-1");
                return;
            }


            while(neg < 0)
            {
                int max = 0;
                int index = 0;
                for(int i=0;i<N;i++)
                {
                    if(r[i] > max)
                    {
                        max = r[i];
                        index = i;
                    }
                }

                Counter++;
                neg += max;
                r[index] = 0;
            }

            Console.Write(Counter.ToString());

        }
    }
