	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
	writer.Flush()
}

func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int, n)
	bb := make([]int, n)

	ab := make(AB, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		bb[i] = getNextInt(scanner)
	}

	for i := 0; i < n; i++ {
		ab[i].c = aa[i] - bb[i]
		ab[i].i = i
	}
	sort.Sort(ab)
	ans := 0
	var horobiyo int64
	for i := 0; i < n && ab[i].c < 0; i++ {
		horobiyo += int64(ab[i].c)
		ans++
	}
	for i := n - 1; i >= 0 && ab[i].c >= 0 && horobiyo < 0; i-- {
		horobiyo += int64(ab[i].c)
		ans++
	}
	if horobiyo < 0 {
		fmt.Fprintln(writer, -1)
		return
	}
	fmt.Fprintln(writer, ans)
}

