type Elem struct {
	A, B, C int
}

type Elems []*Elem

func (e Elems) Len() int {
	return len(e)
}

func (e Elems) Less(i, j int) bool {
	return (e[i].A - e[i].B) < (e[j].A - e[j].B)
}

func (e Elems) Swap(i, j int) {
	e[i], e[j] = e[j], e[i]
}

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	n := nextInt()
	a, b := nextInts(n), nextInts(n)
	elems := make(Elems, n)
	sumA, sumB := 0, 0
	for i := 0; i < n; i++ {
		elems[i] = &Elem{a[i], b[i], a[i]}
		sumA, sumB = sumA+a[i], sumB+b[i]
	}
	sort.Sort(elems)

	if sumA < sumB {
		puts(-1)
		return
	}

	// Cを調整
	for inc, dec := 0, n-1; dec >= 0 && inc < n && inc <= dec; {
		dinc, ddec := elems[inc].B-elems[inc].C, elems[dec].C-elems[dec].B
		// puts(dec, elems[dec], ddec, inc, elems[inc], dinc)
		if dinc <= 0 {
			break
		}
		if dinc == ddec {
			elems[inc].C += dinc
			elems[dec].C -= ddec
			dec--
			inc++
		} else if dinc < ddec {
			elems[inc].C += dinc
			elems[dec].C -= dinc
			inc++
		} else {
			elems[inc].C += ddec
			elems[dec].C -= ddec
			dec--
		}
	}

	ans := 0
	for _, e := range elems {
		if e.A != e.C {
			ans++
		}
	}
	puts(ans)
}

