			margin := A[i] - B[i]
			marginSum += margin
			margins = append(margins, margin)
		}
	}
	if marginSum < needed {
		fmt.Println(-1)
		return
	}
	sort.Sort(sort.Reverse(sort.IntSlice(margins)))
	for needed > 0 {
		needed -= margins[0]
		margins = margins[1:]
		ans++
	}
	fmt.Println(ans)
}

