function solve(N:number,A:number[],B:number[]):number{
    const Dif = A.map((a, i)=>A[i]-B[i]);
    let minus=[];
    let plus=[];
    Dif.forEach((dif,index)=>{
        if(dif<0)minus.push(dif);
        else{
            plus.push(dif);
        }
    })
    let sumOfMinus = minus.reduce((x,y)=>x+y,0);
    plus.sort();
    let ans=minus.length;
    while(true){
        if(sumOfMinus>=0){
            return ans;
        }else{
            if(plus.length>0){
                sumOfMinus+=plus.pop(); //biggest
                ans++;
            }else{
                return -1;
            }
        }
    }
}
