auto solve( long[] as, long[] bs )
{
	auto ans = -1L;

	// asとbsの差を計算
	auto ds = new long[ as.length ];
	auto dt = 0L;
	foreach( ref d, a, b; lockstep( ds, as, bs ) )
	{
		d = a - b;
		dt += d;
	}

	// 後の処理のために降順に並べ替え
	ds.sort!( ( a, b ) => b < a );

	// 差の合計がマイナスだったら無理
	if( dt < 0 ) return -1;

	// 差がマイナスの項目の合計を計算
	auto ms = ds.filter!( ( m ) => m < 0 );
	auto mc = ms.walkLength;
	auto mt = -ms.sum;

	// 差がプラスの項目を値が大きいほうから順にマイナスの項目へ余分を移す
	auto ps = ds.filter!( ( m ) => 0 < m );
	auto pc = 0L;
	auto pt = 0L;
	foreach( p; ps )
	{
		if( mt <= pt ) break;
		pt += p;
		pc++;
	}

	return mc + pc;
}

