auto solve( long[] as, long[] bs )
{
	// 準備度の差を計算
	auto ds = new long[ as.length ];
	auto dt = 0L;
	foreach( ref d, a, b; lockstep( ds, as, bs ) )
	{
		d = a - b;
		dt += d;
	}

	// 差の合計がマイナスだったら絶対不合格
	if( dt < 0 ) return -1;

	// 差がマイナスの試験を集計
	auto ms = ds.filter!( ( d ) => d < 0 );
	auto mc = ms.walkLength;
	auto mt = -ms.sum;

	// 差がマイナスの試験が無かったら元から合格
	if( mc == 0 ) return 0;

	// 差がプラスの試験から差がマイナスの試験へ余分な準備度を移す（準備度が大きい順に使う）
	ds.sort!( ( a, b ) => b < a );
	auto ps = ds.filter!( ( d ) => 0 < d );
	auto pc = 0L;
	auto pt = 0L;
	foreach( p; ps )
	{
		if( mt <= pt ) break;
		pc++;
		pt += p;
	}

	return mc + pc;
}

