        writeln(-1);
        return;
    }

    int ans;
    long less;
    long[] un, ov;

    foreach (i ; 0 .. n) {
        long d = a[i] - b[i];
        if (d < 0) {
            less += -d;
            ans++;
        }
        else if (d > 0) {
            ov ~= d;
        }
    }

    ov.sort!"a > b"();

    foreach (ovi ; ov) {
        if (less <= 0) {
            break;
        }
        ans++;
        less -= ovi;
    }

    writeln(ans);
}







