IMPOSSIBLE = -1


def solve(xs, ys):
    if sum(xs) < sum(ys):
        return IMPOSSIBLE
    n = len(xs)
    ts = [x - y for x, y in zip(xs, ys)]
    da_idxs = sorted(range(n), key=lambda i: ts[i])
    us = ts[:]
    pos_donor = n - 1
    pos_acceptor = 0
    while pos_acceptor < pos_donor:
        acceptor_actidx = da_idxs[pos_acceptor]
        donor_actidx = da_idxs[pos_donor]
        if us[acceptor_actidx] < 0:
            delta = min(-us[acceptor_actidx], us[donor_actidx])
            us[acceptor_actidx] += delta
            us[donor_actidx] -= delta
        if us[donor_actidx] <= 0:
            pos_donor -= 1
        if us[acceptor_actidx] >= 0:
            pos_acceptor += 1
    return sum(t != u for t, u in zip(ts, us))


