import itertools

N = int(input())
A = list(map(int, input().split()))
B = list(map(int, input().split()))

def solve():
  #checks
  if(sum(A)<sum(B)):
    return -1
  if(check(A)):
    return 0
  for i in range(2,N+1):
    for comb in itertools.combinations(range(N), i):
      for replaced in replace(comb):
        temp = A
        for j in range(i):
          temp[comb[j]] = A[replaced[j]]
        if(check(temp)):
          return sum([not(comb[j] == replaced[j]) for j in range(i)])
  return 0

def check(_A):
  return sum([int(_A[i]>=B[i]) for i in range(N)]) == N

def replace(iter):
  return itertools.permutations(iter, len(iter))

print(str(solve()))

