def slv(N, A, B):
    if sum(A) < sum(B):
        return -1

    P = []
    M = []
    for i in range(N):
        d = A[i] - B[i]
        if d > 0:
            P.append(d)
        elif d < 0:
            M.append(d)

    P.sort()
    M.sort()

    c = 0
    ans = 0
    for m in M:
        while -m > c:
            c += P.pop()
            ans += 1
        c += m
        ans += 1

    return ans


