    B = input_int_list()

    if sum(A) < sum(B):
        print(-1)
        return
    plus = []
    minus = []

    # a < b はすべて調整の必要あり
    # a < b の補填は それぞれの b > a のうち b-a が大きいところから貪欲に補填する
    for i in range(n):
        d = B[i] - A[i]
        if d > 0:
