            if charge == 0:
                if heapq:
                    charge = -heapq.heappop(plus)
                    ans += 1
                else:
                    print(-1)
                    return
            if d <= charge:
                charge -= d
                d = 0
            else:
                charge = 0
                d -= charge

    print(len(minus) + ans)
    return


