import sys

def check(n, a, b) :
    p = [] #plus
    z = [] #zero
    m = [] #minus
    for i in range(n) :
        d = a[i] - b[i]
        if d > 0 :
            p.append(d)
        elif d == 0 :
            z.append(d)
        else :
            m.append(d)

    new_p = sorted(p, reverse=True)

    m_sum = sum(m)
    p_sum = sum(p)

    if p_sum + m_sum < 0 :
        return -1

    if len(p) + len(z) == n :
        return 0

    count = 0
    tmp = 0
    for i, ele in enumerate(new_p) :
        count = count + 1
        tmp = tmp + ele

        if tmp + m_sum >= 0 :
            return (count + len(m))


