  for (int i = 0; i < N; ++i)
    cin >> a[i];

  long long b[N];
  for (int i = 0; i < N; ++i)
    cin >> b[i];

  long long diff_total = 0;
  vector<int> indices(N);
  vector<long long> diff(N);
  bool changed[N];
  for (int i = 0; i < N; ++i) {
    diff_total += a[i] - b[i];
    diff[i] = a[i] - b[i];
    indices[i] = i;
    changed[i] = false;
  }

  if (diff_total < 0) {
    cout << -1 << endl;
    return 0;
  }

  sort(diff.begin(), diff.end());

  int last_provider = N - 1;
  int i = 0;
  while (true) {
    if (diff[i] >= 0)
      break;
    if (abs(diff[last_provider]) > abs(diff[i])) {
      diff[last_provider] += diff[i];
      changed[i] = true;
      changed[last_provider] = true;
      ++i;
    } else {
      diff[i] += diff[last_provider];
      diff[last_provider] = 0;
      changed[i] = true;
      changed[last_provider] = true;
      if (diff[i] == 0)
        ++i;
      --last_provider;
    }
  }

  int ret = 0;
  for (int i = 0; i < N; ++i)
    if (changed[i])
      ++ret;

  cout << ret << endl;

  return 0;
}

