fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let n = sc.read();
    let a: Vec<i64> = sc.read_vec(n);
    let b: Vec<i64> = sc.read_vec(n);

    let a_sum = a.iter().sum::<i64>();
    let b_sum = b.iter().sum::<i64>();
    if a_sum < b_sum {
        println!("-1");
        return;
    }

    let mut good = vec![];
    let mut bad = vec![];
    for i in 0..n {
        if a[i] > b[i] {
            good.push((a[i], b[i]));
        } else if a[i] < b[i] {
            bad.push((a[i], b[i]));
        }
    }

    let mut required = bad.iter().map(|&(a, b)| b - a).sum::<i64>();
    good.sort();
    good.reverse();

    let mut used_goods = 0;
    for &(a, b) in good.iter() {
        if required <= 0 {
            break;
        }
        used_goods += 1;
        required -= a - b;
    }

    assert!(required <= 0);
    println!("{}", used_goods + bad.len());
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

