fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();

    let a: Vec<i64> = (0..n)
        .map(|_| iterator.next().unwrap().parse().unwrap())
        .collect();
    let b: Vec<i64> = (0..n)
        .map(|_| iterator.next().unwrap().parse().unwrap())
        .collect();

    let mut d_sum = 0;
    let mut minus_sum = 0;
    let mut count = 0;
    let mut plus_d: Vec<i64> = Vec::new();
    for i in 0..n {
        let d = a[i] - b[i];
        d_sum += d;
        if d < 0 {
            minus_sum += d;
            count += 1;
        } else {
            plus_d.push(d);
        }
    }

    if d_sum < 0 {
        return "-1".to_string();
    }

    plus_d.sort();

    while minus_sum < 0 {
        let d = plus_d.pop().unwrap();
        minus_sum += d;
        count += 1;
    }

    return count.to_string();
}

