        diff[i] = (an[i] as isize - bn[i] as isize).abs() as usize;
    }

    diff.sort();
    diff.reverse();

    let mut cnt = 0;
    let mut sum: isize = 0;

    for i in 0..n {
        if an[i] < bn[i] {
            cnt += 1;
            sum += (bn[i] - an[i]) as isize;
        }
    }

    let mut idx = 0;
    while sum > 0 {
        sum -= diff[idx] as isize;
        idx += 1;
    }

    println!("{}", idx + cnt);
}


