fn solve() {
    input!{
        N:usize,
        a:[i64;N],
        b:[i64;N],
    }
    // aがどれだけ浮いてるか？
    let mut diff=vec![];
    for i in 0..N {
        diff.push(a[i]-b[i]);
    }
    let mut cnt=0;
    let mut lack=0;
    let mut diff_sum=0;
    for i in 0..N {
        diff_sum+=diff[i];
        // 沈んでるやつは変わること確定
        if diff[i]<0 {
            lack+=-diff[i];
            cnt+=1;
        }
    }
    if diff_sum < 0 {
        println!("-1");
        return
    }

    // 浮いてるやつから沈み分をかき集める
    diff.sort();diff.reverse();
    let mut i=0;
    while lack>0 {
        // 正の部分を足せば充足するはず
        assert!(diff[i]>0);
        lack-=diff[i];
        i+=1;
    }
    cnt+=i;

    println!("{}",cnt);
}

