fn main() {
    let stdin = stdin();
    let mut reader = StdinReader::new(stdin.lock());
    let n = reader.u();
    let a = reader.uv(n);
    let b = reader.uv(n);
    let asum: usize = a.iter().sum();
    let bsum: usize = b.iter().sum();
    if bsum > asum {
        println!("{}", -1);
        return;
    }

    let mut losesum = 0;
    let mut lose = 0;
    let mut win = BTreeMap::new();
    for i in 0..n {
        if a[i] > b[i] {
            *win.entry(Reverse(a[i] - b[i])).or_insert(0) += 1;
        }
        if a[i] < b[i] {
            lose += 1;
            losesum += b[i] - a[i];
        }
    }
    if lose == 0 {
        println!("{}", 0);
        return;
    }
    let mut ans = lose;
    for (Reverse(k), count) in win {
        if k * count < losesum {
            ans += count;
            losesum -= k * count;
        } else {
            ans += (losesum + k - 1) / k;
            break;
        }
    }
    println!("{}", ans);
}

