fn read_as_vec<T>() -> Vec<T>
where T: FromStr, <T as FromStr>::Err : Debug{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().split_whitespace().map(|c| T::from_str(c).unwrap()).collect()
}

fn main(){
    let n = read_as_vec::<i32>()[0];
    let a = read_as_vec::<i32>();
    let b = read_as_vec::<i32>();
    let mut ans: i32 = 0;
    let mut ab: Vec<(i32, i32)> = a.into_iter().zip(b.into_iter()).collect();
    ab.sort_by_key(|(a, b)| b-a);
    for (now, target) in &ab{
        if now != target{
            ans += 1;
        }
    }

    let mut changed_sum: i32 = ab.iter().map(|(x, _)|*x).sum::<i32>() - ab.iter().map(|(_, y)| *y).sum::<i32>();


    if changed_sum < 0{
        println!("-1");
        return;
    }

    for (now, target) in &ab{
        if now <= target{
            continue;
        }
        //always now > target
        changed_sum -= now - target;

        //finish
        if changed_sum < 0{
            println!("{}", ans);
            return;
        }
        ans -= 1;
    }

    println!("0");

}

