//https://qiita.com/tubo28/items/e6076e9040da57368845
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main(){
    let n: usize = read();
    let a: Vec<i64> = (0..n).map(|_| read()).collect();
    let b: Vec<i64> = (0..n).map(|_| read()).collect();

    let a_sum:i64 = a.iter().sum();
    let b_sum:i64 = b.iter().sum();

    let mut OKs:Vec<i64> = Vec::new(); 
    let mut NGs:i64 = 0;
    let mut change_num:usize = 0;

    if a_sum >= b_sum {
        for i in 0..n{
