fn main() {
    input! {
        n: usize,
        mut a: [i64; n],
        mut b: [i64; n],
    }
    let mut g_n = vec![];
    let mut g_p = vec![];
    for i in 0..n {
        let acc = a[i] - b[i];
        if acc < 0 {
            g_n.push(acc);
        } else {
            g_p.push(acc);
        }
    }

    if g_n.iter().sum::<i64>() + g_p.iter().sum::<i64>() < 0 {
        return println!("-1");
    }

    g_n.sort();
    g_n.reverse();

    g_p.sort();
    g_p.reverse();

    let mut cnt = g_n.len();
    let mut cur = 0;
    let mut used = vec![false; n];
    while let Some(v) = g_n.pop() {
        let mut v_ = v.clone();
        while v_ < 0 && cur < n {
            if v_.abs() <= g_p[cur] {
                if used[cur] == false {
                    cnt += 1;
                    used[cur] = true
                }
                g_p[cur] += v_;
                v_ = 0;
            } else {
                v_ += g_p[cur];
                if used[cur] == false {
                    cnt += 1;
                    used[cur] = true;
                }
                cur += 1;
            }
        }
    }

    println!("{}", cnt);
}

