use std::io::*;
use std::str::FromStr;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let a = i.read_vec::<usize>(n);
    let b = i.read_vec::<usize>(n);

    if let Some(r) = solve(&a, &b) {
        writeln!(o, "{}", r).unwrap();
    } else {
        writeln!(o, "{}", -1).unwrap();
    }
}
fn solve(a: &[usize], b: &[usize]) -> Option<usize> {
    let mut c_need = 0;
    let mut c_extra = Vec::new();
    let mut result = 0;
    for i in 0..a.len() {
        let a = a[i];
        let b = b[i];
        if a < b {
            c_need += b - a;
            result += 1;
        }
        if a > b {
            c_extra.push(a - b);
        }
    }
    c_extra.sort();
    let mut c = 0;
    while c < c_need {
        if let Some(c_extra) = c_extra.pop() {
            c += c_extra;
            result += 1;
        } else {
            return None;
        }
    }
    Some(result)
}

