fn main() {
    input! {
        n: usize,
        xs: [i64; n],
        ys: [i64; n],
    };

    let diffs = xs
        .into_iter()
        .zip(ys.into_iter())
        .map(|(x, y)| x - y)
        .collect::<Vec<_>>();

    let mut affords = diffs.iter().filter(|&&d| 0 < d).collect::<Vec<_>>();
    affords.sort();
    let mut afford_sums = vec![0; n + 1];
    for (i, afford) in affords.into_iter().rev().enumerate() {
        afford_sums[i + 1] = afford_sums[i] + afford;
    }
