    let ans = afford_sums
        .iter()
        .enumerate()
        .find(|&(_, &afford_sum)| -short_sum <= afford_sum)
        .map(|(i, _)| i as i64)
        .map(|cnt| cnt + diffs.iter().filter(|&&d| d < 0).count() as i64)
        .unwrap_or(-1);
    println!("{}", ans);
}

