fn decode(v: &[u8]) -> Vec<u8> {
    let mut tbl = [0; 256];
    for i in 0..85 { tbl[TBL[i] as usize] = i as u32; }
    let mut v_vec = v.to_vec();
    let padding = (5 - v.len() % 5) % 5;
    v_vec.extend(vec![b'~'; padding]);
    let mut ret = vec![0u8;v_vec.len() / 5 * 4];
    for (i, ck) in v_vec.chunks(5).enumerate() {
        let mut acc = 0;
        for &c in ck {
            acc = acc * 85 + tbl[c as usize];
        }
        ret[i * 4..(i + 1) * 4].copy_from_slice(&unsafe{std::mem::transmute::<u32, [u8; 4]>(acc.to_be())});
    }
    let l = ret.len();
    ret.resize(l - padding, 0u8);
    ret
}

