use proconio::input;

fn main() {
    input! {
        n: usize,
        aa: [isize; n],
        bb: [isize; n],
    }

    let mut positives = vec![];
    let mut negatives = vec![];

    for (a, b) in aa.into_iter().zip(bb.into_iter()) {
        let diff = a - b;
        if diff >= 0 {
            positives.push(diff);
        } else {
            negatives.push(diff);
        }
    }

    if negatives.len() == 0 {
        println!("0");
        return;
    }

    let mut count = negatives.len();

    let negative_sum = negatives.into_iter().sum::<isize>();
    let mut positive_sum = 0;

    positives.sort();
    positives.reverse();

    for positive in positives {
        positive_sum += positive;
        count += 1;

        if positive_sum + negative_sum >= 0 {
            println!("{}", count);
            return;
        }
    }

    println!("-1");
}

