fn main() {
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n]
    }

    if a.iter().sum::<i64>() < b.iter().sum::<i64>() {
        println!("-1");
        return;
    }

    let mut pos = Vec::new();
    let mut neg = Vec::new();

    for k in (0..n).filter(|x| a[*x] != b[*x]).map(|x| a[x] - b[x]) {
        if k > 0 {
            pos.push(k);
        }
        if k < 0 {
            neg.push(k);
        }
    }

    pos.sort();
    pos.reverse();
    neg.sort();

    let mut pl = 0;
    let mut ng = 0;
    let mut stock = 0;

    loop {
        if ng >= neg.len() {
            break;
        } else {
            if stock >= -neg[ng] {
                stock -= -neg[ng];
                ng += 1;
            } else {
                stock += pos[pl];
                pl += 1;
                stock -= -neg[ng];
                ng += 1;
            }
        }
    }

    // dbg!(pl, ng);
    println!("{}", pl + ng);
}

