    let mut plus = BinaryHeap::new();
    let mut minus = 0;

    for i in 0..n {
        let buf = a[i] - b[i];
        if buf < 0 {
            minus += buf;
        } else {
            plus.push(buf);
        }
    }

    while minus < 0 {
        minus += plus.pop().unwrap();
    }
    println!("{}", n - plus.len());
}

