                        }
                        None => {
                            buf.extend_from_slice(available);
                            (false, available.len())
                        }
                    }
                };
                r.consume(used);
                read += used;
                if done || used == 0 {
                    return Ok(read);
                }
            }
        }

        pub struct InputReader<R: BufRead> {
            reader: R,
            buf: Vec<u8>,
        }

        impl<R: BufRead> InputReader<R> {
            pub fn new(reader: R) -> InputReader<R> {
                InputReader {
                    reader: reader,
                    buf: Vec::<u8>::new(),
                }
            }

            pub fn read_word(&mut self) {
                read_word(&mut self.reader, &mut self.buf);
            }

            pub fn read<T>(&mut self) -> T
                where T: FromStr,
                      T::Err: Debug
            {
                self.buf.clear();
                self.read_word();
                from_utf8(&self.buf).unwrap().trim().parse().unwrap()
            }
        }
    }
}

use std::io::BufRead;
use std::str::FromStr;
use std::fmt;
use std::str;
use std::cmp::min;

struct InputScanner<R: BufRead> {
    reader: R,
    buf: Vec<u8>, // Should never be empty
    pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}

impl<R: BufRead> InputScanner<R> {
    fn new(reader: R, capacity: usize) -> Self {
        InputScanner {
            reader: reader,
            buf: Vec::with_capacity(capacity),
            pos: 0,
        }
    }

    #[inline]
    fn next<T: FromStr>(&mut self) -> T
    where
        T::Err: fmt::Debug,
    {
        if self.buf.is_empty() {
            self._read_next_line();
        }
        let mut start = None;
        loop {
            match (self.buf[self.pos], start.is_some()) {
                (b' ', true) | (b'\n', true) => break,
                (_, true) | (b' ', false) => self.pos += 1,
                (b'\n', false) => self._read_next_line(),
                (_, false) => start = Some(self.pos),
            }
        }
        let target = &self.buf[start.unwrap()..self.pos];
        unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
    }

    #[inline]
    fn _read_next_line(&mut self) {
        self.pos = 0;
        self.buf.clear();
        if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
            panic!("Reached EOF");
        }
    }
}

fn main() {
    let stdin = std::io::stdin();
    let mut scanner = InputScanner::new(stdin.lock(), 1200000);
    let n: i32 = scanner.next();
    let a: Vec<i32> = (0..n).map(|_| scanner.next()).collect();
    let b: Vec<i32> = (0..n).map(|_| scanner.next()).collect();

    let mut c: Vec<i32> = a.iter().zip(b.iter()).map(|(x, y)| x - y).collect();
    c.sort_unstable();
    let mut p = 0;
    let mut q = c.len() - 1;
    let mut p_moved = 0;
    let mut q_moved = 0;
    while p < q && c[p] < 0 && c[q] > 0 {
        let mv = min(-c[p], c[q]);
        c[p] += mv;
        c[q] -= mv;
        if mv > 0 {
            p_moved = p + 1;
            q_moved = c.len() - q;
        }
        if c[q] == 0 {
            q -= 1;
        }
        if c[p] == 0 {
            p += 1;
        }
    }
    let res: i32 = if c[p] < 0 {
        -1
    } else {
        (q_moved + p_moved) as i32
    };
    println!("{}", res)
}
